/**
 * The DOCUMENT operations: `init`, `list`, `show`.
 *
 * Appending each to the table in `./index.ts` is the ONLY edit that makes it
 * appear in the CLI tree, the manifest, and `--help` — no second registration, no
 * hand-written manifest row, no description corpus.
 *
 * ## The shared doc-path field
 *
 * All three take the same optional `file` field with the same description, built
 * by one {@link docPathField} factory rather than restated three times. The
 * resolution rule itself is a single exported constant in `store.ts`, quoted here,
 * so `--help`, the manifest, and every error message that mentions precedence all
 * cite the same string.
 *
 * ## Reads disclose, they do not gate
 *
 * `list` and `show` both surface the load's `diagnostics` on their payload. That
 * is the V27 disclosure reaching an agent: a document carrying an unknown
 * top-level key or a hand-edited sentence says so on every read, at `info`
 * severity, so the exit code stays 0 and the fact is nonetheless visible. A
 * disclosure an agent never sees is not a disclosure.
 */

import { dirname, join, relative, resolve, sep } from 'node:path'
import { Effect, Schema } from 'effect'
import { INTENT_VERSION, POLICY_VERSION } from '../../domain/anchor/anchor.ts'
import { CONFIG_FILE_NAME, skeletonConfig } from '../../domain/config/config.ts'
import {
  DOC_VERSION,
  type DocumentDiagnostic,
  type DocVersion,
  emptyDocument,
  type Requirement,
  V4_EXPERIMENTAL_STATEMENT,
} from '../../domain/requirements/document.ts'
import { requireRequirement } from '../../domain/requirements/resolve.ts'
import { DOC_PATH_CONVENTION, DocPath, DocStore } from '../../ports/doc-store.ts'
import { ErrConfigInvalid, ErrDocExists, type ErrNotFound } from '../../ports/errors.ts'
import { ok } from '../runtime/envelope.ts'
import { defineOperation } from '../runtime/operation.ts'

// ---------------------------------------------------------------------------
// The shared doc-path input field
// ---------------------------------------------------------------------------

/**
 * The optional document-path field every document operation takes.
 *
 * `NullOr` + a `null` default rather than `optionalKey`, because this field
 * crosses the CLI boundary: an unsupplied positional argument or flag arrives as
 * "nothing", and `null` is the one JSON value that says so on a wire an agent may
 * also be writing by hand. Inside the handler it goes straight to
 * `DocPath.resolve`, which treats `null` and `undefined` identically — so the
 * boundary convention costs no branch at the point of use.
 *
 * The annotation carries the DEFAULT explicitly alongside the decoding default,
 * because `withDecodingDefaultKey` does not emit one into the JSON Schema and
 * `defineOperation` fails construction on an optional field the manifest cannot
 * describe.
 */
const docPathField = (verb: string) =>
  Schema.withDecodingDefaultKey<Schema.optionalKey<Schema.NullOr<Schema.String>>>(
    Effect.succeed(null),
  )(
    Schema.optionalKey(
      Schema.NullOr(Schema.String).annotate({
        default: null,
        description: [
          `Path to the requirements document to ${verb}.`,
          DOC_PATH_CONVENTION,
          'Example: ./requirements.json',
        ].join('\n'),
      }),
    ),
  )

// ---------------------------------------------------------------------------
// init
// ---------------------------------------------------------------------------

/** What `init` reports. `split` is present exactly when `--split` wrote the anchors. */
interface InitPayload {
  readonly path: string
  readonly docVersion: DocVersion
  /** Whether the document was written (a kept document under --split is not). */
  readonly created: boolean
  readonly overwritten: boolean
  readonly requirements: number
  readonly split?: { readonly config: string; readonly intent: string; readonly policy: string }
  /**
   * Present exactly when `split` is: what this release does with the intent and policy it just
   * wrote ({@link V4_EXPERIMENTAL_STATEMENT}). The config's pins are enforced, so it is not
   * covered by the note.
   */
  readonly anchorsNote?: string
}

/** The split intent file's name, beside the document. */
const SPLIT_INTENT_FILE = 'intent.json'

/** The split policy file's name, beside the document. */
const SPLIT_POLICY_FILE = 'policy.json'

/** Pretty JSON with a trailing newline, the store's on-disk shape for a document too. */
const jsonText = (value: unknown): string => `${JSON.stringify(value, null, 2)}\n`

/** `to` relative to `fromDir`, with `/` separators, as a config names a file. */
const relativeTo = (fromDir: string, to: string): string =>
  relative(resolve(fromDir), resolve(to)).split(sep).join('/')

/**
 * `init --split`: the document (kept when it exists), plus skeleton intent and policy files and
 * the pinned config that names them.
 *
 * ## Write-safety
 *
 * The three anchor files are owner-authored and CODEOWNED, so none is ever overwritten. Every
 * target is checked BEFORE anything is written, so a refusal writes nothing at all, and each
 * is then written with an exclusive create, so a file that appears between the check and the
 * write is refused rather than clobbered.
 */
const initSplit = (path: string, force: boolean) =>
  Effect.gen(function* () {
    const store = yield* DocStore
    const docExists = yield* store.exists(path)
    const writeDocument = !docExists || force

    // A kept document must not already carry the anchors inline: a split copy would make two.
    const kept = writeDocument ? undefined : (yield* store.load(path)).document
    const inline = (['intent', 'policy'] as const).filter((key) => kept?.[key] !== undefined)
    if (inline.length > 0) {
      return yield* Effect.fail(
        new ErrConfigInvalid({
          error: `${path} already carries an inline ${inline.join(' and ')}; init --split would write a second copy.`,
          suggestions: [
            `Keep the inline ${inline.join(' and ')}, and run \`symspec init\` without --split.`,
            'Nothing was written.',
          ],
        }),
      )
    }

    // Real paths throughout, so the names the config records resolve from where it is written.
    const location = yield* store.configPath(path)
    const configFile = location.path
    const intentFile = join(dirname(location.document), SPLIT_INTENT_FILE)
    const policyFile = join(dirname(location.document), SPLIT_POLICY_FILE)
    const targets = [intentFile, policyFile, configFile]
    const existing: string[] = []
    for (const target of targets) if (yield* store.exists(target)) existing.push(target)
    if (existing.length > 0) {
      return yield* Effect.fail(
        new ErrDocExists({
          error: `init --split refused: ${existing.join(', ')} already ${existing.length === 1 ? 'exists' : 'exist'}. It never overwrites an intent, a policy or a config, even with --force.`,
          suggestions: [
            'Nothing was written, and every existing file was left intact.',
            'Edit the existing files by hand, or move them aside and re-run.',
          ],
          repair: { ops: [], commands: existing.map((f) => `cat ${f}`) },
        }),
      )
    }

    const configDir = dirname(configFile)
    yield* store.create(intentFile, jsonText({ intentVersion: INTENT_VERSION, items: [] }))
    yield* store.create(
      policyFile,
      jsonText({ policyVersion: POLICY_VERSION, levels: [], assign: {} }),
    )
    yield* store.create(
      configFile,
      jsonText(
        skeletonConfig({
          document: relativeTo(configDir, location.document),
          intent: relativeTo(configDir, intentFile),
          policy: relativeTo(configDir, policyFile),
        }),
      ),
    )
    const document = writeDocument ? emptyDocument() : (kept ?? emptyDocument())
    if (writeDocument) yield* store.save(path, { document })

    return ok<'init', InitPayload>('init', {
      path,
      docVersion: document.docVersion,
      created: writeDocument,
      overwritten: docExists && force,
      requirements: Object.keys(document.requirements).length,
      split: { config: configFile, intent: intentFile, policy: policyFile },
      anchorsNote: `${SPLIT_INTENT_FILE} and ${SPLIT_POLICY_FILE}: ${V4_EXPERIMENTAL_STATEMENT}`,
    })
  })

/**
 * `init` — create an empty v3 document.
 *
 * ## It REFUSES to overwrite, and that is the whole design
 *
 * A requirements document is hand-authored work; `init` clobbering one would be
 * unrecoverable. So an existing file at the resolved path is `ERR_DOC_EXISTS` —
 * whose catalog text already promises "the existing file is left intact" — and
 * `--force` is the explicit opt-in. Refusing by default is not caution, it is the
 * only behavior that lets an agent call `init` speculatively (to make sure a
 * document exists) without risking the document it was about to read.
 *
 * The check is a genuine TOCTOU race in principle — the file could appear between
 * the `exists` and the `save`. It is not worth closing here: the failure mode is
 * "an agent's own concurrent init overwrote its own empty document with another
 * empty document", which is harmless, and closing it would mean an exclusive-create
 * primitive the atomic-rename write deliberately does not use.
 */
export const initOp = defineOperation({
  name: 'init',
  summary: 'Create an empty requirements document at the resolved path',
  type: 'init',
  input: Schema.Struct({
    file: docPathField('create'),
    force: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: [
          'Overwrite an existing document at the resolved path.',
          'Without this, an existing file is an ERR_DOC_EXISTS failure and is left completely intact —',
          'so `init` is safe to call speculatively against a document you were about to read.',
          'It never applies to the files --split writes.',
        ].join('\n'),
      }),
    ),
    split: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: [
          `Also write the anchors as separate files: skeleton \`${SPLIT_INTENT_FILE}\` and \`${SPLIT_POLICY_FILE}\` beside the`,
          `document, and a \`${CONFIG_FILE_NAME}\` that names them and pins every run knob at its default.`,
          'The config goes to its default location: the toplevel `git rev-parse --show-toplevel` prints',
          'for the document`s real directory, or that directory when git names no repository there.',
          '`check` reads it from there unless --config or SYMSPEC_CONFIG names another, and a run below',
          'any pin is demoted `run-weakened`.',
          `The intent and policy files: ${V4_EXPERIMENTAL_STATEMENT}`,
          'An existing document is kept, not recreated (unless --force). The three new files are NEVER',
          'overwritten, --force or not: if any exists the command writes nothing and fails with',
          'ERR_DOC_EXISTS, because an owner writes these, not the tool. A document that already carries',
          'an inline intent or policy is refused with ERR_CONFIG_INVALID, since a split copy would make two.',
        ].join('\n'),
      }),
    ),
  }),
  handler: (input) =>
    Effect.gen(function* () {
      const docPath = yield* DocPath
      const store = yield* DocStore
      const path = docPath.resolve(input.file)

      if (input.split) return yield* initSplit(path, input.force)

      if (!input.force && (yield* store.exists(path))) {
        return yield* Effect.fail(
          new ErrDocExists({
            error: `A document already exists at ${path}; init refused to overwrite it.`,
            suggestions: [
              'Pass --force to recreate it, or choose a different path.',
              'The existing file was NOT modified.',
              `Run \`symspec list ${path}\` to see what is in it.`,
            ],
            repair: { ops: [], commands: [`symspec list ${path}`] },
          }),
        )
      }

      const document = emptyDocument()
      yield* store.save(path, { document })
      return ok<'init', InitPayload>('init', {
        path,
        docVersion: DOC_VERSION,
        created: true,
        overwritten: input.force,
        requirements: 0,
      })
    }),
})

// ---------------------------------------------------------------------------
// list
// ---------------------------------------------------------------------------

/**
 * One row of `list` output: enough to identify and triage a requirement without
 * fetching it, and no more.
 *
 * Deliberately NOT the whole requirement. `list` over a 42-requirement document
 * is the call an agent makes to ORIENT, and returning every field would make it as
 * expensive as reading the file — which the agent could have done itself. `sentence`
 * is included because it is the one field that makes a row humanly identifiable;
 * everything else here is a handle or a triage axis.
 */
interface ListRow {
  readonly id: string
  readonly key?: string
  readonly patternType: string
  readonly priority: string
  readonly status: string
  readonly sentence: string
}

/** Project a requirement onto its list row, omitting an absent key rather than
 * emitting `null` — the same absence-is-absence rule the schema follows. */
const listRow = (r: Requirement): ListRow => ({
  id: r.id,
  ...(r.key !== undefined ? { key: r.key } : {}),
  patternType: r.patternType,
  priority: r.priority,
  status: r.status,
  sentence: r.sentence,
})

/**
 * `list` — every requirement's handles and triage axes, plus the document's
 * summary counts.
 *
 * Rows are sorted by KEY where present (keys are what a human reads and reasons
 * about), then by UUID for keyless requirements, so output is deterministic across
 * runs and diffable between them. A document mixing keyed and keyless requirements
 * — both hex-bonk fixtures do, one way or the other — gets a stable, readable
 * order rather than whatever the map iteration happened to produce.
 */
export const listOp = defineOperation({
  name: 'list',
  summary: 'List every requirement in the document with its key, UUID, and canonical sentence',
  type: 'list',
  input: Schema.Struct({ file: docPathField('read') }),
  handler: (input) =>
    Effect.gen(function* () {
      const docPath = yield* DocPath
      const store = yield* DocStore
      const path = docPath.resolve(input.file)
      const loaded = yield* store.load(path)
      const doc = loaded.document

      const rows = Object.values(doc.requirements)
        .map(listRow)
        .sort((a, b) => {
          // Keyed requirements first, in key order; then keyless, in UUID order.
          // Two keyless rows compare by id, two keyed rows by key, and a keyed row
          // always precedes a keyless one.
          if (a.key !== undefined && b.key !== undefined) return a.key.localeCompare(b.key)
          if (a.key !== undefined) return -1
          if (b.key !== undefined) return 1
          return a.id.localeCompare(b.id)
        })

      return ok('list', {
        path,
        docVersion: doc.docVersion,
        count: rows.length,
        requirements: rows,
        counts: {
          edges: countEdges(doc.requirements),
          glossary: doc.glossary.length,
          antonyms: doc.antonyms.length,
          waivers: doc.waivers.length,
          stateVariables: doc.stateModel.variables.length,
        },
        diagnostics: loaded.diagnostics satisfies readonly DocumentDiagnostic[],
      })
    }),
})

/** Total outbound edges across every relation — the one aggregate that tells an
 * agent whether a document has a graph at all. */
const countEdges = (requirements: Readonly<Record<string, Requirement>>): number => {
  let total = 0
  for (const r of Object.values(requirements)) {
    total += r.derives.length + r.satisfies.length + r.verifies.length + r.refines.length
  }
  return total
}

// ---------------------------------------------------------------------------
// show
// ---------------------------------------------------------------------------

/**
 * `show <ref>` — one requirement in full, addressed by UUID or stable key.
 *
 * Resolution goes through {@link requireRequirement}, the single chokepoint, so
 * `show` accepts a key for free and a miss produces `ERR_NOT_FOUND` with
 * did-you-mean suggestions and a runnable repair command. Nothing about key
 * handling lives in this operation, which is the point: the next ref-taking
 * operation gets the same behavior by calling the same guard, and cannot get it
 * subtly different.
 *
 * The payload includes `resolvedFrom` — the raw ref the caller passed — alongside
 * the requirement's own `id`. An agent that resolved by key then wants to write an
 * edge needs the UUID, and making the mapping explicit in the response saves it a
 * second lookup and stops it from persisting the key by mistake.
 */
export const showOp = defineOperation({
  name: 'show',
  summary: 'Show one requirement in full, addressed by its stable key or its UUID',
  type: 'requirement',
  input: Schema.Struct({
    ref: Schema.String.annotate({
      description: [
        'The requirement to show, as its stable key (e.g. TX-B6, G1) OR its UUID.',
        'Tried as a UUID first, then as a key, so both spellings work everywhere a ref is accepted.',
      ].join('\n'),
    }),
    file: docPathField('read'),
  }),
  handler: (input) =>
    Effect.gen(function* () {
      const docPath = yield* DocPath
      const store = yield* DocStore
      const path = docPath.resolve(input.file)
      const loaded = yield* store.load(path)

      const found = requireRequirement(loaded.document, input.ref)
      if (isNotFound(found)) return yield* Effect.fail(found)

      return ok('requirement', {
        path,
        resolvedFrom: input.ref,
        requirement: found,
        diagnostics: loaded.diagnostics satisfies readonly DocumentDiagnostic[],
      })
    }),
})

/**
 * Narrow `requireRequirement`'s return to its failure branch.
 *
 * `Requirement | ErrNotFound` needs a discriminator, and `_tag` is the honest one:
 * it is the ERR_* class's own tag, so this cannot drift from the catalog. Checking
 * for the tag (rather than for the absence of a requirement field) also means a
 * future requirement field named `_tag` would be a compile error here instead of a
 * silent misclassification.
 */
const isNotFound = (value: Requirement | ErrNotFound): value is ErrNotFound =>
  '_tag' in value && value._tag === 'ERR_NOT_FOUND'

/**
 * The ONE set of write-time fences every fold of a document runs under.
 *
 * `foldOps` without options is a fold with no fences: phrases are trimmed rather than
 * normalized, and no antonym, term, or glossary write is validated. That default is right for
 * a caller with no engine in its load graph and wrong for anything that writes or measures a
 * document an agent can produce. So this module is the single source for three callers:
 *
 * - `apply` and every single-op mutation (`./mutation.ts`), the write path;
 * - `import` (`./import.ts`), whose side-table records (glossary, antonym, waiver) are folded
 *   through the same `applyOp`, so a v4 stream cannot commit a record `apply` would refuse;
 * - the gaming harness (`src/testing/gaming.ts`), which receives it through its wiring, because
 *   `testing/` may not import `app/`. A harness that folds a move with fewer fences than
 *   `apply` measures escapes an agent cannot actually take.
 *
 * A new write-time validator goes here, and all three callers inherit it.
 */

import { ANTONYM_INDEX, buildAntonymIndexWithDoc } from '../../domain/engine/formal/antonyms.ts'
import {
  glossaryContraries,
  glossaryIndex,
  normalize,
  termIndex,
} from '../../domain/engine/formal/atomize.ts'
import { ESTABLISH_VERBS } from '../../domain/engine/formal/guard-implication.ts'
import { deInflectHead } from '../../domain/engine/formal/lemma.ts'
import type { MutateOptions } from '../../domain/requirements/mutate.ts'
import { findingClassOf, WAIVABILITY } from '../../domain/waivability.ts'

/**
 * The mutation-fold options: the injected normalizer and every write-time validator.
 *
 * `domain/requirements/mutate.ts` cannot import the transplanted formal tier — the dependency
 * runs the other way, and a cycle would put the atomizer in the load graph of every document
 * read. So the functions that need it are injected HERE, which is the lowest layer that
 * legitimately knows about both.
 */
export const MUTATE_OPTIONS: MutateOptions = {
  /**
   * The waivability policy (spec 007 AC-5-6), read off the published class table: a `never`
   * class (verdict, disclosure, triage, hygiene, anchor) is refused in every scope, a code no
   * catalog publishes has no class and is refused, and a `scoped` class (wording, structural)
   * is accepted only over named requirements, stored with the hash of their current text.
   * Every write channel folds under these options, so `apply`, `symspec waive` and `import`
   * refuse the same waivers, and `compat.ts` holds a stored waiver to the same table at check.
   */
  waiverPolicy: (code) => {
    const cls = findingClassOf(code)
    return cls === undefined ? undefined : { class: cls, waivable: WAIVABILITY[cls] }
  },
  // The atomizer's own normalizer, so a committed antonym head is EXACTLY the key the
  // atomizer looks up. Storing "Open" where the atomizer looks up "open" would make
  // the committed pair silently inert — a decision recorded and not applied.
  normalizeHead: normalize,
  /**
   * The false-contradiction guard, and the reason it belongs at WRITE time.
   *
   * An antonym is the one committed record whose wrong value MANUFACTURES a conflict
   * rather than merely masking one. `buildAntonymIndexWithDoc` THROWS on an odd
   * polarity cycle (asserting a↔b when a and b already resolve to the same polarity
   * through the seed classes), and catching it here turns that into a clean
   * `ERR_USAGE` — which is what keeps the CHECK path throw-free. A hand-edited bad
   * document falls back to seed-only rather than crashing a verdict.
   */
  validateAntonyms: (pairs) => {
    try {
      buildAntonymIndexWithDoc(pairs.map((p) => [normalize(p.a), normalize(p.b)] as const))
      return undefined
    } catch (cause) {
      return cause instanceof Error ? cause.message : String(cause)
    }
  },
  /**
   * The OTHER false-contradiction guard: terms are for nouns, enforced rather than documented.
   *
   * A term is substituted inside every slot body, so one containing a verb reaches the response
   * head — and that desyncs two pipelines which must agree. `guard-implication` decides whether
   * a response ESTABLISHES a state by parsing the raw text against `ESTABLISH_VERBS`; the
   * bridge's polarity comes from the full `atomize`, which sees the substitution. Rewrite a head
   * into an antonym class and the bridge is still recognised while its polarity flips, so it
   * asserts the negation of what the document says. The inert-drop downstream compares atom
   * NAMES, not polarity, so it does not catch it: the inverted implication joins the whole-spec
   * conjunction and can make a group UNSAT that the document never entailed. Error severity,
   * and the tool's own doing.
   *
   * Both lexicons are consulted per TOKEN, because the substitution is per token — a term
   * `close the vault` would reach the head just as `close` does. Refusing at write time is what
   * keeps the check path free of "this table was incoherent" branches, exactly as above.
   */
  validateTerms: (canonical, alias) => {
    // De-inflected, because `atomize` de-inflects the head before probing: a raw-token check
    // accepts `revokes` while the atomizer reads `revoke`, and that gap was a verified
    // fabrication. Defense in depth only — the SOUNDNESS guarantee is the check-time drop in
    // `guard-implication.ts`, because no write-time fence can see a doc antonym committed
    // afterwards, nor a two-token head formed by joining a canonical to the tokens beside it.
    const offending = [...canonical.split(/[\s_]+/), ...alias.split(/[\s_]+/)]
      .filter((token) => token.length > 0)
      .find((token) => {
        const head = deInflectHead(token)
        return (
          ANTONYM_INDEX.has(token) ||
          ANTONYM_INDEX.has(head) ||
          ESTABLISH_VERBS.has(token) ||
          ESTABLISH_VERBS.has(head)
        )
      })
    if (offending === undefined) return undefined
    return (
      `"${offending}" is a verb the formal tier reads — the antonym table or the ` +
      'state-bridge lexicon — and substituting one inside a body moves the polarity the solver ' +
      'computes without moving the parse that recognises the bridge'
    )
  },
  /**
   * The glossary twin of the two guards above: an entry must not name two contraries.
   *
   * "close the door" as an alias of "open the door" says the two are one action while the seed
   * pair open/close says they cannot both happen, and committed it turned FND_CONTRADICTION into
   * `verified: true`. The propose tier already withholds that merge (AC-3-6); this refuses the
   * committed op. Read through the document's OWN antonyms and terms, the tables the atomizer
   * uses. Defense in depth only — an antonym or term committed afterwards forms the same entry
   * with no glossary write to refuse, so the soundness guarantee is `atomize` keeping each
   * contrary on its own atom linked to the entry's action, and `check` demoting
   * (`contrary-glossary-alias`) over what that leaves undecided.
   */
  validateGlossary: (document, canonical, alias) => {
    let antonyms: ReturnType<typeof buildAntonymIndexWithDoc> = ANTONYM_INDEX
    try {
      antonyms = buildAntonymIndexWithDoc(
        document.antonyms.map((p) => [normalize(p.a), normalize(p.b)] as const),
      )
    } catch {
      // An inconsistent committed table is refused at ITS write; check falls back to the seeds.
    }
    const entry = glossaryContraries(
      glossaryIndex(document.glossary),
      antonyms,
      termIndex(document.terms ?? []),
    ).find((e) => e.canonical === canonical)
    const pair = entry?.contraries.find(([p, q]) => p === alias || q === alias)
    if (pair === undefined) return undefined
    const other = (pair[0] === alias ? pair[1] : pair[0]).replace(/_/g, ' ')
    return (
      `it is a contrary of "${other}" under the antonym table, so one entry naming both would ` +
      'say neither action ever happens'
    )
  },
}

/**
 * THE MUTATION OPERATIONS — every way a document changes, as one table of ops over
 * one fold.
 *
 * ## Twelve operations, one implementation
 *
 * `add`, `update`, `delete`, the four edge verbs, `remove-edge`, `waive`, `glossary`,
 * `antonym`, and `apply`. Every one of them builds a `DocumentOp[]` and hands it to
 * {@link runFold}. The single-op commands fold a one-element stream; `apply` folds an
 * N-element one. So there is no per-command mutation logic that could disagree with
 * the batch path — v4's `add`/`update`/`waive`/`glossary` cores each had their
 * own, and `apply.ts` re-implemented all four a third time.
 *
 * What that buys concretely: `--dry-run` is one branch in {@link runFold} rather than
 * a per-command feature (v4 had it only on `add`), the atomic-abort semantics
 * apply to a single op as much as to a batch, and adding a verb means adding an entry
 * to `core/ops.ts` plus one table row here.
 *
 * ## `apply` is the flagship, and its op stream is the SAME vocabulary
 *
 * v4's `apply` accepted eight verbs and could not express the three side
 * tables at all — those rode out as shell command lines its `import` had to re-parse.
 * Here `apply` consumes the whole `DocumentOp` union, so a repair plan that mixes a
 * `glossary add`, two `waive`s and an `update` is ONE invocation.
 *
 * ## The manifest-vs-parser drift v4 hit, avoided by construction
 *
 * Donor lesson `manifest-single-source-derivation` records the exact failure: `apply`
 * registered `--doc` while reusing a shared `.describe()` whose prose hardcoded
 * `--file`, so the manifest told an agent to run `apply --file` and got ERR_USAGE —
 * on the flagship command. Every description here that names a flag names its OWN
 * flag, and `mutation.test.ts` asserts that property mechanically: any description
 * mentioning a backticked `--flag` must name a field this operation actually declares.
 */

import { Effect, Schema } from 'effect'
// STATIC. A dynamic import here bought nothing: `operations/parse.ts` imports
// `engine/parse/batch.ts` statically and that imports `result.ts` statically, so the parse
// ladder is in the main chunk on every run regardless. The lazy form only added an await
// and made the build report an ineffective dynamic import.
import { parseLine } from '../../domain/engine/parse/result.ts'
import {
  EARS_PATTERNS,
  FRAME_KINDS,
  PRIORITIES,
  RELATIONS,
  RESPONSE_KINDS,
  STATE_VAR_TYPES,
  STATUSES,
  UPDATABLE_ATTRS,
  VERIFICATION_METHODS,
} from '../../domain/requirements/document.ts'
import { type FoldResult, foldOps } from '../../domain/requirements/mutate.ts'
import { type DocumentOp, decodeOp, RELATION_EDGE_OP } from '../../domain/requirements/ops.ts'
import { DOC_PATH_CONVENTION, DocPath, DocStore } from '../../ports/doc-store.ts'
import {
  ErrDuplicateId,
  ErrDuplicateKey,
  ErrNotFound,
  ErrNullRequired,
  ErrUsage,
  ErrWaiverRefused,
  type OperationalError,
} from '../../ports/errors.ts'
import { StreamSource } from '../../ports/stream.ts'
import { catalogCounts } from '../runtime/catalog.ts'
import { ok } from '../runtime/envelope.ts'
import { defineOperation } from '../runtime/operation.ts'
import { MUTATE_OPTIONS } from './mutate-options.ts'

const lines = (...xs: readonly string[]): string => xs.join('\n')

// ---------------------------------------------------------------------------
// The shared option surface
// ---------------------------------------------------------------------------

/** The document-path field, identical across every mutation op. */
const docPathField = (verb: string) =>
  Schema.withDecodingDefaultKey<Schema.NullOr<Schema.String>>(Effect.succeed(null))(
    Schema.NullOr(Schema.String).annotate({
      default: null,
      description: lines(
        `Path to the requirements document to ${verb}.`,
        DOC_PATH_CONVENTION,
        'Example: ./requirements.json',
      ),
    }),
  )

/**
 * `--dry-run`, available on EVERY mutation op rather than just `add`.
 *
 * v4 had it only on `add`, which is backwards: the ops most worth previewing
 * are the destructive ones (`delete`) and the bulk ones (`apply`), not the additive
 * single one. Because the preview is a branch in the shared fold, giving it to all
 * twelve costs one flag declaration each and cannot behave differently per command.
 */
const dryRunField = Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
  Schema.Boolean.annotate({
    default: false,
    description: lines(
      'Preview only: compute the result and report exactly what WOULD change, then write nothing.',
      'The payload is identical to a real run apart from `written: false`, so an agent can inspect',
      'per-op outcomes, minted ids, and no-ops before committing to a file.',
    ),
  }),
)

/** An optional string field with a `null` default. NOT wrapped in `optionalKey` —
 * `withDecodingDefaultKey` already makes the key optional on the ENCODED side, and
 * adding `optionalKey` leaks `undefined` into the decoded TYPE. */
const optionalString = (description: string) =>
  Schema.withDecodingDefaultKey<Schema.NullOr<Schema.String>>(Effect.succeed(null))(
    Schema.NullOr(Schema.String).annotate({ default: null, description }),
  )

/** A required string field. */
const requiredString = (description: string) => Schema.String.annotate({ description })

/** A ref field's description, single-sourced so all nine ref-taking ops agree. */
const refDescription = (what: string): string =>
  lines(
    `The requirement to ${what}, as its stable key (e.g. TX-B6, G1) OR its UUID.`,
    'Tried as a UUID first, then as a key, so both spellings work everywhere a ref is accepted.',
    'A ref that resolves to nothing is ERR_NOT_FOUND with did-you-mean suggestions.',
  )

// ---------------------------------------------------------------------------
// The shared runner
// ---------------------------------------------------------------------------

/** The payload every mutation op returns. */
export interface MutationPayload extends Omit<FoldResult, 'document'> {
  /** The resolved document path. */
  readonly path: string
  /**
   * One ERROR-severity entry per op the fold REFUSED, present only when one was (spec 007
   * AC-1-6). This is what makes a batch with a refused op exit non-zero through the
   * ordinary exit contract (`1`: an error-severity finding is present), the same contract
   * `check` and `parse` use — before it, an aborted atomic `apply` exited 0 and an agent
   * reading only the exit code saw a success that wrote nothing.
   */
  readonly findings?: readonly RefusedOpFinding[]
  /** Whether the document was actually WRITTEN. False on a dry run, on an atomic
   * abort, and on an all-no-op run — three different reasons, each visible in the
   * fields beside it rather than conflated into one flag. */
  readonly written: boolean
  /** Requirement count after the fold, so an agent sees the effect without a re-read. */
  readonly requirements: number
}

/**
 * Map a fold failure code onto its catalog error class.
 *
 * EXHAUSTIVE over `FOLD_ERROR_CODES` — `mutation.test.ts` asserts every code in that
 * closed set maps to a class, so a new fold failure cannot reach an agent as a
 * mystery. The fold returns plain code STRINGS because it lives in `core/` and the
 * catalog lives in `kernel/`; this is the one place that crossing happens.
 */
const toCatalogError = (
  code: string,
  error: string,
  suggestions: readonly string[],
): OperationalError => {
  const fields = { error, suggestions }
  switch (code) {
    case 'ERR_NOT_FOUND':
      return new ErrNotFound(fields)
    case 'ERR_DUPLICATE_ID':
      return new ErrDuplicateId(fields)
    case 'ERR_DUPLICATE_KEY':
      return new ErrDuplicateKey(fields)
    case 'ERR_NULL_REQUIRED':
      return new ErrNullRequired(fields)
    case 'ERR_WAIVER_REFUSED':
      return new ErrWaiverRefused(fields)
    default:
      // ERR_USAGE, and anything a future fold code forgets to map. Defaulting to a
      // USAGE error rather than an internal one is the honest fallback: the fold only
      // fails on inputs it was given.
      return new ErrUsage(fields)
  }
}

/**
 * Load, fold, save, report — the body of every mutation operation.
 *
 * ## A single-op failure is an ERROR ENVELOPE; a batch failure is DATA
 *
 * The one place the single and batch paths legitimately differ, and the reason is what
 * an agent can do about it. A `symspec update BOGUS status approved` that resolves
 * nothing is a failed invocation: exit 2, `ERR_NOT_FOUND`, with did-you-mean
 * suggestions. Reporting that as a success envelope containing one failed result would
 * make every single-op caller inspect `results[0].ok` and would break the exit
 * contract.
 *
 * A batch is different: 40 ops of which one failed is a partially-successful run whose
 * per-op results ARE the payload, and failing the whole invocation would throw away
 * the report an agent needs to fix line 12. So `apply` reports failures as data — each
 * refused op is ALSO an error-severity entry in `findings`, which is what drives the exit
 * code to `1`, exactly as `check` and `parse` do (spec 007 AC-1-6).
 *
 * `single` selects which contract applies. It is not a style choice — it is the
 * difference between "your command was wrong" and "here is what happened to each of
 * your 40 commands".
 */
const runFold = (args: {
  readonly file: string | null
  readonly dryRun: boolean
  readonly ops: readonly DocumentOp[]
  /** Apply what succeeds instead of aborting on the first failure. */
  readonly continueOnError?: boolean
  /** True for the single-op commands — see the note above. */
  readonly single: boolean
}): Effect.Effect<MutationPayload, OperationalError, DocPath | DocStore> =>
  Effect.gen(function* () {
    const docPath = yield* DocPath
    const store = yield* DocStore
    const path = docPath.resolve(args.file)
    const loaded = yield* store.load(path)

    // The clock is injected into the fold rather than read inside it, so replaying one
    // stream with one timestamp is byte-reproducible.
    const timestamp = new Date().toISOString()
    const result = foldOps(loaded.document, args.ops, timestamp, {
      ...MUTATE_OPTIONS,
      ...(args.continueOnError === true ? { continueOnError: true } : {}),
    })

    // SINGLE-OP contract: a failure is an error envelope, not a payload.
    if (args.single) {
      const failure = result.results.find((r) => !r.ok)
      if (failure !== undefined) {
        return yield* Effect.fail(
          toCatalogError(
            failure.code ?? 'ERR_USAGE',
            failure.error ?? 'the operation failed',
            failure.suggestions ?? [],
          ),
        )
      }
    }

    const written = result.write && !args.dryRun
    if (written) {
      // The preserved unknown top-level keys ride along, so a mutation cannot strip a
      // forward-compatible table (v4 finding V27 — the defect was a mutation
      // round-tripping through a strip-mode parse).
      yield* store.save(path, {
        document: result.document,
        unknownKeys: loaded.unknownKeys,
      })
    }

    // EVERY refused op becomes an error-severity finding, in atomic mode (where it aborted
    // the batch) and in continue-on-error mode (where the rest was applied) alike: either
    // way something the caller asked for did not happen, and the exit code must say so.
    const refused: readonly RefusedOpFinding[] = result.results
      .filter((r) => !r.ok)
      .map((r) => ({
        code: r.code ?? 'ERR_USAGE',
        severity: 'error',
        index: r.index,
        op: r.op,
        message:
          `op ${r.index} (${r.op}) was refused: ${r.error ?? 'the operation failed'}` +
          (result.abortedAt !== undefined
            ? ' — the batch was aborted and nothing was written.'
            : ''),
        suggestions: r.suggestions ?? [],
      }))

    return {
      path,
      written,
      requirements: Object.keys(result.document.requirements).length,
      results: result.results,
      summary: result.summary,
      write: result.write,
      ...(result.abortedAt !== undefined ? { abortedAt: result.abortedAt } : {}),
      ...(refused.length > 0 ? { findings: refused } : {}),
    }
  })

/** A refused op, projected as an error-severity finding (see {@link MutationPayload}). */
export interface RefusedOpFinding {
  /** The op's own failure code (`ERR_NOT_FOUND`, `ERR_USAGE`, …). */
  readonly code: string
  readonly severity: 'error'
  /** The 0-based index of the refused op in the batch. */
  readonly index: number
  readonly op: string
  readonly message: string
  readonly suggestions: readonly string[]
}

/** Emit a mutation payload under the operation's own envelope type. */
const emitMutation = <T extends string>(type: T, payload: MutationPayload) => ok(type, payload)

