export const deleteOp = defineOperation({
  name: 'delete',
  summary: 'Delete one requirement, leaving any inbound edges as dangling references',
  type: 'delete',
  input: Schema.Struct({
    ref: requiredString(refDescription('delete')),
    file: docPathField('delete from'),
    dryRun: dryRunField,
