// ---------------------------------------------------------------------------
// The state model (G4) — the authoring surface for reachability
// ---------------------------------------------------------------------------

/**
 * `state` — declare one state variable, or undeclare it with `--remove`.
 *
 * ## Why the state model is TWO operations and not one
 *
 * `state` declares a VARIABLE; `classify` labels a REQUIREMENT's response and gives
 * its expression. That split mirrors v4's own "two tables, not one" finding
 * (spec 003's AC-2-1 note): the variable set is document-scoped and the
 * effect/constraint label is requirement-scoped, and collapsing them into one command
 * would mean a flag set where half the flags are meaningless in either mode.
 *
 * `--remove` rides on this one op rather than being a peer `unstate` command, matching
 * `waive`/`glossary`/`antonym`/`link` — the CLI has one command per TABLE and a
 * `--remove` flag, while the op STREAM has the two verbs (`state` / `unstate`). A
 * projection difference, not two vocabularies.
 *
 * The `--remove` path is the one place this operation can refuse for a reason the
 * caller did not cause directly: undeclaring a variable that expressions still
 * reference is ERR_USAGE naming those requirements. That refusal is load-bearing — see
 * the `UnstateOp` header — because the alternative is a document whose next `check`
 * hangs the solver rather than reporting anything.
 */
export const stateOp = defineOperation({
  name: 'state',
  summary: 'Declare or undeclare one state variable — the document-scoped half of the state model',
  type: 'state',
  input: Schema.Struct({
    name: requiredString(
      lines(
        'The variable name, as referenced by every effect and constraint expression.',
        'Identifier-shaped: a letter or underscore, then letters, digits, underscores or dots.',
        'Must NOT be one of the reserved words and, or, not, true, false, when — those are',
        'expression syntax, so a variable named one of them could be declared and never referenced.',
        'Examples: lock_held; run_state; retry_count.',
      ),
    ),
    type: optionalString(
      lines(
        `The declared type. Legal values: ${STATE_VAR_TYPES.join(', ')}.`,
        '  - bool: two-valued. Its domain is {true,false} and is NOT declared.',
        '  - int:  integer, optionally bounded with `--min`/`--max`. Declaring BOTH bounds makes the',
        '    variable finite-domain, which is what lets a reachability query be decided rather than',
        '    merely attempted.',
        '  - enum: a finite symbolic variable. `--domain` lists its members and is REQUIRED.',
        'Required unless `--remove` is supplied.',
      ),
    ),
    domain: optionalString(
      lines(
        'For `--type enum` ONLY: the comma-separated members this variable may take.',
        'At least one member — an empty domain would give the encoder an empty state space, over which',
        'every invariant holds VACUOUSLY, so it is refused rather than accepted as a vacuous',
        'declaration. Members are identifier-shaped, because a member is written BARE in an',
        'expression (`run_state = PENDING`).',
        'Example: --domain "PENDING,RUNNING,DONE,FAILED"',
      ),
    ),
    min: optionalString(
      lines(
        'For `--type int` ONLY: the inclusive lower bound. Omit for unbounded below.',
        'An empty range (`--min` above `--max`) is refused: it describes no states at all, so every',
        'invariant over it would hold VACUOUSLY and a reachability proof would mean nothing.',
      ),
    ),
    max: optionalString(
      'For `--type int` ONLY: the inclusive upper bound. Omit for unbounded above.',
    ),
    frame: optionalString(
      lines(
        `Whether the variable persists across a step that does not write it. Legal values: ${FRAME_KINDS.join(', ')}.`,
        'DEFAULTS TO volatile, and that default is a soundness property rather than a preference.',
        '  - volatile: the variable may change freely in any step. Nothing is assumed.',
        '  - stable:   it changes ONLY when some requirement`s effect changes it — a HYPOTHESIS the',
        '    document does not otherwise state.',
        'A property that holds only with the DECLARED `stable` variables held fixed is reported as',
        'PROVED_UNDER_HYPOTHESES naming them, and DEMOTES `verified`. One that needs variables held',
        'that the document leaves volatile is UNKNOWN (reason frame-undeclared), also demoted — so',
        'declaring or releasing a frame moves the verdict. The full lattice is on the `frame` field',
        'of the document schema.',
        'Why volatile by default: measured on this solver, a model whose variable is written by no',
        'requirement returns UNREACHABLE *with an inductive invariant* under a frame and REACHABLE',
        'without one — so a frame-by-default would make the tool prove a false answer and certify it.',
      ),
    ),
    initial: optionalString(
      lines(
        'Optional initial-state predicate over this variable, e.g. "lock_held = false".',
        'Omit when the initial value is unconstrained — an omission is a genuine `any value` rather',
        'than an implied false/zero, so it WEAKENS what can be proven rather than strengthening it.',
      ),
    ),
    remove: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: lines(
          'Undeclare the variable instead of declaring it. Removing an already-absent variable is a',
          'no-op success, so this is safe to replay.',
          'REFUSED while any requirement`s effect or constraint still references the variable — the',
          'referencing requirements are named. Allowing it would leave an UNDECLARED reference in the',
          'document, and the failure that produces at check time is an unkillable solver hang rather',
          'than an error message.',
        ),
      }),
    ),
    file: docPathField('edit'),
    dryRun: dryRunField,
  }),
  handler: (input) =>
    Effect.gen(function* () {
      if (input.remove) {
        const op: DocumentOp = { op: 'unstate', name: input.name }
        return emitMutation(
          'state',
          yield* runFold({ file: input.file, dryRun: input.dryRun, ops: [op], single: true }),
        )
      }

      if (input.type === null) {
        return yield* Effect.fail(
          new ErrUsage({
            error: 'state requires --type when declaring a variable.',
            suggestions: [
              `Legal values: ${STATE_VAR_TYPES.join(', ')}.`,
              `Example: \`symspec state --name ${input.name} --type bool\`.`,
              'Pass --remove to undeclare an existing variable instead.',
            ],
          }),
        )
      }

      // The numeric bounds arrive as STRINGS because argv has no integers, and they are
      // parsed HERE rather than declared as integer flags for one reason: `--min` and
      // `--max` are optional, and an optional integer flag would need a sentinel for
      // "absent" — which is exactly the trap `check --fail-on-unmatched` documents (a
      // negative sentinel is unreachable from a shell, and 0 is a meaningful value).
      // A string flag whose absence is `null` says it without a sentinel.
      const bound = (raw: string | null, flag: string) =>
        raw === null
          ? undefined
          : /^-?\d+$/.test(raw.trim())
            ? Number(raw.trim())
            : `--${flag} expects an integer, got ${JSON.stringify(raw)}.`

      const min = bound(input.min, 'min')
      const max = bound(input.max, 'max')
      for (const value of [min, max]) {
        if (typeof value === 'string') {
          return yield* Effect.fail(
            new ErrUsage({
              error: value,
              suggestions: [
                'Bounds are whole numbers, e.g. --min 0 --max 5.',
                'Omit the flag entirely for an unbounded direction.',
              ],
            }),
          )
        }
      }

      const raw: Record<string, unknown> = {
        op: 'state',
        name: input.name,
        type: input.type,
        ...(input.domain !== null ? { domain: input.domain.split(',').map((m) => m.trim()) } : {}),
        ...(typeof min === 'number' ? { min } : {}),
        ...(typeof max === 'number' ? { max } : {}),
        ...(input.frame !== null ? { frame: input.frame } : {}),
        ...(input.initial !== null ? { initial: input.initial } : {}),
      }

      // Decoded through the OP schema, so a bad `--type` or `--frame` is rejected by the
      // same schema `apply` uses — one validator, not two that could disagree.
      const op = yield* Effect.mapError(
        decodeOp(raw),
        (cause) =>
          new ErrUsage({
            error: `The state declaration is not valid: ${String(cause).replace(/\s*\n\s*/g, ' ')}`,
            suggestions: [
              `--type must be one of: ${STATE_VAR_TYPES.join(', ')}.`,
              `--frame must be one of: ${FRAME_KINDS.join(', ')}.`,
              'Run `symspec manifest` for every field`s exact shape.',
            ],
          }),
      )

      return emitMutation(
        'state',
        yield* runFold({ file: input.file, dryRun: input.dryRun, ops: [op], single: true }),
      )
    }),
})

/**
 * `state-initial` — set or clear the model-wide initial-state predicate.
 *
 * Its own operation rather than a flag on `state`, because it is scoped to the MODEL
 * and not to a variable: it exists precisely for the cross-variable constraints a
 * per-variable `--initial` cannot express (`not (lock_held and pending)`). Hanging it
 * off `state --name` would require naming a variable it is not about.
 */
export const stateInitialOp = defineOperation({
  name: 'state-initial',
  summary: 'Set or clear the model-wide initial-state predicate over the declared variables',
  type: 'stateInitial',
  input: Schema.Struct({
    predicate: optionalString(
      lines(
        'The initial-state predicate over the DECLARED state variables — what holds before any',
        'requirement has fired. Conjoined with every per-variable `initial`, so the two are additive',
        'and adding either can only NARROW the initial states.',
        'Use this for the cross-variable constraints a per-variable initial cannot express.',
        'Every referenced name must be declared: an undeclared reference is ERR_USAGE here rather',
        'than a solver hang later.',
        'Omit it and pass `--clear` to remove the predicate instead.',
        'Examples: "run_state = PENDING and retry_count = 0"; "not (lock_held and pending)".',
      ),
    ),
    clear: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: lines(
          'Remove the model-wide initial predicate. Mutually exclusive with `--predicate`.',
          'Clearing WIDENS the initial states (every state becomes a possible start), which can only',
          'make fewer things provable — the safe direction.',
        ),
      }),
    ),
    file: docPathField('edit'),
    dryRun: dryRunField,
  }),
  handler: (input) =>
    Effect.gen(function* () {
      if (input.clear && input.predicate !== null) {
        return yield* Effect.fail(
          new ErrUsage({
            error:
              '--clear and --predicate are mutually exclusive: clear REMOVES the predicate, a value SETS it.',
            suggestions: ['Drop --clear to set the predicate.', 'Drop --predicate to clear it.'],
          }),
        )
      }
      if (!input.clear && input.predicate === null) {
        return yield* Effect.fail(
          new ErrUsage({
            error: 'state-initial requires --predicate, or --clear to remove it.',
            suggestions: [
              'Pass --predicate "<expression over declared variables>".',
              'Pass --clear to remove the model-wide initial predicate.',
            ],
          }),
        )
      }
      const op: DocumentOp = {
        op: 'state-initial',
        predicate: input.clear ? null : (input.predicate as string),
      }
      return emitMutation(
        'stateInitial',
        yield* runFold({ file: input.file, dryRun: input.dryRun, ops: [op], single: true }),
      )
    }),
})

/**
 * `classify` — label one requirement's response as an effect or a constraint, WITH the
 * expression that says what it does.
 *
 * ## Why the label and the expression are one command
 *
 * Because a label alone is a classification that reads as finished and is not: a
 * requirement marked `effect` with no `stateEffect` contributes nothing to the
 * transition relation, so the reachability tier sees a document that looks classified
 * and has no state model to encode. `--kind` and `--expression` therefore arrive
 * together and the fold refuses one without the other, which makes the easy path the
 * complete one.
 *
 * The alternative — `update responseKind` then `update stateEffect` — still WORKS
 * (both are updatable attributes, because a state model is authored iteratively and
 * editing one expression without restating the label has to be possible), and the
 * `update` path carries the same validation. This op exists so the COMMON case is one
 * call that cannot land half-done.
 */
export const classifyOp = defineOperation({
  name: 'classify',
  summary:
    "Classify one requirement's response as an effect or a constraint, with its state expression",
  type: 'classify',
  input: Schema.Struct({
    ref: requiredString(refDescription('classify')),
    kind: optionalString(
      lines(
        `How the response relates to the state model. Legal values: ${RESPONSE_KINDS.join(', ')}.`,
        '  - effect:     the response CHANGES state. `--expression` is one or more comma-separated',
        '    updates, `<variable> := <expression>`. Several updates happen in ONE step.',
        '  - constraint: the response RESTRICTS state. `--expression` is a PREDICATE the reachability',
        '    tier tries to violate — if no reachable state violates it, that is a proof.',
        'Required unless `--retract` is supplied.',
      ),
    ),
    expression: optionalString(
      lines(
        'What the response does, in the state-model expression language.',
        'For `--kind effect`: an optional GUARD then the updates —',
        '`when <predicate>: <variable> := <value>`, comma-separated for simultaneous updates.',
        'Note `:=` ASSIGNS; a single `=` is the equality COMPARISON and belongs in a constraint.',
        'THE GUARD is what an EARS trigger means formally, written explicitly over declared',
        'variables rather than inferred from the prose trigger slot (guessing one would make the',
        'solver prove the wrong thing). OMITTING it means the effect fires from EVERY state — the',
        'sound default, since it admits more transitions and so proves strictly less, but usually',
        'not what a triggered requirement means.',
        'For `--kind constraint`: a predicate that must hold in every reachable state.',
        'GRAMMAR: comparisons = != < <= > >=; arithmetic + - on ints; and/or/not; parentheses;',
        'true/false and integer literals; and bare names resolved against the declared state model.',
        'No multiplication (it makes the transition relation nonlinear, where an unbounded solver',
        'hang was measured), no quantifiers, no chained comparisons (write `a < b and b < c`).',
        '< <= > >= are INTEGER-ONLY: an enum has a declared DOMAIN, not an ORDER.',
        'EVERY referenced name must be declared with `symspec state` first. An undeclared reference',
        'is refused HERE, at authoring time, because reaching the Horn encoder it would hang the',
        'solver unkillably rather than produce an error.',
        'Examples: "when pending: lock_held := true"; "when granted = 0: granted := granted + 1";',
        '"run_state := RUNNING, retry_count := 0"; "not (lock_held and pending)"; "retry_count <= 3".',
      ),
    ),
    retract: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: lines(
          'Remove the classification: clears the responseKind AND its expression.',
          'Both, deliberately — an expression left behind with no label is a predicate nothing reads,',
          'i.e. a decision recorded and not applied.',
          'Retracting DEMOTES the reachability tier for this requirement (its response becomes',
          'unclassified again), which is the honest direction: the tier now knows less, and says so.',
        ),
      }),
    ),
    file: docPathField('edit'),
    dryRun: dryRunField,
  }),
  handler: (input) =>
    Effect.gen(function* () {
      if (input.retract) {
        if (input.kind !== null || input.expression !== null) {
          return yield* Effect.fail(
            new ErrUsage({
              error:
                '--retract removes the classification, so it cannot be combined with --kind or --expression.',
              suggestions: [
                'Drop --retract to set a classification.',
                'Drop --kind/--expression to retract the existing one.',
              ],
            }),
          )
        }
        const op: DocumentOp = { op: 'classify', ref: input.ref, kind: null }
        return emitMutation(
          'classify',
          yield* runFold({ file: input.file, dryRun: input.dryRun, ops: [op], single: true }),
        )
      }

      if (input.kind === null) {
        return yield* Effect.fail(
          new ErrUsage({
            error: 'classify requires --kind, or --retract to remove an existing classification.',
            suggestions: [
              `Legal values: ${RESPONSE_KINDS.join(', ')}.`,
              `Example: \`symspec classify ${input.ref} --kind constraint --expression "not (lock_held and pending)"\`.`,
            ],
          }),
        )
      }

      const raw: Record<string, unknown> = {
        op: 'classify',
        ref: input.ref,
        kind: input.kind,
        ...(input.expression !== null ? { expression: input.expression } : {}),
      }
      const op = yield* Effect.mapError(
        decodeOp(raw),
        (cause) =>
          new ErrUsage({
            error: `The classification is not valid: ${String(cause).replace(/\s*\n\s*/g, ' ')}`,
            suggestions: [
              `--kind must be one of: ${RESPONSE_KINDS.join(', ')}.`,
              'Run `symspec manifest` for every field`s exact shape.',
            ],
          }),
      )

      return emitMutation(
        'classify',
        yield* runFold({ file: input.file, dryRun: input.dryRun, ops: [op], single: true }),
      )
    }),
})

// ---------------------------------------------------------------------------
// apply — the flagship
// ---------------------------------------------------------------------------

export const applyOpDefinition = defineOperation({
  name: 'apply',
  summary: 'Apply a JSONL stream of document ops in one process and one atomic write',
  type: 'apply',
  input: Schema.Struct({
    // NAMED `--ops`, and the name matters: v4's `apply` registered `--doc` for
    // the DOCUMENT while reusing a shared description whose prose said `--file`, so its
    // manifest told an agent to run `apply --file` and got ERR_USAGE. Here the stream
    // is `--ops` and the document is `--file`, each described by its own text naming
    // its own flag.
    ops: optionalString(
      lines(
        'Path to the JSONL op stream: one `{"op":...}` record per line. Omit to read STDIN.',
        'Blank lines and `#` comments are skipped, so a stream can be annotated.',
        'Every op verb `symspec manifest` publishes is accepted — including the three side tables',
        '(`glossary`, `antonym`, `waive`) v4 could only express as shell commands.',
        'A `key` minted by an `add` earlier in the SAME stream is referenceable by later ops, which',
        'is what removes the label-to-UUID sidecar file entirely.',
        'Example: --ops ./repair-plan.jsonl',
      ),
    ),
    file: docPathField('apply to'),
    continueOnError: Schema.withDecodingDefaultKey<Schema.Boolean>(Effect.succeed(false))(
      Schema.Boolean.annotate({
        default: false,
        description: lines(
          'Best-effort mode: apply the ops that succeed instead of aborting on the first failure.',
          'ATOMIC by default — any failure writes NOTHING and reports the failing op`s index, so a',
          'crashed batch leaves the document untouched and the resume story is "fix that line and',
          're-run" rather than "work out how far it got".',
          'Best-effort is the mode a REPAIR PLAN wants: an op that is already applied (a no-op) or',
          'that names a requirement someone deleted should not block the eight repairs that do apply.',
        ),
      }),
    ),
    dryRun: dryRunField,
  }),
  handler: (input) =>
    Effect.gen(function* () {
      const reader = yield* StreamSource
      const text = yield* reader.read(input.ops)

      if (text.trim().length === 0) {
        return yield* Effect.fail(
          new ErrUsage({
            error:
              input.ops === null
                ? 'No op stream on stdin. Pipe records in, or pass --ops <path>.'
                : `The op stream at ${input.ops} is empty or contains only comments.`,
            suggestions: [
              'Pipe a plan: `symspec check --field data.coverage.demotions | ... | symspec apply`.',
              'Or read a file: `symspec apply --ops ./repair-plan.jsonl`.',
              'Get a ready-made stream from `symspec parse --field data.opsJsonl`.',
            ],
          }),
        )
      }

      // Decode EVERY line before folding any of it, so a malformed record is reported
      // with its line number rather than as an abort partway through.
      const ops: DocumentOp[] = []
      const problems: { readonly line: number; readonly detail: string }[] = []
      const rawLines = text.split(/\r?\n/)
      for (let i = 0; i < rawLines.length; i += 1) {
        const line = (rawLines[i] ?? '').trim()
        if (line.length === 0 || line.startsWith('#')) continue
        let parsed: unknown
        try {
          parsed = JSON.parse(line)
        } catch (cause) {
          problems.push({
            line: i + 1,
            detail: `not valid JSON: ${cause instanceof Error ? cause.message : String(cause)}`,
          })
          continue
        }
        const decoded = yield* Effect.result(decodeOp(parsed))
        if (decoded._tag === 'Failure') {
          problems.push({
            line: i + 1,
            detail: `rejected: ${String(decoded.failure).replace(/\s*\n\s*/g, ' ')}`,
          })
          continue
        }
        ops.push(decoded.success)
      }

      // A malformed line is a USAGE error in atomic mode: the stream as given cannot be
      // applied, and applying the well-formed subset would be a partial write the
      // caller did not ask for.
      if (problems.length > 0 && input.continueOnError !== true) {
        return yield* Effect.fail(
          new ErrUsage({
            error:
              `${problems.length} op record(s) could not be read, so nothing was applied ` +
              `(atomic mode): ${problems.map((p) => `line ${p.line} ${p.detail}`).join('; ')}`,
            suggestions: [
              'Fix the named lines and re-run — the document is unchanged.',
              'Or pass --continue-on-error to apply the records that ARE valid.',
              'Run `symspec manifest` for every op verb and its exact fields.',
            ],
          }),
        )
      }

      const payload = yield* runFold({
        file: input.file,
        dryRun: input.dryRun,
        ops,
        ...(input.continueOnError === true ? { continueOnError: true } : {}),
        single: false,
      })
      return ok('apply', { ...payload, problems })
    }),
})

/**
 * REPAIR SYNTHESIS — turning every demotion into a `{ops[], commands[]}` an agent
 * can apply without reading prose (spec AC-A-1).
 *
 * ## What v4 left to the agent, and what this closes
 *
 * v4's `CoverageDemotion` carries `action: string` — a paragraph of prose
 * naming the discharging command, e.g.
 *
 *   "Alternatively, `symspec waive add <blocking-code> --ref <id> --reason "…"`"
 *
 * Two things make that a poor agent contract. First, an agent must PARSE prose to
 * find the command, and there is no guarantee the sentence structure is stable.
 * Second — and this is the load-bearing part — `<blocking-code>` is a literal
 * PLACEHOLDER. The pipeline knows exactly which codes blocked the requirement (the
 * gate carried them as evidence), but the demotion's action text does not join
 * them in. So an agent following the instruction verbatim runs
 * `symspec waive add <blocking-code>` and gets a usage error.
 *
 * This module does that join. For every demotion reason, {@link repairForDemotion}
 * returns a `Repair` whose `commands` are RUNNABLE — no placeholders, no prose to
 * parse — resolving `<blocking-code>` from the run's own excluded-requirement
 * evidence and `<a>`/`<b>` from the finding that raised the demotion.
 *
 * v4's `action` prose is PRESERVED alongside, unchanged. It carries the
 * *reasoning* (why waiving cannot discharge a coverage fact, why re-admission is
 * defensible), which a runnable command cannot express, and dropping it would lose
 * the honesty the demotion-only doctrine rests on. The repair is additive: prose
 * for a human, ops and commands for an agent.
 *
 * ## `ops` are REAL as of G2b (spec AC-A-1)
 *
 * G2a shipped this module with an always-empty `ops` and a header note explaining
 * why: the discharges are `glossary add` / `antonym add` / `waive add`, and those
 * were COMMANDS whose op records did not exist yet. Emitting a speculative record
 * for a shape that was not fixed would have been a guess an agent then applied.
 *
 * `core/ops.ts` fixed the shape, so `ops` now carries the actual `DocumentOp`
 * records — decodable by `apply` BY CONSTRUCTION, since the finding emits from the
 * same union `apply` decodes. That closes the loop v4 could not:
 *
 *     symspec check --field data.coverage.demotions   # read the plan
 *     symspec apply --ops plan.jsonl                  # execute it
 *     symspec check                                   # the demotions are gone
 *
 * `commands` is PRESERVED alongside, and not as legacy. Two of the discharges are
 * genuinely not ops — `--solver-budget-ms` is a different INVOCATION, and a
 * `show`/`list` read is what an agent needs before it can author a rewrite — so a
 * repair that carried only ops would have to either omit those or fabricate an op
 * that performs them.
 *
 * ## Where `ops` is still empty, and why each is honest rather than unfinished
 *
 * - `uncovered-requirement` — the discharge is a REWRITE. No op performs one, and
 *   synthesizing `{"op":"update","attr":"systemResponse","value":"…"}` would mean
 *   inventing the replacement text, which is the one thing a repair must never do.
 *   It carries the two READS that produce the input for a rewrite instead.
 * - `solver-budget-exhausted` — the discharge is a different invocation, not a
 *   document change.
 * - `no-decide-tier-comparison` — WHICH terms to link is a judgment about the
 *   document's meaning that no run can make. A fabricated `glossary` op here would
 *   be the propose/decide violation the whole architecture forbids: it would commit
 *   a decide-tier artifact from a guess.
 *
 * In each case the honest signal is a repair with commands and no ops, or (for a
 * genuinely mechanical-fix-free reason) no repair at all — the envelope helper OMITS
 * an all-empty repair, so "there is a repair, it is nothing" never reaches an agent.
 */

import { runnable } from '../../ports/command-form.ts'
import type { Repair } from '../../ports/repair.ts'
import type { CheckFinding, CoverageDemotion, RunDisclosure } from '../engine/pipeline/check.ts'
import type { Exclusion } from '../engine/pipeline/gate.ts'
import type { DocumentOp } from '../requirements/ops.ts'
import { waivabilityOf } from '../waivability.ts'

/** The reason strings a {@link CoverageDemotion} may carry. */
export type DemotionReason = CoverageDemotion['reason']

/**
 * The run-scoped facts a repair needs beyond the demotion itself.
 *
 * `exclusionsById` is the join that resolves `<blocking-code>`: the AC-3-7 gate
 * recorded the blocking findings as evidence, and this is how they reach the
 * repair. `findingsById` resolves the verb/quantity pairs an `antonym`/`glossary`
 * command needs.
 */
export interface RepairContext {
  /** Gate exclusions, indexed by requirement id — the `<blocking-code>` source. */
  readonly exclusionsById: ReadonlyMap<string, Exclusion>
  /** Every kept finding, so a demotion can reach the finding that raised it. */
  readonly findings: readonly CheckFinding[]
  /**
   * The `--solver-budget-ms` the run used, for the raise-the-budget command.
   *
   * `optionalKey` rather than `number | undefined`: under
   * `exactOptionalPropertyTypes` an unbounded run OMITS the key, which is the same
   * absence-is-absence convention v4 `CheckOptions` uses, so the caller can
   * spread its options straight in with no `undefined` widening.
   */
  readonly solverBudgetMs?: number
  /**
   * The MEASURED budget recommendation from `data.budgetHint`, when the run produced
   * one (G3, AC-A-8).
   *
   * Threaded in rather than recomputed, because the repair command and the hint are
   * two renderings of ONE answer to "what budget should I use" and they must not
   * disagree. G2a's `raisedBudget` doubling is kept as the fallback for a caller with
   * no measurement (a direct library call, a test), so this module still works
   * standalone — but when a hint exists it WINS, and `repair.test.ts` asserts the two
   * numbers are equal rather than merely both plausible.
   */
  readonly recommendedBudgetMs?: number
  /**
   * The per-group `--timeout-ms` the run used, for the raise-the-timeout command on
   * an `inconclusive-group` demotion.
   *
   * There is no measured recommendation to prefer here, unlike the whole-run budget:
   * a group came back `unknown`, which says nothing about how much longer it would
   * have needed. So the command doubles, and an agent that still gets `unknown`
   * doubles again.
   */
  readonly timeoutMs?: number
  /**
   * What the run was made of (`data.run`), so a `run-weakened` repair names the invocation
   * that undoes the weakening actually present. Absent for a caller with no run to report.
   */
  readonly run?: RunDisclosure
  /** The document path, so every command is copy-pasteable as-is. */
  readonly docPath: string
  /**
   * The content hash of the requirements a finding names, as a pair waiver binds it
   * (`requirementsContentHash`). Threaded in so a waiver op carries the hash of the text `check`
   * raised the finding on, and `apply` refuses it once that text has changed. Absent for a
   * caller with no document (a direct library call, a test): the op then omits the hash and
   * `apply` binds the text as it stands when the op is applied.
   */
  readonly contentHash?: (ids: readonly string[]) => string | undefined
}

/** A repair with nothing in it — the honest shape when no mechanical fix exists. */
const NO_REPAIR: Repair = { ops: [], commands: [] }

/**
 * The budget to recommend in a raise-the-budget command.
 *
 * PREFERS the measured recommendation from `data.budgetHint` (G3): that number is
 * extrapolated from the work the run actually completed and the time it actually took,
 * so it lands in one hop where doubling takes several — from a 500ms budget on a
 * 60-requirement document, doubling needs seven `check` runs to reach a working figure
 * and each one pays the full truncated cost.
 *
 * Falls back to the G2a doubling when no measurement is available (a direct library
 * call, a unit test), floored so a tiny budget does not suggest a tinier one. The
 * fallback stays because this module must work without the caller having measured
 * anything — but it is a guess that happens to converge, not evidence, and the header
 * says so.
 */
const raisedBudget = (current: number | undefined, recommended: number | undefined): number =>
  recommended ?? (current === undefined ? 10_000 : Math.max(2_000, current * 2))

/**
 * The per-group timeout to recommend after an `unknown`.
 *
 * A doubling with a floor, and no measured alternative: the whole-run budget has one
 * (`data.budgetHint` extrapolates from completed work), but an `unknown` group
 * completed nothing, so there is nothing to extrapolate from. The floor is the tier's
 * own 2000ms default doubled, so a run that passed a tiny `--timeout-ms` is not sent
 * back with a tiny suggestion.
 */
const raisedTimeout = (current: number | undefined): number =>
  Math.max(4_000, (current ?? 2_000) * 2)

/**
 * Build the runnable repair for one demotion.
 *
 * Exhaustive over {@link DemotionReason} by construction: the `switch` returns in
 * every arm and the function's return type has no `undefined`, so adding a reason
 * to v4's union without handling it here is a compile error rather than a
 * silently repair-less demotion.
 */
export const repairForDemotion = (demotion: CoverageDemotion, context: RepairContext): Repair => {
  switch (demotion.reason) {
    // ---------------------------------------------------------------------
    // THE PLACEHOLDER JOIN — the one v4 left to the agent
    // ---------------------------------------------------------------------
    case 'excluded-from-formal': {
      const id = demotion.requirementIds[0]
      if (id === undefined) return NO_REPAIR
      const exclusion = context.exclusionsById.get(id)
      // A parse failure has no blocking CODE to waive — there is no finding, the
      // sentence simply did not parse. So the only repair is to look at it, which
      // `show` does. Waiving nothing would be the wrong instruction.
      if (exclusion === undefined || exclusion.reason === 'parse-failure') {
        return { ops: [], commands: [`symspec show ${id} ${context.docPath}`] }
      }
      // The join: the gate carried the blocking findings as evidence, so each
      // becomes a CONCRETE waive — one per code, because waiving is per-code and an
      // agent should be able to discharge them one at a time and re-check between.
      // Only a `scoped`-class code (spec 007 AC-5-6): the fold refuses any other.
      const codes = [...new Set(exclusion.findings.map((f) => f.code))]
        .filter((code) => waivabilityOf(code) === 'scoped')
        .sort()
      const contentHash = context.contentHash?.([id])
      return {
        // REAL OPS (G2b). Each is a `{"op":"waive"}` record `apply` decodes, scoped
        // to EXACTLY the excluded requirement and bound to its current text (`refs` plus
        // the content hash), so it suppresses that finding THERE and only while the
        // reviewed text stands. The reason carries a PLACEHOLDER an agent must replace
        // — deliberately, because a waiver's whole value is its audit trail and
        // synthesizing a justification would be the tool lying on the author's
        // behalf. An agent that applies these unedited commits a visible
        // `<why this finding does not apply>`, which is the honest failure mode.
        //
        // Applied, the waiver re-admits the requirement to the solver and the run demotes
        // `waived-blocking-lint` in its place (G3): a comparison over wording a reviewer
        // accepted rather than fixed never certifies, so this op trades one demotion for
        // another and the rephrase is the only discharge that can reach `verified: true`.
        ops: codes.map(
          (code) =>
            ({
              op: 'waive',
              code,
              refs: [id],
              ...(contentHash !== undefined ? { contentHash } : {}),
              reason: 'reviewed: <why this finding does not apply>',
            }) satisfies DocumentOp,
        ),
        commands: [
          // Look FIRST: the honest primary repair is to fix the sentence, and an
          // agent cannot rewrite what it has not read. A waiver is the fallback, not
          // the recommendation — which is why the read leads and the ops are second.
          `symspec show ${id} ${context.docPath}`,
          `symspec check ${context.docPath}`,
        ],
      }
    }

    // ---------------------------------------------------------------------
    // Reasons whose discharging command is named by the RAISING FINDING
    // ---------------------------------------------------------------------
    case 'open-opposition-candidate':
      // The finding message carries the two verb heads and the exact
      // `antonym add`/`glossary add` invocation; extracting them is a join on the
      // finding, not a guess.
      return fromFindingMessage(demotion, context, 'FND_OPPOSITION_CANDIDATE')

    case 'opposite-polarity-near-duplicate':
      // The FND_SIMILAR_SEMANTIC message carries the exact `glossary add` merge; the commands
      // carry it first. No op: the candidate is triage, never waivable (spec 007 AC-5-6).
      return fromFindingMessage(demotion, context, 'FND_SIMILAR_SEMANTIC')

    case 'quantity-alias-candidate':
      return fromFindingMessage(demotion, context, 'FND_QUANTITY_ALIAS_CANDIDATE')

    case 'relational-reasoning-not-attempted':
      // Aggregate/cross-quantity reasoning was NOT ATTEMPTED — there is no command
      // that attempts it, and FND_RELATIONAL_UNCHECKED is a disclosure, which no waiver
      // discharges (decision D1, spec 007 AC-5-6): a waiver on "not compared" is a claim
      // the tool cannot check. NO OPS. The discharge is restating the constraint in a form
      // the solver compares, which needs the requirements read first.
      return {
        ops: [],
        commands: [
          ...demotion.requirementIds.map((id) => `symspec show ${id} ${context.docPath}`),
          `symspec check ${context.docPath}`,
        ],
      }

    case 'numeric-bounds-uncompared':
      // The numeric tier declined to decide: the verdict depends on a reading (role,
      // temperature sense, unit) the sentences do not fix. No command decides it for the
      // author, and the disclosure is never waivable (D1). NO OPS: the repair is to restate
      // the bounds in one sense and one unit, which needs the requirements read first.
      return {
        ops: [],
        commands: [
          ...demotion.requirementIds.map((id) => `symspec show ${id} ${context.docPath}`),
          `symspec check ${context.docPath}`,
        ],
      }

    case 'number-spelling-candidate':
      // Whether two separator spellings are one number is the author's decimal convention; no
      // command decides it, and a triage candidate is never waivable. NO OPS: the repair is to
      // spell the numbers in one convention, which needs the requirements read first.
      return {
        ops: [],
        commands: [
          ...demotion.requirementIds.map((id) => `symspec show ${id} ${context.docPath}`),
          `symspec check ${context.docPath}`,
        ],
      }

    // ---------------------------------------------------------------------
    // Run-scoped reasons: the repair is a different INVOCATION, not an edit
    // ---------------------------------------------------------------------
    case 'solver-budget-exhausted':
      return {
        ops: [],
        commands: [
          `symspec check ${context.docPath} --solver-budget-ms ${raisedBudget(context.solverBudgetMs, context.recommendedBudgetMs)}`,
        ],
      }

    case 'inconclusive-group':
    case 'solver-unknown':
      // The solver said `unknown` for this group. NO OPS, and that is the honest
      // shape: no document edit decides an undecidable group, and a waiver of the
      // raising FND_NEEDS_REVIEW would hide the disclosure while leaving the group
      // undecided. The lever is the PER-GROUP timeout, so the repair is the same
      // invocation with more of it — the `--timeout-ms` analogue of
      // `solver-budget-exhausted`'s `--solver-budget-ms`.
      return {
        ops: [],
        commands: [
          `symspec check ${context.docPath} --timeout-ms ${raisedTimeout(context.timeoutMs)}`,
        ],
      }

    case 'run-weakened':
      // The run itself was weakened: the semantic tier ran on the TEST stub (AC-3-5), or
      // above the default --semantic-threshold (I-1). NO OPS: the document is not at fault.
      // The repair is the plain invocation, which carries no threshold flag, with the stub
      // switch off for that one command when the stub ran (the Layer enables the stub only on
      // exactly `1`), so it loads the pinned model. One command discharges both causes.
      return {
        ops: [],
        commands: [
          context.run === undefined || context.run.embedder === 'stub'
            ? `SYMSPEC_EMBED_STUB=0 symspec check ${context.docPath}`
            : `symspec check ${context.docPath}`,
        ],
      }

    case 'semantic-tier-skipped':
      // NO OPS, and that is right: the tier was skipped by CONFIGURATION, so the
      // document is not at fault and no document change discharges it. The repair is
      // the invocation that runs the tier. As of G2b `--semantic` defaults ON, so
      // reaching this demotion means someone passed `--semantic=false` or the model
      // was unavailable — hence naming the env var too.
      return {
        ops: [],
        commands: [
          `symspec check ${context.docPath} --semantic`,
          `SYMSPEC_EMBED_ALLOW_REMOTE=1 symspec check ${context.docPath}`,
        ],
      }

    case 'contrary-glossary-alias':
      // A glossary entry names two contraries as one action. NO OPS: which alias to remove —
      // which of the two actions the author meant — is a judgment no run can make. The action
      // prose names the exact `glossary --remove` for each side; the commands are the reads.
      return {
        ops: [],
        commands: [
          ...demotion.requirementIds.map((id) => `symspec show ${id} ${context.docPath}`),
          `symspec check ${context.docPath}`,
        ],
      }

    case 'conditional-conflict-unchecked':
      // Two requirements demand opposite things of one response under guards the solver
      // never asserted together. NO OPS: whether the guards can co-occur is a fact about
      // the domain, and any edit that resolves it (or declares them exclusive) changes what
      // a requirement MEANS — a judgment no run can make. The commands are the reads an
      // agent needs to make it: both requirements, then the re-check.
      return {
        ops: [],
        commands: [
          ...demotion.requirementIds.map((id) => `symspec show ${id} ${context.docPath}`),
          `symspec check ${context.docPath}`,
        ],
      }

    case 'no-decide-tier-comparison':
      // No pair was compared: usually no two requirements shared an atom, else the pair
      // was an exact duplicate or its guards were never asserted together (the action
      // says which). The levers — a glossary or antonym link, deleting a copy, a rewrite —
      // are judgments about the document's meaning that no run can make. So the command
      // is the inspection that lets an agent decide, not a fabricated edit.
      return { ops: [], commands: [`symspec list ${context.docPath}`] }

    // ---------------------------------------------------------------------
    // The reason whose repair is INPUT, not an edit
    // ---------------------------------------------------------------------
    case 'uncovered-requirement': {
      // The discharge is a REWRITE: give the requirement vocabulary in common with
      // the requirements it relates to. No command performs a rewrite, and
      // synthesizing `symspec update --system-response "…"` would be inventing the
      // replacement text — the one thing a repair must never do.
      //
      // But "no command fixes this" is not the same as "no command helps". An agent
      // cannot rewrite a requirement it has not read, and it cannot choose shared
      // vocabulary without seeing what the rest of the document says. So the repair
      // is the two READS that produce exactly that input, in the order an agent
      // needs them: the requirement itself, then the document it must blend into.
      //
      // This is the honest middle: every demotion carries a runnable `repair`
      // (AC-A-1), and none of them pretends to author content.
      const id = demotion.requirementIds[0]
      if (id === undefined) return NO_REPAIR
      return {
        ops: [],
        commands: [
          `symspec show ${id} ${context.docPath}`,
          `symspec list ${context.docPath}`,
          `symspec check ${context.docPath}`,
        ],
      }
    }
  }
}

/**
 * Build the repair for a PROPOSE-ONLY candidate, from the finding that raised it.
 *
 * The semantic/quantity-alias findings BUILD their suggested invocation into their
 * message with the real verb heads or quantity labels substituted (see
 * `engine/formal/semantic.ts` and `engine/formal/quantity-alias.ts`). So the advice is
 * READ from the finding, never reconstructed — which means it cannot drift from what
 * the finding says, and a future change to the wording propagates for free.
 *
 * ## Why these reasons carry NO ops
 *
 * An opposition candidate's message deliberately offers TWO mutually-exclusive
 * remedies — an `antonym` link if the verbs are opposites, a `glossary` link if they
 * are synonyms — with an explicit warning that committing the wrong one MANUFACTURES
 * a false contradiction. Embeddings cannot tell which, because antonyms embed CLOSE.
 *
 * So emitting both as ops would hand an agent a plan that is wrong half the time and
 * catastrophic in one direction, and emitting one would be the tool picking — which is
 * exactly the propose/decide violation the architecture forbids. The commands carry
 * both, in the order the finding recommends trying them, for a reviewer to choose
 * from. Before spec 007 AC-5-6 the op was a reviewed waiver of the candidate; every code
 * raising these demotions is `triage` class, which is never waivable, so the fold now refuses
 * that op and the repair offers none. A pair that is not a conflict is reworded.
 *
 * That is the honest shape: nothing is applied blind where a human or agent has to decide.
 */
/**
 * The finding of `code` that raised `demotion`: the one naming exactly its ids, else one
 * sharing an id. One that merely shares an id belongs to another pair, so the exact match wins.
 */
const raisingFinding = (
  demotion: CoverageDemotion,
  sameCode: readonly CheckFinding[],
): CheckFinding | undefined => {
  const ids = new Set(demotion.requirementIds)
  return (
    sameCode.find(
      (f) => f.requirementIds.length === ids.size && f.requirementIds.every((id) => ids.has(id)),
    ) ?? sameCode.find((f) => f.requirementIds.some((id) => ids.has(id)))
  )
}

const fromFindingMessage = (
  demotion: CoverageDemotion,
  context: RepairContext,
  code: string,
): Repair => {
  const sameCode = context.findings.filter((f) => f.code === code)
  // The finding that raised THIS demotion names exactly its ids; one that merely shares an
  // id belongs to another pair, and reading its message would hand out the wrong merge.
  const finding = raisingFinding(demotion, sameCode)
  if (finding === undefined) return NO_REPAIR

  // NO OPS. Every code that raises one of these demotions is a triage candidate, and a triage
  // candidate is never waivable (spec 007 AC-5-6): it is discharged by committing the table
  // entry it proposes, or by rewording, and either changes what the solver decides. Which entry
  // is right is the propose/decide judgment no run can make, so the commands carry the
  // finding's own alternatives for a reviewer to choose from, and nothing is applied for them.
  //
  // A `symspec waive` a message spells is dropped from the commands for the same reason.
  const advice = extractSymspecCommands(finding.message).filter(
    (command) => !command.startsWith('symspec waive'),
  )
  return {
    ops: [],
    commands: [
      // The finding's own alternatives FIRST, in the order its reasoning recommends: a
      // committed glossary or antonym link lets the solver PROVE or dismiss the conflict.
      ...advice,
      `symspec check ${context.docPath}`,
    ],
  }
}

/**
 * Pull every backticked `symspec …` invocation out of a finding message, in order,
 * deduplicated, in the form the CLI accepts.
 *
 * Deliberately narrow: it matches only a backtick-delimited run that STARTS with
 * `symspec `, so surrounding prose, quoted code strings, and inline `code` spans
 * that are not commands are all ignored. A message that mentions two alternatives
 * (an antonym link if the verbs are opposites, a glossary link if they are synonyms)
 * yields both, in the order the message presents them — which is the order the
 * finding's own reasoning recommends trying them.
 *
 * ## Why the rewrite lives HERE
 *
 * An agent runs these verbatim — that is the contract this module exists to honour,
 * and the reason the header calls them RUNNABLE. A command that prints usage is
 * worse than no command: the agent reads exit 0, concludes the repair applied, and
 * re-checks to find nothing moved, which is indistinguishable from a repair that was
 * a legitimate no-op. So validity is enforced at the one seam every extracted command
 * passes through, rather than trusted at each of the eight messages that build one.
 *
 * The messages are the engine tier's shipped wording, spread across eight build
 * sites, so normalizing on read keeps the flat-surface fact in one place. Deduplication happens
 * AFTER the rewrite, so two spellings of one command collapse to one entry.
 */
const extractSymspecCommands = (message: string): readonly string[] => {
  const found: string[] = []
  for (const match of message.matchAll(/`(symspec [^`]+)`/g)) {
    const command = match[1]
    if (command === undefined) continue
    const normalized = runnable(command)
    if (!found.includes(normalized)) found.push(normalized)
  }
  return found
}

/**
 * THE ANCHORS — the intent and policy schemas, as a leaf module.
 *
 * `intent` says what a specification is FOR: the obligations, assumptions and goals its
 * requirements exist to serve. `policy` ranks those items into criticality levels. Both are
 * owned by a person, not by the agent writing requirements, so `check` treats them as fixed
 * points to compare against rather than as data an op may edit: no op in `ops.ts` writes
 * either one, and `save` never writes a split intent or policy file.
 *
 * ## Why this file imports `Schema` and nothing else
 *
 * A later certificate kernel reads these schemas to know what a requirement is for, and that
 * kernel's boundary admits only the typed IR and the solver port. A module that imports
 * nothing from this repository is the only shape it can import without taking the
 * requirements model with it. `src/package-boundary.test.ts` pins the single import. So the
 * patterns below are this file's own: {@link INTENT_ID_PATTERN} is asserted equal to the
 * requirement `KEY_PATTERN` by a test, not imported from it.
 *
 * ## Why no field has a decoding default
 *
 * `withDecodingDefaultKey` takes its default as an `Effect`, which this file does not import.
 * The rule that falls out is worth having for its own sake: the decoded anchor is exactly the
 * authored anchor, with nothing materialized, so a hash taken over the decoded value and a
 * hash taken over the file's content cannot disagree about a default. An absent `kind` reads
 * as {@link DEFAULT_INTENT_KIND} through {@link intentKindOf}, and an absent
 * `admissibleAssumptionKinds` reads as the empty list.
 *
 * ## Strict, and unique where a reference points
 *
 * Every struct is decoded with excess properties refused (the document decoder's setting), so
 * a typo'd field inside an anchor is a hard failure. An intent id is what a requirement's
 * `intentRef` names and a level id is what `assign` names, so a duplicate of either would
 * make a reference ambiguous; the decode refuses both, naming the duplicate. Whether an
 * `assign` key names an item that exists in `intent` is a question across two artifacts,
 * which may live in two files, so it is not asked here.
 */

import { Schema } from 'effect'

/** Multi-line description builder. */
const lines = (...xs: readonly string[]): string => xs.join('\n')

/**
 * What THIS release does with document format v4's vocabulary, intent and policy, and with a
 * requirement's `intentRef` and `derived`: it decodes them and writes them back, and no check
 * tier reads them. ONE constant, interpolated into every surface that describes them (the
 * schema descriptions the manifest and AGENTS.md derive from, `init --split`'s help and result,
 * the README), so no copy can drift into an enforcement claim (ruling RH-R3). Defined in this
 * leaf module because the intent and policy descriptions below carry it and this file imports
 * nothing from the repository; `document.ts` re-exports it.
 */
export const V4_EXPERIMENTAL_STATEMENT =
  'Experimental in this release: decoded and preserved on save, read by no check tier yet; its shape may change in a minor release.'

/** A non-empty string. */
const NonEmpty = Schema.String.pipe(Schema.check(Schema.isMinLength(1)))

/**
 * The intent-id format: the requirement key format (1-64 chars of `[A-Za-z0-9._-]`, at least
 * one non-digit, a leading alphanumeric), so one grammar names a requirement and the intent
 * item it serves. Flagless, because it lowers into the published JSON Schema as a `pattern`.
 */
export const INTENT_ID_PATTERN = /^(?=.*[A-Za-z._-])[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/

/** An intent item's id. */
export const IntentId = Schema.String.pipe(Schema.check(Schema.isPattern(INTENT_ID_PATTERN)))
export type IntentId = typeof IntentId.Type

/** A policy level's id, on the same format as an intent id. */
const LevelId = Schema.String.pipe(Schema.check(Schema.isPattern(INTENT_ID_PATTERN)))

/** A bare sha256 digest: 64 lowercase hex digits, with no `sha256:` prefix. */
export const SHA256_HEX_PATTERN = /^[0-9a-f]{64}$/

/** A bare sha256 digest. */
export const Sha256Hex = Schema.String.pipe(Schema.check(Schema.isPattern(SHA256_HEX_PATTERN)))

/**
 * What an intent item states.
 *
 * - `obligation`: something the system must do or ensure. Requirements bind to these.
 * - `assumption`: a fact about the environment the specification relies on.
 * - `goal`: a desired outcome, weaker than an obligation.
 */
export const INTENT_KINDS = ['obligation', 'assumption', 'goal'] as const
export type IntentKind = (typeof INTENT_KINDS)[number]

/** What an intent item with no `kind` states. */
export const DEFAULT_INTENT_KIND: IntentKind = 'obligation'

/** The `intentVersion` this build reads and writes. */
export const INTENT_VERSION = 1 as const

/** The `policyVersion` this build reads and writes. */
export const POLICY_VERSION = 1 as const

/** One intent item. */
export const IntentItem = Schema.Struct({
  id: IntentId.annotate({
    description: lines(
      'The stable id a requirement`s `intentRef` names. Same format as a requirement key.',
      'Unique within the intent. Examples: "I1"; "SAFETY-DOORS".',
    ),
  }),
  text: NonEmpty.annotate({
    description: lines(
      'The item, in the owner`s words. A later release will hold the specification to this text,',
      'so an edit to it changes what the specification is for.',
      "Example: 'The doors stay closed while the train is moving.'",
      V4_EXPERIMENTAL_STATEMENT,
    ),
  }),
  kind: Schema.optionalKey(
    Schema.Literals(INTENT_KINDS).annotate({
      description: lines(
        'What the item states: `obligation` (the system must do or ensure it), `assumption` (a fact',
        'about the environment the specification relies on) or `goal` (a desired outcome, weaker',
        'than an obligation). An absent kind reads as `obligation`; the decoder does not write it in.',
      ),
    }),
  ),
  source: Schema.optionalKey(
    NonEmpty.annotate({
      description:
        "Where the item came from, for a reader tracing it back. Free text. Example: 'ops memo 4, section 2'.",
    }),
  ),
}).annotate({ description: 'One item of intent: an obligation, assumption or goal, with its id.' })
export type IntentItem = typeof IntentItem.Type

/** The kind an intent item states, reading an absent kind as {@link DEFAULT_INTENT_KIND}. */
export const intentKindOf = (item: IntentItem): IntentKind => item.kind ?? DEFAULT_INTENT_KIND

/** The ids in `ids` that occur more than once, sorted. */
const duplicates = (ids: readonly string[]): readonly string[] => {
  const seen = new Set<string>()
  const repeated = new Set<string>()
  for (const id of ids) (seen.has(id) ? repeated : seen).add(id)
  return [...repeated].sort()
}

/** The intent artifact. */
export const Intent = Schema.Struct({
  intentVersion: Schema.Literal(INTENT_VERSION).annotate({
    description: 'The intent-format version. Exactly 1 for this format.',
  }),
  items: Schema.Array(IntentItem).annotate({
    description: lines(
      'The intent items, in the owner`s order. Item ids are unique. A later release will require',
      'each requirement to name one of them through `intentRef` or be marked `derived`; this one',
      'decodes a requirement with neither.',
      V4_EXPERIMENTAL_STATEMENT,
    ),
  }),
  source: Schema.optionalKey(
    Schema.Struct({
      importedFrom: NonEmpty.annotate({
        description: "The path or URL the intent was imported from. Example: 'parent/intent.json'.",
      }),
      sha256: Sha256Hex.annotate({
        description: 'The sha256 of the imported file`s bytes, as 64 lowercase hex digits.',
      }),
    }).annotate({
      description: 'Where this intent was imported from, when it was imported rather than written.',
    }),
  ),
})
  .annotate({
    description: lines(
      'What the specification is for: the obligations, assumptions and goals its requirements serve.',
      'Inline in the document (format v4) or in its own file. Written by its owner; no op writes it.',
      V4_EXPERIMENTAL_STATEMENT,
    ),
  })
  .pipe(
    Schema.check(
      Schema.makeFilter((intent: { readonly items: readonly { readonly id: string }[] }) => {
        const repeated = duplicates(intent.items.map((item) => item.id))
        return repeated.length === 0
          ? undefined
          : {
              path: ['items'],
              issue: `intent item ids must be unique; repeated: ${repeated.join(', ')}`,
            }
      }),
    ),
  )
export type Intent = typeof Intent.Type

/** One criticality level. */
export const PolicyLevel = Schema.Struct({
  id: LevelId.annotate({
    description: 'The level id that `assign` names. Unique within the policy. Example: "safety".',
  }),
  description: Schema.optionalKey(
    NonEmpty.annotate({
      description: "What an item at this level puts at stake. Example: 'Loss of life or injury.'",
    }),
  ),
}).annotate({ description: 'One criticality level.' })
export type PolicyLevel = typeof PolicyLevel.Type

/**
 * `assign`, keyed by intent id.
 *
 * `Schema.String` plus `isPropertyNames` rather than `Schema.Record(IntentId, …)`, because a
 * record's key schema FILTERS on this Effect version: a malformed key is dropped from the
 * decoded value without an error (the trap `document.ts`'s `RequirementsMap` documents).
 */
const Assign = Schema.Record(Schema.String, LevelId)
  .pipe(Schema.check(Schema.isPropertyNames(IntentId)))
  .annotate({
    description: lines(
      'The level of each intent item: intent id -> level id. Every level named must be declared in',
      '`levels`. Example: {"I1": "safety", "I2": "comfort"}.',
    ),
  })

/** The policy artifact. */
export const Policy = Schema.Struct({
  policyVersion: Schema.Literal(POLICY_VERSION).annotate({
    description: 'The policy-format version. Exactly 1 for this format.',
  }),
  levels: Schema.Array(PolicyLevel).annotate({
    description: lines(
      'The criticality levels, highest first. Array order is the yield order between levels, and no',
      'tier reads it yet. Level ids are unique.',
    ),
  }),
  assign: Assign,
  admissibleAssumptionKinds: Schema.optionalKey(
    Schema.Array(NonEmpty).annotate({
      description: lines(
        'Reserved: the kinds of environment fact an assumption may state. Read by no tier yet. An',
        'absent list reads as empty.',
      ),
    }),
  ),
})
  .annotate({
    description: lines(
      'How much each intent item matters: ordered criticality levels and the level of each item.',
      'Inline in the document (format v4) or in its own file. Written by its owner; no op writes it.',
      V4_EXPERIMENTAL_STATEMENT,
    ),
  })
  .pipe(
    Schema.check(
      Schema.makeFilter(
        (policy: {
          readonly levels: readonly { readonly id: string }[]
          readonly assign: Readonly<Record<string, string>>
        }) => {
          const ids = policy.levels.map((level) => level.id)
          const repeated = duplicates(ids)
          if (repeated.length > 0) {
            return {
              path: ['levels'],
              issue: `policy level ids must be unique; repeated: ${repeated.join(', ')}`,
            }
          }
          const declared = new Set(ids)
          const undeclared = [...new Set(Object.values(policy.assign))]
            .filter((level) => !declared.has(level))
            .sort()
          return undeclared.length === 0
            ? undefined
            : {
                path: ['assign'],
                issue: `assign names a level that \`levels\` does not declare: ${undeclared.join(', ')}`,
              }
        },
      ),
    ),
  )
export type Policy = typeof Policy.Type

/**
 * THE BOUNDARY — one function that projects a v3 document onto the v2-shaped view
 * the transplanted formal tier reads.
 *
 * ## Why the translation lives here and nowhere else
 *
 * The transplanted tier consumes `engine/core/schema.ts`'s `RequirementsDoc`: a
 * `schemaVersion` tag, a UUID-keyed requirement map, and the three side tables.
 * The v5 document is `../core/document.ts`'s `RequirementsDocument`: `docVersion`,
 * a `stateModel`, and per-requirement `responseKind`.
 *
 * Two places the conversion could go, and only one is defensible:
 *
 * - INSIDE the tier — translate at each of the ~40 files' call sites. That scatters
 *   the format bridge across 40 engine files, and every future question about the
 *   tier then starts with "is this the tier's behavior or the bridge's?".
 * - AT THE BOUNDARY — one function, here. The tier stays untouched, and there is
 *   exactly one place where a v3 document becomes the v2 view it reads.
 *
 * So: here.
 *
 * ## What is dropped, and why each drop is sound for G2a
 *
 * The projection is LOSSY in exactly two ways, both deliberate:
 *
 * 1. **`stateModel` is dropped.** Nothing in the G2a check path reads it — the
 *    reachability tier that will is G4, and G4's design is to encode the state
 *    model NATIVELY rather than through this v2 view. Dropping it here cannot
 *    silently degrade a verdict because no tier consults it; the moment one does,
 *    it will be a G4 tier that takes the v3 document directly.
 * 2. **`responseKind` is dropped.** Same argument: it is the effect-or-constraint
 *    classification the Horn encoder needs, and the propositional/numeric/temporal
 *    tiers do not read it. The v3 field exists so the classification is DATA rather
 *    than a retrofit (v4 V27); it does not yet have a consumer.
 *
 * Neither drop is a `verified` hazard, and that is checkable rather than asserted:
 * `compat.test.ts` proves the tier's output is identical whether or not a document
 * carries a state model, which is the same statement as "no tier reads it".
 *
 * ## What must NOT be lost, and is not
 *
 * `negated` and the rendered `sentence` are the two fields the atomizer and the
 * GtWR/AC-3-7 gate actually key on, and both survive verbatim. `negated` in
 * particular is load-bearing: it is what makes `shall X` and `shall not X` share
 * one atom at opposite polarity so a contradiction is provable rather than looking
 * like two unrelated strings. The v3 schema defaults it to `false` on decode, so
 * it is always present here.
 *
 * ## The `schemaVersion: 2` tag is a lie the tier never reads
 *
 * It is set because v4 type requires the field. Nothing in the check path
 * branches on it (measured: no reference outside the type declaration), so it is a
 * structural placeholder, not a claim that this is a v2 document. Stating that
 * here rather than leaving a bare `2` in the code is the difference between an
 * honest placeholder and a bug someone later "fixes" by writing 3.
 */

import type { Doc } from './engine/core/doc.ts'
import type { Requirement as EngineRequirement } from './engine/core/schema.ts'
import { requirementsContentHash } from './requirements/content-hash.ts'
import {
  CONTENT_HASH_PATTERN,
  type DocumentDiagnostic,
  type Requirement as DocumentRequirement,
  type RequirementsDocument,
  type Waiver,
} from './requirements/document.ts'
import { type FindingClass, findingClassOf, WAIVABILITY } from './waivability.ts'

/**
 * Project one v3 requirement onto v4's requirement shape.
 *
 * Optional fields are spread CONDITIONALLY rather than assigned `undefined`. The
 * v3 type is exact-optional (`exactOptionalPropertyTypes`), so an absent key is
 * genuinely absent, and preserving that distinction across the boundary matters:
 * the tier tests `trigger !== undefined`, and `{trigger: undefined}` vs `{}`
 * behaves the same for that test but differently under `JSON.stringify`. Keeping
 * absence as absence means a projected document serializes to the same bytes a
 * hand-written v2 document would, so anything that canonicalizes JSON — a fixture,
 * a snapshot, an envelope diff — sees no spurious change.
 */
export const toEngineRequirement = (r: DocumentRequirement): EngineRequirement => ({
  id: r.id,
  patternType: r.patternType,
  systemName: r.systemName,
  systemResponse: r.systemResponse,
  // Present on every decoded v3 requirement (the schema defaults it), and
  // load-bearing: this flag is what puts `shall X` and `shall not X` on one atom
  // at opposite polarity.
  negated: r.negated,
  sentence: r.sentence,
  priority: r.priority,
  status: r.status,
  // Edge arrays are `readonly` in v3 and mutable in the tier's type. Copied rather than
  // cast: the tier does not mutate them today, but sharing the array would make a future
  // mutation inside the engine reach back into the caller's document — an aliasing bug
  // in the most confusing possible place.
  derives: [...r.derives],
  satisfies: [...r.satisfies],
  verifies: [...r.verifies],
  refines: [...r.refines],
  createdAt: r.createdAt,
  updatedAt: r.updatedAt,
  ...(r.key !== undefined ? { key: r.key } : {}),
  ...(r.preCondition !== undefined ? { preCondition: r.preCondition } : {}),
  ...(r.trigger !== undefined ? { trigger: r.trigger } : {}),
  ...(r.verificationMethod !== undefined ? { verificationMethod: r.verificationMethod } : {}),
  ...(r.verificationNote !== undefined ? { verificationNote: r.verificationNote } : {}),
})

// ---------------------------------------------------------------------------
// Waivability at the boundary (spec 007 AC-5-6)
// ---------------------------------------------------------------------------

/**
 * Appended to the legacy reason of every replacement `waive` a `waiver-inert` diagnostic offers,
 * so the narrower waiver keeps its reviewer's words and says where it came from (ruling R41).
 */
export const RESCOPED_REASON_MARKER = ' (rescoped from a legacy waiver)'

/** Why a stored waiver does not reach the engine, when it does not. */
export type InertCause =
  /** No catalog publishes the code (an exact match: no trimming, no case folding). */
  | 'unclassified'
  /** The code's class is `never`: a verdict, disclosure, triage, hygiene or anchor finding. */
  | 'never'
  /** No requirement scope at all: a waiver by code reaches findings nobody reviewed. */
  | 'code-only'
  /** A scope but no content hash: bound to no reviewed text. */
  | 'no-hash'
  /** A scope naming a requirement the document no longer has, so the hash binds nothing. */
  | 'missing-requirement'
  /** Both scope fields at once, a shape no fold writes: which scope was reviewed is unknowable. */
  | 'both-scopes'
  /** A reason that is blank after trimming: no audit trail, a shape the fold refuses. */
  | 'blank-reason'
  /** A content hash that is not `sha256:` and 64 lowercase hex digits, a shape no fold writes. */
  | 'malformed-hash'

/**
 * What the waivability policy makes of ONE stored waiver at check time.
 *
 * - `qualifies`: a `scoped`-class code over named requirements whose current text matches the
 *   stored hash. Exactly these cross to the engine, as the exact set `ids`.
 * - `stale`: the same, but the text changed since the review. The finding comes back and the
 *   waiver is listed in `data.ignoredWaivers` for the new text to be re-reviewed.
 * - `inert`: anything the S3 fold would refuse as an op. Kept in the document, disclosed as a
 *   `waiver-inert` diagnostic, and never handed to the engine.
 */
export type WaiverStanding =
  | { readonly kind: 'qualifies'; readonly ids: readonly string[] }
  | {
      readonly kind: 'stale'
      readonly ids: readonly string[]
      readonly storedHash: string
      readonly currentHash: string
    }
  | { readonly kind: 'inert'; readonly cause: InertCause; readonly class?: FindingClass }

/** The requirement scope a stored waiver carries: its exact set, or its one requirement. */
const scopeOf = (w: Waiver): readonly string[] | undefined =>
  w.requirementIds ?? (w.requirementId !== undefined ? [w.requirementId] : undefined)

/**
 * Classify one stored waiver under the waivability policy — the check-time twin of the fold's
 * refusal (`MUTATE_OPTIONS.waiverPolicy`): a stored waiver reaches the engine exactly when the
 * fold would accept it as an op on this document and store it unchanged.
 *
 * The code is read EXACTLY as stored. The fold trims an op's code before classifying it, but a
 * stored ` FND_CONTRADICTION` never passed a fold, and folding case or whitespace here would
 * hand a hand-written variant of a `never` code the engine's exact-match `isWaived`.
 */
export const waiverStanding = (document: RequirementsDocument, w: Waiver): WaiverStanding => {
  const cls = findingClassOf(w.code)
  if (cls === undefined) return { kind: 'inert', cause: 'unclassified' }
  if (WAIVABILITY[cls] === 'never') return { kind: 'inert', cause: 'never', class: cls }
  // Only the shape the fold stores crosses (ruling R54): one scope field, a reason, an anchored hash.
  if (w.requirementId !== undefined && w.requirementIds !== undefined) {
    return { kind: 'inert', cause: 'both-scopes', class: cls }
  }
  if (typeof w.reason !== 'string' || w.reason.trim().length === 0) {
    return { kind: 'inert', cause: 'blank-reason', class: cls }
  }
  const ids = scopeOf(w)
  if (ids === undefined || ids.length === 0) {
    return { kind: 'inert', cause: 'code-only', class: cls }
  }
  if (w.contentHash === undefined) return { kind: 'inert', cause: 'no-hash', class: cls }
  if (!CONTENT_HASH_PATTERN.test(w.contentHash)) {
    return { kind: 'inert', cause: 'malformed-hash', class: cls }
  }
  const currentHash = requirementsContentHash(document, ids)
  if (currentHash === undefined) {
    return { kind: 'inert', cause: 'missing-requirement', class: cls }
  }
  return currentHash === w.contentHash
    ? { kind: 'qualifies', ids }
    : { kind: 'stale', ids, storedHash: w.contentHash, currentHash }
}

/** A finding as the boundary reads it: its code and the requirements it names. */
export interface FindingScope {
  readonly code: string
  readonly requirementIds: readonly string[]
}

/**
 * Whether a stored waiver reached `f` under the PRE-S3 matching (the code, then every scope it
 * carries: one requirement named, or exactly the set). The migration offers a scoped waive for
 * every finding a legacy waiver reaches this way today (ruling R18), so a reviewer re-scopes
 * what the waiver covered and nothing more.
 */
const reachedBefore = (w: Waiver, f: FindingScope): boolean => {
  if (f.code !== w.code) return false
  if (w.requirementIds !== undefined) {
    const want = new Set(w.requirementIds)
    const got = new Set(f.requirementIds)
    if (got.size !== want.size || ![...got].every((id) => want.has(id))) return false
  }
  return w.requirementId === undefined || f.requirementIds.includes(w.requirementId)
}

/** True when some finding names exactly `ids` under `code` — what an exact-set waiver bites. */
export const matchesFinding = (
  code: string,
  ids: readonly string[],
  findings: readonly FindingScope[],
): boolean =>
  findings.some((f) => reachedBefore({ code, requirementIds: ids, reason: 'probe' } as Waiver, f))

/** The exact `unwaive` of a stored waiver: its code and the scope it is stored under. */
const unwaiveOf = (w: Waiver): Readonly<Record<string, unknown>> => ({
  op: 'unwaive',
  code: w.code,
  ...(w.requirementId !== undefined ? { ref: w.requirementId } : {}),
  ...(w.requirementIds !== undefined ? { refs: [...w.requirementIds] } : {}),
})

/** A stored waiver as stored, for a diagnostic to name the row. */
const asStored = (w: Waiver): Readonly<Record<string, unknown>> => ({ ...w })

const quoted = (ids: readonly string[]): string => ids.join(', ')

/**
 * The `waiver-inert` diagnostic for a stored waiver the policy does not forward (`standing` is
 * its {@link waiverStanding}), or for a forwarded one that matches no finding (`standing`
 * `qualifies`, which only {@link unmatchedWaiverDiagnostic} passes).
 *
 * `findings` are the run's findings (every tier, unfiltered). For a `scoped` code the ops carry,
 * after the unwaive, one `waive` per finding the legacy waiver reaches today, over exactly that
 * finding's requirements and the hash of their current text, with the legacy reason and
 * {@link RESCOPED_REASON_MARKER} (rulings R18, R41). A `never` code gets the unwaive alone: the
 * finding is discharged only by rewriting what it names (R19).
 */
export const inertWaiverDiagnostic = (
  document: RequirementsDocument,
  w: Waiver,
  standing: Extract<WaiverStanding, { kind: 'inert' }>,
  findings: readonly FindingScope[],
): DocumentDiagnostic => {
  const scope = scopeOf(w)
  const rescoped =
    standing.cause === 'code-only' || standing.cause === 'no-hash'
      ? replacementWaives(document, w, findings)
      : []
  const detail = inertDetail(w, standing, rescoped.length)
  return {
    kind: 'waiver-inert',
    severity: 'info',
    detail,
    ...(scope !== undefined && scope.length > 0 ? { requirementIds: [...scope] } : {}),
    waiver: asStored(w),
    ops: [unwaiveOf(w), ...rescoped],
  }
}

/** One scoped `waive` per finding a legacy waiver reaches today, deduplicated by set. */
const replacementWaives = (
  document: RequirementsDocument,
  w: Waiver,
  findings: readonly FindingScope[],
): readonly Readonly<Record<string, unknown>>[] => {
  const seen = new Set<string>()
  const ops: Readonly<Record<string, unknown>>[] = []
  for (const f of findings) {
    if (!reachedBefore(w, f) || f.requirementIds.length === 0) continue
    const refs = [...new Set(f.requirementIds)].sort()
    const key = refs.join(',')
    if (seen.has(key)) continue
    const contentHash = requirementsContentHash(document, refs)
    if (contentHash === undefined) continue
    seen.add(key)
    ops.push({
      op: 'waive',
      code: w.code,
      refs,
      contentHash,
      reason: `${w.reason}${RESCOPED_REASON_MARKER}`,
    })
  }
  return ops
}

const inertDetail = (
  w: Waiver,
  standing: Extract<WaiverStanding, { kind: 'inert' }>,
  rescoped: number,
): string => {
  const head = `The stored waiver of ${w.code}`
  const remove = 'The op below removes it.'
  const rescope =
    rescoped > 0
      ? ` The ops below remove it and re-scope it to the ${rescoped === 1 ? 'finding' : `${rescoped} findings`} it reaches today, each over exactly that finding's requirements and the hash of their current text: review each before applying it.`
      : ` It reaches no finding today, so it offers no re-scoped waiver. ${remove}`
  switch (standing.cause) {
    case 'unclassified':
      return `${head} is inert: no catalog publishes that code, so it has no waivability class and \`check\` never applies it. ${remove}`
    case 'never':
      return `${head} is inert: ${w.code} is a ${standing.class}-class finding, which is never waivable, so \`check\` ignores the waiver and the finding stands. Rewrite required: change the requirement the finding names, or commit the antonym or glossary entry it proposes where the phrasings really are contraries or one action. ${remove}`
    case 'code-only':
      return `${head} names no requirement, so it is inert: a waiver by code alone would reach every finding of the code, including ones nobody reviewed.${rescope}`
    case 'no-hash':
      return `${head} over ${quoted(scopeOf(w) ?? [])} carries no content hash, so it is bound to no reviewed text and is inert.${rescope}`
    case 'missing-requirement':
      return `${head} names a requirement the document no longer has, so its content hash binds no text and it is inert. ${remove}`
    case 'both-scopes':
      return `${head} carries both "requirementId" and "requirementIds", a shape no fold writes, so which scope was reviewed cannot be known and it is inert. ${remove}`
    case 'blank-reason':
      return `${head} has a blank reason, so it records no review and is inert. ${remove}`
    case 'malformed-hash':
      return `${head} carries a content hash that is not \`sha256:\` and 64 hex digits, so it binds no text and is inert. ${remove}`
  }
}

/**
 * The `waiver-inert` diagnostic for a forwarded waiver whose requirement set matches no finding:
 * the engine reads a scope as the EXACT set, so it suppressed nothing. Its unwaive alone — a
 * stored exact set matched no finding before S3 either (ruling R38).
 */
export const unmatchedWaiverDiagnostic = (w: Waiver): DocumentDiagnostic => {
  const scope = scopeOf(w) ?? []
  return {
    kind: 'waiver-inert',
    severity: 'info',
    detail: `The stored waiver of ${w.code} over ${quoted(scope)} matches no finding: no finding of the code names exactly those requirements, so it suppresses nothing. The op below removes it.`,
    requirementIds: [...scope],
    waiver: asStored(w),
    ops: [unwaiveOf(w)],
  }
}

/**
 * One `data.ignoredWaivers` entry: a stale-hash waiver of a `scoped` code (ruling R21, R42). The
 * text it was reviewed on changed, so the finding is back; the entry offers the unwaive only,
 * because a waive at the new hash would certify text nobody has read.
 */
export interface IgnoredWaiver {
  readonly code: string
  readonly requirementIds: readonly string[]
  readonly storedHash: string
  readonly currentHash: string
  readonly reason: string
  readonly note: string
  readonly ops: readonly Readonly<Record<string, unknown>>[]
}

export const ignoredWaiverEntry = (
  w: Waiver,
  standing: Extract<WaiverStanding, { kind: 'stale' }>,
): IgnoredWaiver => ({
  code: w.code,
  requirementIds: [...standing.ids],
  storedHash: standing.storedHash,
  currentHash: standing.currentHash,
  reason: w.reason,
  note: `The text of ${quoted(standing.ids)} changed since this waiver was reviewed (stored ${standing.storedHash}, now ${standing.currentHash}), so it no longer applies and its finding is back. Re-review the new text: if the finding still does not apply, accept it again from that finding's own repair; the op below removes the stale waiver.`,
  ops: [unwaiveOf(w)],
})

/**
 * Project a v3 document onto v4's document shape — the ONE boundary
 * crossing.
 *
 * Requirement ORDER is preserved by construction: `Object.entries` on the v3 map
 * feeds a fresh object in the same sequence, and `listRequirements` is a plain
 * `Object.values`. That is not incidental — the order feeds the atom roster and
 * the candidate-pair emission, so re-ordering here would change `pairsChecked`
 * and therefore the coverage report, while leaving every finding intact. Exactly
 * the kind of divergence that looks like noise in a diff.
 */
export const toEngineDoc = (document: RequirementsDocument): Doc => {
  const requirements: Record<string, EngineRequirement> = {}
  for (const [id, r] of Object.entries(document.requirements)) {
    requirements[id] = toEngineRequirement(r)
  }
  return {
    // A structural placeholder the tier never reads — see the module header.
    schemaVersion: 2,
    requirements,
    glossary: document.glossary.map((g) => ({ canonical: g.canonical, aliases: [...g.aliases] })),
    antonyms: document.antonyms.map((a) => ({ a: a.a, b: a.b })),
    // Only a waiver the waivability policy lets in crosses (spec 007 AC-5-6, R22): a `scoped`
    // code over named requirements whose text still matches the reviewed hash. It crosses as the
    // EXACT set — a stored single `requirementId` too, as `[id]` (R39) — bound to the text, so
    // the engine's own matching cannot widen it. Dropping a waiver can only put a finding back,
    // never invent one, so every other shape stays behind and is disclosed by `check`.
    waivers: document.waivers.flatMap((w) => {
      const standing = waiverStanding(document, w)
      return standing.kind === 'qualifies'
        ? [{ code: w.code, reason: w.reason, requirementIds: [...standing.ids], textBound: true }]
        : []
    }),
    terms: document.terms.map((t) => ({ canonical: t.canonical, aliases: [...t.aliases] })),
  }
}

/**
 * `FND_*` finding codes enumeration — the closed, append-only set of finding
 * codes the calling agent switches on (Appendix B, spec.md).
 *
 * Every finding symspec emits carries a `{ code, severity, … }` shape whose
 * `code` is one of these. The catalog spans all four tiers:
 *
 *   - Tier 0 structural (AC-3-5/3-6): DANGLING_REFERENCE, MISSING_TRIGGER,
 *     MISSING_PRECONDITION, CYCLE, ORPHAN
 *   - Lint free tier (AC-3-1): EXACT_DUPLICATE  (GtWR rule codes are the
 *     separate `GtwrCodeSchema` catalog in src/lint/codes.ts)
 *   - Formal SMT tier (AC-4-4/4-5/4-7/4-12): CONTRADICTION, SUBSUMPTION,
 *     REDUNDANCY, VACUITY, SIMILAR_UNUNIFIED, NEEDS_REVIEW
 *   - Completeness heuristic (AC-4-5a): INCOMPLETE
 *   - Certify Lean tier (AC-5-2/5-3): CERTIFIED, CERTIFY_FAILED
 *
 * ## Reachability bridges (AC-6-3 "each documented code is reachable")
 *
 * Two producer surfaces do not yet emit their `FND_*` code as a string
 * literal — they discriminate on other fields for historical reasons:
 *
 *   - the Tier-0 structural pass (`core/analyze.ts`) tags findings with a
 *     `kind` (`'DanglingReference'` …); {@link structuralKindToFndCode} is the
 *     canonical, single-source mapping from that `kind` to its `FND_*` code.
 *   - the free-tier exact-duplicate solver tags `kind: 'ExactDuplicate'`;
 *     {@link solverKindToFndCode} maps it to `FND_EXACT_DUPLICATE`.
 *   - the certify tier returns a `certified` boolean; {@link certifiedToFndCode}
 *     maps that verdict to `FND_CERTIFIED` / `FND_CERTIFY_FAILED`.
 *
 * These bridges live here so the code catalog is genuinely single-sourced and
 * the AC-6-3 reachability test can assert every documented code is produced by
 * a real emitter path (either a direct `code:` literal or one of these maps),
 * not merely enumerated.
 *
 * ## Single-source `.describe()` corpus + append-only (AC-6-3)
 *
 * {@link FndCodeMeta} carries a per-code `.describe()`; the manifest (AC-6-1)
 * reads it to build its FND table. `satisfies Record<FndCode, …>` forces the
 * corpus to cover EXACTLY the enum members. Never renumber or remove a code;
 * new codes append to the END. A snapshot test guards this for FND_* alongside
 * the ERR_* and GTWR_* catalogs.
 *
 * Cite: AC-6-3 (three exported enums, FND_* is the third); Appendix B
 * (normative finding-code enum); AC-3-5/3-6, AC-4-4/4-5/4-5a/4-7/4-12, AC-5-2/5-3.
 */

/**
 * `FND_*` finding codes — the closed enum an agent switches on. Grouped by
 * tier to match Appendix B's table order. Append-only; never renumber or
 * remove.
 *
 * ## Zod removed (transplant edit #3 of 4)
 *
 * v4 declared this as `z.enum([...])` plus a parallel `FndCodeMeta` of
 * `z.literal(code).describe(text)` bound by `satisfies Record<FndCode, …>`. The
 * greenfield does not ship Zod (spec: "Zod (greenfield is Effect Schema native;
 * no bridge needed)"), so the enum is a `const` tuple and the meta corpus is a
 * plain record — the same two artifacts, the same `satisfies` bound, no schema
 * library.
 *
 * The 30 code strings and all 30 description texts below were extracted
 * PROGRAMMATICALLY from the live v4's `FndCodeMeta` (`.description` off each
 * described literal), not retyped, so they are byte-identical to v4's
 * agent-facing text. `codes.test.ts` re-extracts from v4 and diffs, so a
 * divergence is a test failure rather than a silent drift.
 */
export const FND_CODES = [
  // Tier 0 — structural (AC-3-5, AC-3-6)
  'FND_DANGLING_REFERENCE',
  'FND_MISSING_TRIGGER',
  'FND_MISSING_PRECONDITION',
  'FND_CYCLE',
  'FND_ORPHAN',
  // Lint — free tier (AC-3-1)
  'FND_EXACT_DUPLICATE',
  // Formal tier — SMT (AC-4-4, AC-4-5, AC-4-7, AC-4-12)
  'FND_CONTRADICTION',
  'FND_SUBSUMPTION',
  'FND_REDUNDANCY',
  'FND_VACUITY',
  'FND_SIMILAR_UNUNIFIED',
  'FND_NEEDS_REVIEW',
  // Completeness heuristic — lint tier (AC-4-5a)
  'FND_INCOMPLETE',
  // Certify tier — Lean (AC-5-2, AC-5-3)
  'FND_CERTIFIED',
  'FND_CERTIFY_FAILED',
  // Semantic paraphrase-bridging tier (AC-9-5) — propose-only, never a verdict
  'FND_SIMILAR_SEMANTIC',
  // Numeric/arithmetic conflict tier (AC-30-3) — deterministic verdict (LIA/LRA)
  'FND_NUMERIC_CONTRADICTION',
  // DAG well-formedness (AC-32-3) — deterministic structural verdict
  'FND_LEAF_UNVERIFIABLE',
  // Embedding-graph proposals (AC-32-2/4) — propose-only, never a verdict
  'FND_MISSING_TRACE_LINK',
  'FND_DUPLICATE_CLUSTER',
  // Ambiguity family (AC-31-1/2/3/5) — deterministic detectors + structured punt
  'FND_AMBIGUOUS_VAGUE',
  'FND_AMBIGUOUS_QUANTIFIER',
  'FND_AMBIGUOUS_REFERENCE',
  'FND_AMBIGUITY_NEEDS_JUDGMENT',
  // Bounded temporal tier (AC-33-2) — sound-for-UNSAT verdict over a trace bound
  'FND_TEMPORAL_CONTRADICTION',
  // Formal-coverage disclosure (appended) — the formal tier evaluated ZERO
  // pairs (usually because no two requirements shared an atom), so `check` performed no
  // cross-requirement conflict analysis. An info finding so silence that looks
  // like a pass is loud instead.
  'FND_NO_PAIRS_CHECKED',
  // Opposition-candidate proposal (appended — #6) — two same-system responses
  // that share an object but differ on the leading verb, a likely antonym pair
  // the seed/committed antonym tables did not unify. Propose-only, info-tier:
  // it suggests `symspec antonym add`, never a verdict.
  'FND_OPPOSITION_CANDIDATE',
  // Formal-exclusion disclosure (appended) — a requirement was dropped from the
  // formal (SMT) tier because an error-severity lint/parse finding blocked its
  // surface. `verified` cannot cover a requirement the solver never saw, so this
  // is a first-class LOUD signal (not buried in residualRisk) and DEMOTES
  // `verified`. Info-tier, one per excluded requirement.
  'FND_EXCLUDED_FROM_FORMAL',
  // Quantity-alias proposal (appended) — two co-active numeric bounds (same
  // system, same guard, or both unguarded) land on DIFFERENT quantity keys
  // that nonetheless share a noun token (e.g. "complete the infusion within ≤30
  // min" vs "run the infusion for ≥60 min"). The bounds may constrain ONE
  // physical quantity the verb phrasing split apart. Propose-only: suggests
  // `symspec glossary add` to unify the quantities so the LIA tier can compare
  // their bounds. Never a verdict; it DEMOTES `verified` because a possible
  // numeric conflict went unexamined.
  'FND_QUANTITY_ALIAS_CANDIDATE',
  // Relational-reasoning disclosure (appended) — requirements under one shared
  // trigger carry numeric bounds AND unmatched (singleton) atoms, the shape
  // where aggregate/conservation or cross-quantity relational conflicts hide.
  // symspec's numeric tier is pairwise same-quantity only; it does NOT attempt
  // aggregate sums or cross-quantity arithmetic. Info-tier, DEMOTES `verified`
  // so "verified" never outruns what the solver actually compared.
  'FND_RELATIONAL_UNCHECKED',
  // Numeric-uncompared disclosure (appended, spec 007 AC-2-5/AC-2-6) — co-live bounds
  // on ONE quantity key that the numeric tier neither proved nor dismissed: a deadline
  // and a duration it keeps on two variables, a °F/K bound whose absolute and
  // difference readings disagree, or two units no conversion relates. Info-tier,
  // DEMOTES `verified`; never a verdict.
  'FND_NUMERIC_UNCOMPARED',
  // Number-spelling proposal (appended, spec 007 AC-2-4) — two requirements write one
  // phrase with numbers that differ only in a digit separator (`1.5` / `1,5`, `1_500` /
  // `1.500`), so they land on two atoms. Whether they are one number depends on the
  // decimal convention, which no closed rule fixes. Info-tier, DEMOTES `verified`;
  // never a verdict.
  'FND_NUMBER_SPELLING_CANDIDATE',
] as const

