/**
 * The Tier-0 structural pass (`core/analyze.ts`) discriminant `kind` → its
 * `FND_*` code. This is the single source of that correspondence; the `check`
 * wiring (AC-6-8) and the reachability test both read it.
 */
export const structuralKindToFndCode = {
  DanglingReference: 'FND_DANGLING_REFERENCE',
  MissingTrigger: 'FND_MISSING_TRIGGER',
  MissingPreCondition: 'FND_MISSING_PRECONDITION',
  CycleDetected: 'FND_CYCLE',
  OrphanRequirement: 'FND_ORPHAN',
  LeafUnverifiable: 'FND_LEAF_UNVERIFIABLE',
} as const satisfies Record<string, FndCode>

/**
 * The free-tier solver discriminant `kind` → its `FND_*` code. Only the
 * exact-duplicate solver maps to an `FND_*` code here; the pairwise/formal
 * kinds surface under the formal-tier codes above.
 */
export const solverKindToFndCode = {
  ExactDuplicate: 'FND_EXACT_DUPLICATE',
} as const satisfies Record<string, FndCode>

/** The certify verdict boolean → its `FND_*` code (AC-5-2/5-3). */
export function certifiedToFndCode(certified: boolean): FndCode {
  return certified ? 'FND_CERTIFIED' : 'FND_CERTIFY_FAILED'
}

/**
 * `FND_NUMBER_SPELLING_CANDIDATE` — a phrase whose numbers differ only in a digit separator
 * (spec 007 AC-2-4; the demote-not-prove contract).
 *
 * ## The pair this demotes
 *
 * `normalize` keeps a `,` or `.` between two digits inside its number, because the separator
 * decides which number it is: the numeric tier reads `1,500 ms` as 1500 ms and `1.500 ms` as
 * 1.5 ms. When the separator was deleted, `1,500` and `1.500` shared one atom and the
 * propositional tier proved `respond within 1,500 ms` / `not respond within 1.500 ms`, a
 * consistent pair. The same deletion also collapsed `1.5` with a decimal-comma `1,5`, and
 * `1_500` with a European `1.500`, where the proof was right. Keeping the separator stops the
 * false proof, but it leaves each of those pairs on two atoms, and when another requirement
 * covers each atom nothing else in the check names the pair: exit 0, `verified: true`.
 *
 * ## Why this demotes and never proves
 *
 * No closed rule says whether `1,500` and `1.500` are one number: it depends on the author's
 * decimal convention. A proof may rest only on exact keys, so the two atoms stay apart, and this
 * tier names the pair instead: a propose-only info finding for every pair of requirements with
 * two different atoms (or two different antonym keys) whose {@link digitSeparatorFold} is equal,
 * that is, every pair the old deletion collapsed and the split separated. Its demotion is
 * discharged by spelling the number identically in both requirements, which puts them on one
 * atom where the solver compares them, or by a reviewed waiver when they are different numbers.
 * Polarity is not read: one spelling per number is the repair either way, and a demotion is
 * always sound.
 */

import { digitSeparatorFold } from './atomize.ts'
import type { EncodedRequirement } from './encode.ts'

/** A propose-only number-spelling finding (info; DEMOTES `verified`). */
export interface NumberSpellingCandidateFinding {
  readonly code: 'FND_NUMBER_SPELLING_CANDIDATE'
  readonly severity: 'info'
  /** The two requirement ids, sorted. */
  readonly requirementIds: [string, string]
  readonly message: string
}

/** One identity a requirement's atom row carries: its atom name, or its antonym key. */
interface Spelling {
  readonly id: string
  readonly identity: string
  readonly slotText: string
  /** The identity the same row has in fold space, tables included (see `folded` below). */
  readonly foldedIdentity: string
}

/** A row's identities, atom name first: two namespaces (U+0000 cannot occur in either). */
const identitiesOf = (row: EncodedRequirement['atoms'][number]): string[] => [
  `atom\u0000${row.atom}`,
  ...(row.opposition !== undefined ? [`key\u0000${row.opposition.key}`] : []),
]

/**
 * Every pair of requirements that write one phrase with numbers differing only in a digit
 * separator, sorted by id pair. At most one finding per pair (the first split found).
 *
 * `folded[i]` is `encoded[i]` re-encoded through `makeDigitSeparatorFoldAtomize`: the same
 * requirement with every digit separator, in its slots AND in the committed glossary and term
 * tables, read as a token boundary. Two rows that share an identity there but not in `encoded`
 * are a split the fold of the atoms alone cannot see, because a table alias spelled with the other
 * separator rewrote only one of them. Omitted, each row's fold space is the fold of its own atom
 * (a table-free document).
 */
export function findNumberSpellingCandidates(
  encoded: readonly EncodedRequirement[],
  folded?: readonly EncodedRequirement[],
): NumberSpellingCandidateFinding[] {
  const spellings: Spelling[] = encoded.flatMap((e, i) =>
    e.atoms.flatMap((row, k) => {
      const foldedRow = folded?.[i]?.atoms[k]
      const foldedIds = foldedRow !== undefined ? identitiesOf(foldedRow) : []
      return identitiesOf(row).map((identity, n) => ({
        id: e.id,
        identity,
        slotText: row.slotText,
        foldedIdentity: foldedIds[n] ?? digitSeparatorFold(identity),
      }))
    }),
  )
  // Fold -> the spellings under it. Every spelling sits under the fold of its own identity and
  // under its fold-space identity. Two spellings with no separator anywhere fold to themselves, so
  // a class can pair two DIFFERENT identities only through a separator.
  const byFold = new Map<string, Spelling[]>()
  for (const s of spellings) {
    for (const fold of new Set([digitSeparatorFold(s.identity), s.foldedIdentity])) {
      byFold.set(fold, [...(byFold.get(fold) ?? []), s])
    }
  }

  const found = new Map<string, NumberSpellingCandidateFinding>()
  for (const members of byFold.values()) {
    for (let i = 0; i < members.length; i++) {
      for (let j = i + 1; j < members.length; j++) {
        const x = members[i] as Spelling
        const y = members[j] as Spelling
        if (x.id === y.id || x.identity === y.identity) continue
        const [lo, hi] = x.id < y.id ? [x, y] : [y, x]
        const key = `${lo.id}|${hi.id}`
        if (found.has(key)) continue
        // Their own atoms fold apart, so only a committed alias related them in fold space.
        const viaTable = digitSeparatorFold(lo.identity) !== digitSeparatorFold(hi.identity)
        found.set(key, {
          code: 'FND_NUMBER_SPELLING_CANDIDATE',
          severity: 'info',
          requirementIds: [lo.id, hi.id],
          message: viaTable
            ? `${lo.id} ("${lo.slotText}") and ${hi.id} ("${hi.slotText}") would share one ` +
              'atom through a committed glossary or term alias if a digit separator in it were ' +
              'spelled the way the requirement spells it, so they are two atoms and the solver ' +
              'never compared them. A `,` or `.` between digits is a thousands separator in one ' +
              'convention and a decimal point in the other, so symspec does not decide whether ' +
              'the alias and the requirement write one number. If they do, rewrite the ' +
              'requirement with `symspec update --ref <id> <attr> "<wording>"` (or re-commit the alias) so both spell the ' +
              'number identically, and re-run `symspec check`. If they are different numbers, ' +
              'rewrite one so both follow one separator convention, and the solver compares the ' +
              'two numbers as written. This is a suggestion, not a verdict.'
            : `${lo.id} and ${hi.id} write the same phrase with numbers that differ only in a ` +
              `digit separator ("${lo.slotText}" vs "${hi.slotText}"), so they are two atoms and ` +
              'the solver never compared them. A `,` or `.` between digits is a thousands ' +
              'separator in one convention and a decimal point in the other, so symspec does not ' +
              'decide whether they are one number. If they are, rewrite one requirement with ' +
              '`symspec update --ref <id> <attr> "<wording>"` so both spell the number identically: they then share one atom ' +
              'and re-running `symspec check` proves any conflict. If they are different ' +
              'numbers, rewrite one so both follow one separator convention, and the solver ' +
              'compares the two numbers as written. This is a suggestion, not a verdict.',
        })
      }
    }
  }
  return [...found.values()].sort((a, b) => {
    const ka = a.requirementIds.join('|')
    const kb = b.requirementIds.join('|')
    return ka < kb ? -1 : ka > kb ? 1 : 0
  })
}

/**
 * Quantity-alias candidate detection (propose-only).
 *
 * ## The blind spot this closes
 *
 * The numeric tier (`numeric.ts` → `numeric-contradiction.ts`) proves a conflict
 * only when two bounds land on the SAME per-system quantity key. That key is the
 * whole phrase before the comparator, so the SAME physical quantity described with
 * two different verbs splits into two keys and the joint bound is never seen:
 *
 *     "complete the infusion within at most 30 minutes"  → qty `complete_the_infusion_within`  (≤ 30 min)
 *     "run the infusion for at least 60 minutes"         → qty `run_the_infusion`              (≥ 60 min)
 *
 * ≤ 30 ∧ ≥ 60 on one duration is UNSAT, but the two keys never meet, so nothing in
 * the decide tier can prove it (GitHub issue #2, reproducer a). This tier is what
 * stops `check` certifying such a document.
 *
 * This tier is a DISCLOSER, so it pairs on the COARSE unit class (`numeric.ts`
 * `unitClassOf`), never on the bound's role. The decide tier keeps two different
 * marked roles apart (`complete the infusion within 30 minutes` is a deadline, `run
 * the infusion for at least 60 minutes` a duration — spec 007 AC-2-6), and pairing on
 * that finer key deleted this candidate on issue #2's own reproducer, which then
 * certified (`.erpaval/solutions/architecture/a-finer-key-is-not-uniformly-safer.md`).
 * When the two roles are ones the decide tier would still keep apart under one key,
 * the message says so: the `glossary add` still records that the phrasings are one
 * quantity, and the pair then meets on one key where `FND_NUMERIC_UNCOMPARED`
 * discloses it rather than proves it.
 *
 * ## Why this is propose-only, not an automatic merge
 *
 * We must NOT strip the verb and force the two keys together: "transmit the
 * packet" and "receive the packet" also share the object "the packet" but are
 * genuinely different quantities — auto-merging them would MANUFACTURE a false
 * numeric contradiction. Whether two verb-phrasings name one physical quantity
 * is an authoring judgment, exactly like the paraphrase/opposition proposals
 * (`semantic.ts`). So this tier follows the same PROPOSE/DECIDE discipline:
 *
 *   - PROPOSE (here, deterministic + conservative): flag CO-ACTIVE numeric bounds
 *     — one system and one GUARD key (precondition and trigger together), where
 *     two wholly unguarded requirements share the always-on context — whose
 *     quantity labels share a common object SUFFIX
 *     but differ in their leading verb, and whose comparators are
 *     directionally OPPOSED (one upper, one lower) in a comparable unit — the
 *     only shape that could be jointly unsatisfiable if unified. Emit an
 *     info-tier `FND_QUANTITY_ALIAS_CANDIDATE` carrying a ready-to-run
 *     `symspec glossary add` command. This DEMOTES `verified` (a possible
 *     numeric conflict went unexamined) but is never a verdict.
 *   - DECIDE (elsewhere, already built): if the author confirms the quantities
 *     are one, `symspec glossary add "<a>" "<b>"` commits the alias; `atomize`
 *     /`quantityKey` route both labels' normalized form to one canonical key, so
 *     the existing LIA tier compares the bounds and proves the conflict.
 *
 * ## High precision by design
 *
 * The common-suffix + differing-verb-prefix test is the specific signature of
 * "one quantity, two verbs". It deliberately does NOT fire on labels that share
 * a leading noun but differ in their tail ("account balance" vs "account age") —
 * those are distinct quantities that merely start the same, not a verb split.
 */

import { normalize, normalizeScope } from './atomize.ts'
import {
  type NumericPredicate,
  opposedComparators,
  rolesCompatible,
  unitClassOf,
} from './numeric.ts'

/** One requirement's numeric predicates + the context needed to group it. */
export interface QuantityAliasInput {
  readonly id: string
  /** Per-system scope (predicates already bake this into their quantity key). */
  readonly systemName: string
  /**
   * Normalized guard context spanning BOTH EARS guard slots (precondition and
   * trigger). `''` means genuinely unguarded — no precondition AND no trigger —
   * which is the only state that licenses the "both bounds always hold" claim in
   * this tier's message. Built by `pipeline/check.ts`'s `guardKeyOf`.
   */
  readonly guardKey: string
  readonly predicates: readonly NumericPredicate[]
}

/** A propose-only quantity-alias-candidate finding (info; DEMOTES `verified`). */
export interface QuantityAliasCandidateFinding {
  readonly code: 'FND_QUANTITY_ALIAS_CANDIDATE'
  readonly severity: 'info'
  /** The two requirement ids whose bounds might constrain one quantity. */
  readonly requirementIds: string[]
  readonly message: string
}

/** Tokens that are never the shared "object" of a quantity label. */
const LABEL_STOPWORDS: ReadonlySet<string> = new Set([
  'a',
  'an',
  'the',
  'of',
  'to',
  'for',
  'by',
  'at',
  'in',
  'on',
  'with',
  'its',
  'their',
  // Comparator / bound words that the numeric keyer leaves ON the label when
  // they lead a compound bound ("complete the infusion WITHIN at most 30 min" →
  // label "complete the infusion within"). We drop them HERE, in the propose-only matcher,
  // rather than in numeric.ts's KEY — stripping them from the sound key would
  // collapse phrasal-verb nouns ("carry OVER" vs "carry") and fabricate a false
  // contradiction. Dropping them only for object-suffix comparison is safe: this
  // tier can only DEMOTE + suggest a glossary alias, never assert a conflict.
  'within',
  'under',
  'over',
  'above',
  'below',
  'exceeding',
  'exceed',
])

/** Split a quantity label into lowercased word tokens (drops articles/preps). */
function contentTokens(label: string): string[] {
  return normalize(label)
    .split('_')
    .filter((t) => t.length > 0 && !LABEL_STOPWORDS.has(t))
}

/**
 * The "one quantity, two verbs" signature: the two labels share a non-empty
 * common SUFFIX of content tokens (the object noun phrase) and each has a
 * non-empty, DIFFERING residual prefix (the leading verb). Returns the shared
 * object phrase (for the message) or null when the shape does not hold.
 */
function sharedObjectSuffix(labelA: string, labelB: string): string | null {
  const a = contentTokens(labelA)
  const b = contentTokens(labelB)
  if (a.length === 0 || b.length === 0) return null
  let n = 0
  while (n < a.length && n < b.length && a[a.length - 1 - n] === b[b.length - 1 - n]) n += 1
  if (n === 0) return null // no shared object → not the same quantity
  const prefixA = a.slice(0, a.length - n)
  const prefixB = b.slice(0, b.length - n)
  // The two labels must DIFFER in their residual prefix (the verb/qualifier that
  // split one object into two keys). We do NOT require BOTH prefixes to be
  // non-empty: a slot that names the quantity with no verb ("the infusion within
  // at most 30 min" → ["infusion"]) still pairs with one that has a verb ("run the
  // infusion" → ["run","infusion"]), and that pair is the same-quantity-two-verbs
  // shape. Equal prefixes would mean identical token lists (already keyed together
  // by the numeric tier, and the caller skips pa.quantity === pb.quantity anyway),
  // so reject only that.
  if (prefixA.join('_') === prefixB.join('_')) return null
  return a.slice(a.length - n).join(' ')
}

/**
 * Find quantity-alias candidates across a set of requirements' numeric
 * predicates. Deterministic and conservative — a false negative (missed
 * suggestion) is preferred over a false positive that nags the author. Emits at
 * most one finding per requirement pair (the first opposed, object-sharing bound
 * pair found), keyed by sorted id pair so the output is order-independent.
 */
export function findQuantityAliasCandidates(
  inputs: readonly QuantityAliasInput[],
): QuantityAliasCandidateFinding[] {
  const findings: QuantityAliasCandidateFinding[] = []
  const emittedPairs = new Set<string>()

  for (let i = 0; i < inputs.length; i += 1) {
    for (let j = i + 1; j < inputs.length; j += 1) {
      const ra = inputs[i]!
      const rb = inputs[j]!
      if (ra.id === rb.id) continue
      // Same context: same system and the SAME guard key, where two EMPTY keys
      // are the same context — a pair of wholly unguarded requirements is
      // unconditional, so the two bounds always hold together. Requirements under
      // DIFFERENT guards do not co-occur, so their bounds cannot form a
      // single-quantity conflict worth surfacing. Refusing the always-on context
      // would leave the most co-active pair in the document unexamined and
      // uncounted: an under-demotion, the one direction a propose-only tier can be
      // wrong in, since it can only ever push `verified` false.
      //
      // The key spans BOTH guard slots, which is what makes two mutually exclusive
      // PRECONDITIONS ("while the tank is full" vs "while the tank is empty")
      // different contexts, so this pair is skipped. A key built from `trigger`
      // alone maps every precondition-guarded requirement to `''`: it co-asserts
      // guards the document keeps apart, and it makes the message below claim "no
      // trigger" about a document that has two.
      // Same system by atom scope, never the raw name: a case or punctuation variant of one
      // system is one scope, and a discloser that is finer than the scope under-discloses.
      if (normalizeScope(ra.systemName) !== normalizeScope(rb.systemName)) continue
      if (ra.guardKey !== rb.guardKey) continue

      const pairKey = [ra.id, rb.id].sort().join('|')
      if (emittedPairs.has(pairKey)) continue

      let hit: { pa: NumericPredicate; pb: NumericPredicate; object: string } | null = null
      for (const pa of ra.predicates) {
        for (const pb of rb.predicates) {
          // Already the same quantity → the numeric tier handles it; skip.
          if (pa.quantity === pb.quantity) continue
          // Comparable unit: the same class the decide tier partitions on. A time
          // bound and a byte bound are genuinely different quantities. The ROLE is
          // deliberately not compared here (see the module header).
          if (unitClassOf(pa) !== unitClassOf(pb)) continue
          // Same-direction bounds only TIGHTEN when unified (never conflict), so they
          // are not worth demoting `verified` over.
          if (!opposedComparators(pa.comparator, pb.comparator)) continue
          const object = sharedObjectSuffix(pa.label, pb.label)
          if (object === null) continue
          hit = { pa, pb, object }
          break
        }
        if (hit !== null) break
      }
      if (hit === null) continue

      emittedPairs.add(pairKey)
      const [loId, hiId] = [ra.id, rb.id].sort() as [string, string]
      const { pa, pb, object } = hit
      // Deterministic canonical/alias order for the suggested command.
      const [labelLo, labelHi] = [pa.label, pb.label].sort() as [string, string]
      // The message names the context it actually found, because a reader checks the claim
      // against the document: an unconditional pair has no guard to be "the same" as. An
      // empty `guardKey` means no precondition AND no trigger, so "always hold" is a
      // statement the document supports.
      const context =
        ra.guardKey === ''
          ? 'in the same system with no precondition or trigger, so both bounds always hold'
          : 'under the same system and the same precondition and trigger'
      const head =
        `${loId} and ${hiId} place opposed numeric bounds (${pa.sourceText} vs ${pb.sourceText}) ` +
        `${context}, on quantities that share the object "${object}" but ` +
        `differ in their leading verb ("${pa.label}" vs "${pb.label}"), so they atomized to ` +
        'different quantity keys and were never compared. '
      // Two different marked roles stay apart on one key too, so the alias alone does not
      // make the pair provable. The command is still the right first step (it records that
      // the two phrasings are one quantity), but the message must not promise a proof.
      const roles = rolesCompatible(pa.role, pb.role)
        ? ''
        : `They also bound two roles (${pa.role} and ${pb.role}), which the numeric tier keeps on two ` +
          'variables even under one key, so after the alias it DISCLOSES the pair ' +
          '(FND_NUMERIC_UNCOMPARED) rather than proving it; restate them if the deadline is on ' +
          'the completion of what the duration measures. '
      const advice =
        'If both bounds constrain the SAME ' +
        `physical quantity, run \`symspec glossary "${labelLo}" "${labelHi}"\` so the numeric ` +
        (roles === ''
          ? 'tier keys them together and can prove any conflict, then re-run `symspec check`. '
          : 'tier keys them together, then re-run `symspec check`. ') +
        roles +
        'If they are genuinely different quantities, reword one so each names its own quantity ' +
        'in different words (the two verb phrasings are what made them look like one). This is a ' +
        'suggestion, not a verdict.'
      findings.push({
        code: 'FND_QUANTITY_ALIAS_CANDIDATE',
        severity: 'info',
        requirementIds: [loId, hiId],
        message: head + advice,
      })
    }
  }

  return findings
}

/**
 * `FND_SIMILAR_UNUNIFIED` — the over-unification-adjacent review prompt (AC-4-12).
 *
 * The formal tier's soundness claim (AC-4-11, "sound modulo atomization GIVEN
 * conservative normalization") has exactly one false-positive risk class: two
 * DIFFERENT conditions collapsing onto one atom because normalization was too
 * aggressive. AC-4-2a's mitigation is to stay conservative (no stemming, no
 * stopword-stripping beyond a leading article, a small curated antonym table).
 * That conservatism buys soundness but costs recall the other way: genuine
 * near-synonyms that AREN'T in the seed antonym table ("log the failure" vs
 * "record the failure") stay on two distinct atoms and a real conflict can hide
 * (research-smt.md §4.3 rule 2 mitigation).
 *
 * This module does not try to fix that by unifying more aggressively — that
 * would reintroduce the over-unification risk it exists to guard against.
 * Instead it REUSES the existing Rule 3 Jaccard pass (`pairwise-filter.ts`,
 * AC-3-4) as a pure REPORTER: for every pair the Jaccard rule already flags as
 * lexically similar (≥ the shared threshold, default 0.7) it checks whether the
 * two requirements' RESPONSE atoms actually resolved to the same atom name
 * under `atomize` (AC-4-2a) — same name means "unified" regardless of polarity,
 * because an antonym-table hit (e.g. grant/revoke) is a DESIGNED unification
 * (opposite polarity, same atom), not a miss. When the names differ, symspec
 * emits an info-severity `FND_SIMILAR_UNUNIFIED` finding naming both
 * requirement ids and points the calling agent at a `symspec glossary` merge
 * for genuine synonyms the seed table missed (AC-4-12).
 *
 * ## Scope boundary
 *
 * This module never manufactures a conflict — it is strictly informational
 * (`severity: 'info'`), the correct posture for a heuristic that can only ever
 * be a hint, never a proof, that two requirements might describe the same
 * underlying condition.
 */

import { emitCandidatePairs } from '../solvers/free/pairwise-filter.ts'
import type { CandidatePair, ReqView } from '../solvers/types.ts'
import { type Atom, areContrary, atomize } from './atomize.ts'

/** An info-severity similar-but-not-unified finding (Appendix B `FND_SIMILAR_UNUNIFIED`). */
export interface SimilarUnunifiedFinding {
  readonly code: 'FND_SIMILAR_UNUNIFIED'
  readonly severity: 'info'
  /** Both requirement ids, in the candidate pair's stable `[a, b]` order. */
  readonly requirementIds: [string, string]
  readonly message: string
}

/**
 * A requirement projection this module accepts: {@link ReqView} plus the
 * optional parse-time `negated` flag (AC-2-4), matching the additive shape
 * `encode.ts`'s `EncodableRequirement` uses. Response-atom identity (not
 * polarity) is what this module compares, but the flag is threaded through
 * anyway so the SAME atomization the rest of the formal tier sees is used
 * here — never a polarity-blind stand-in.
 */
export type SimilarityRequirement = ReqView & { negated?: boolean }

/** Options for {@link findSimilarUnunified}. */
export interface FindSimilarUnunifiedOptions {
  /** Jaccard threshold forwarded to the Rule 3 candidate pass. Default 0.7 (AC-3-4/AC-4-12). */
  similarityThreshold?: number
}

/** The scoped RESPONSE atom name for a requirement, per AC-4-2a. Polarity-agnostic by design. */
function responseAtomOf(req: SimilarityRequirement): Atom {
  return atomize({
    kind: 'resp',
    text: req.systemResponse,
    systemName: req.systemName,
    ...(req.negated !== undefined ? { negated: req.negated } : {}),
  })
}

const pairKey = (a: string, b: string): string => (a < b ? `${a}|${b}` : `${b}|${a}`)

/**
 * Reuse the Rule 3 Jaccard pass over `reqs` (AC-3-4) and report, at `info`
 * severity, every candidate pair whose responses are lexically similar but
 * whose atoms did NOT unify to the same name under `atomize` (AC-4-2a).
 *
 * Only Rule 3 (`near-duplicate-sentence`) candidates are considered — Rule 1
 * (same trigger, different response) and Rule 2 (overlapping precondition) are
 * about structural relationships between DIFFERENT conditions, not lexical
 * near-synonymy, so they are out of scope for this reporter.
 */
export function findSimilarUnunified(
  reqs: readonly SimilarityRequirement[],
  options: FindSimilarUnunifiedOptions = {},
): SimilarUnunifiedFinding[] {
  const filterOpts =
    options.similarityThreshold === undefined
      ? {}
      : { similarityThreshold: options.similarityThreshold }
  const pairs: CandidatePair[] = emitCandidatePairs([...reqs], filterOpts)
  const byId = new Map(reqs.map((r) => [r.id, r] as const))

  const findings: SimilarUnunifiedFinding[] = []
  const seen = new Set<string>()

  for (const pair of pairs) {
    if (pair.reason !== 'near-duplicate-sentence') continue

    const a = byId.get(pair.a)
    const b = byId.get(pair.b)
    if (a === undefined || b === undefined) continue

    const key = pairKey(pair.a, pair.b)
    if (seen.has(key)) continue
    seen.add(key)

    const litA = responseAtomOf(a)
    const litB = responseAtomOf(b)
    const atomA = litA.name
    const atomB = litB.name
    // Same atom name ⇒ unified (identical text) ⇒ no finding. A seed-antonym pair is two
    // CONTRARY atoms (AC-2-1) the solver already relates — proposing to reword one into the other
    // would tell the author to merge `grant access` with `revoke access`.
    if (atomA === atomB || areContrary(litA, litB)) continue

    findings.push({
      code: 'FND_SIMILAR_UNUNIFIED',
      severity: 'info',
      requirementIds: [pair.a, pair.b],
      message:
        `${pair.a} and ${pair.b} have lexically similar sentences (Jaccard ≥ ` +
        `${options.similarityThreshold ?? 0.7}) but their responses did not unify to the ` +
        'same atom under the conservative normalization/antonym table. If these are genuine ' +
        `synonyms (e.g. "${atomA}" vs "${atomB}"), reword one requirement's response via ` +
        '`symspec update --ref <id> systemResponse "<wording>"` so both use the same phrasing, then re-run `symspec check` to ' +
        'surface any conflict the shared atom exposes.',
    })
  }

  return findings
}

/**
 * PROJECTING A REACHABILITY RUN ONTO FINDINGS AND DEMOTIONS.
 *
 * The tier (`./reachability.ts`) answers questions about a state model. This module
 * turns those answers into the two things `check` publishes: `findings[]` entries an
 * agent branches on, and `coverage.demotions[]` entries that keep `verified` honest.
 *
 * Kept separate from the tier for a reason that is about testability rather than tidiness:
 * the tier needs a live WASM solver, and every rule in THIS file is a pure function of a
 * `ReachabilityReport`. So the wording of a demotion, the shape of a repair, and the
 * decision about what demotes can all be asserted without booting Z3 — which is what
 * makes it affordable to test them exhaustively.
 *
 * ## The demotion-only doctrine, applied
 *
 * This tier may DEMOTE `verified` and may never promote it. Concretely: a `PROVED`
 * verdict adds an info finding and NO demotion (it is the absence of a demotion that
 * lets `verified` stay true), while every other outcome — under-hypotheses, unknown,
 * not-checked — adds one. There is no path here that removes a demotion another tier
 * raised, and that asymmetry is what makes "silence is not a certificate" true of the
 * reachability tier too.
 *
 * ## Evidence names REQUIREMENTS, not internal rule names
 *
 * Every trace step and every hypothesis is rendered with the requirement's own stable
 * key where it has one (v4 V29's groundwork). A trace that read
 * `sys__lock__resp__grant` would be technically complete and practically useless; one
 * that reads `init -> TX-A1 -> TX-A1 -> TX-C1` is a sentence about the author's own
 * document.
 */

import type { Repair } from '../../ports/repair.ts'
import type { StateVariable } from '../requirements/document.ts'
import type { DocumentOp } from '../requirements/ops.ts'
import { REACHABILITY_BFS_STATE_CAP } from './explicit-state.ts'
import type { ConstraintResult, ReachabilityReport } from './reachability.ts'
import type { ReachabilityFndCode } from './reachability-codes.ts'

/**
 * One finding this module produces.
 *
 * Structurally v4's `CheckFinding` minus the `tier` field, which the caller
 * stamps: `check` owns the `CheckTier` union and this module must not widen it. The
 * `evidence` is deliberately a plain open record rather than v4's `Evidence`
 * type — v4's shape is an atom table plus an unsat core, and a reachability
 * invariant or trace is neither, so reusing it would mean either lying about the field's
 * meaning or editing a transplanted file.
 */
export interface ReachabilityFinding {
  readonly code: ReachabilityFndCode
  readonly severity: 'error' | 'warn' | 'info'
  readonly requirementIds: readonly string[]
  readonly message: string
  /** The reachability evidence: an invariant, a trace, or the hypotheses relied upon. */
  readonly evidence?: Readonly<Record<string, unknown>>
  /** The runnable remedy, where one exists. */
  readonly repair?: Repair
}

/** One demotion this module produces — v4's `CoverageDemotion` shape plus the
 * v5 `repair`, so `check` can splice these into `coverage.demotions[]` directly. */
export interface ReachabilityDemotion {
  readonly reason: string
  readonly requirementIds: readonly string[]
  readonly action: string
  readonly repair?: Repair
}

/** The whole projection. */
export interface ReachabilityProjection {
  readonly findings: readonly ReachabilityFinding[]
  readonly demotions: readonly ReachabilityDemotion[]
}

/**
 * The demotion reasons this tier adds, as a closed list.
 *
 * Enumerated so `check`'s repair mapping can be exhaustive over them by test, the same
 * discipline `FOLD_ERROR_CODES` uses for the mutation fold. Prefixed `reachability-` so
 * they cannot collide with the pipeline's own `CoverageDemotion['reason']` members,
 * which is a real risk: that union is a string literal type and a duplicate reason
 * would silently merge two different remedies under one name.
 */
export const REACHABILITY_DEMOTION_REASONS = [
  'reachability-not-checked',
  'reachability-frame-relied-upon',
  'reachability-budget-exhausted',
  'reachability-undecidable',
  // APPENDED at the HARDENING wave. Its own reason rather than reusing
  // `reachability-undecidable`, because the remedies are opposite: undecidable says "bound
  // the model", vacuous-initial says "the model admits NO states, fix the initial
  // predicate". Collapsing them would send an agent to add bounds to a document whose
  // bounds are already the problem.
  'reachability-vacuous-initial-state',
  // APPENDED for spec 007 AC-1-5: the explicit-state search refuted a proof, so the proof
  // was withdrawn. Its own reason because the remedy is neither a budget nor a bound — it
  // is a tool defect to report.
  'reachability-certificate-disagrees',
  // APPENDED for spec 007 AC-1-6: the proof needs a frame the document does not declare.
  // Its own reason because its discharge is a frame DECLARATION (or requirements), where
  // `reachability-frame-relied-upon`'s is the opposite — releasing one.
  'reachability-frame-undeclared',
  // APPENDED for spec 007 AC-1-5: the solver proved the constraint, but the explicit-state
  // search stopped without either finishing or showing the model is beyond its cap, so the
  // proof was withheld. Its own reason because the remedy is to make the model enumerable,
  // not to raise the solver's budget or to read a refutation.
  'reachability-cross-check-incomplete',
] as const

export type ReachabilityDemotionReason = (typeof REACHABILITY_DEMOTION_REASONS)[number]

/** The hypothesis list as prose: each variable with the requirements that write it. */
const reliedOn = (hypotheses: NonNullable<ConstraintResult['hypotheses']>): string =>
  hypotheses
    .map(
      (h) =>
        `${h.variable} (written by ${h.writers.length > 0 ? h.writers.join(', ') : 'NO requirement'})`,
    )
    .join('; ')

/**
 * The `state` op that re-declares `variable` EXACTLY as declared, with only `frame` changed.
 *
 * `state` is a full redeclaration (see `StateOp`), so this carries the variable's own type,
 * enum domain or int bounds, and initial. The first implementation emitted `type: 'bool'`
 * for every variable, which for an int is a type change the fold refuses — the repair a
 * check handed out could not be applied (spec 007 AC-1-6).
 */
const redeclare = (variable: StateVariable, frame: 'stable' | 'volatile'): DocumentOp => {
  const initial = variable.initial !== undefined ? { initial: variable.initial } : {}
  if (variable.type === 'bool')
    return { op: 'state', name: variable.name, type: 'bool', frame, ...initial }
  if (variable.type === 'enum') {
    return {
      op: 'state',
      name: variable.name,
      type: 'enum',
      domain: [...variable.domain],
      frame,
      ...initial,
    }
  }
  return {
    op: 'state',
    name: variable.name,
    type: 'int',
    ...(variable.domain?.min !== undefined ? { min: variable.domain.min } : {}),
    ...(variable.domain?.max !== undefined ? { max: variable.domain.max } : {}),
    frame,
    ...initial,
  }
}

/** Render one state as `a = 1, b = true`, in declaration order. */
const renderState = (state: Readonly<Record<string, string>>): string =>
  Object.entries(state)
    .map(([name, value]) => `${name} = ${value}`)
    .join(', ')

/** Render a trace as an arrow-joined path, which is how a human reads a counterexample. */
const renderTrace = (result: ConstraintResult): string => {
  const steps = result.trace?.steps ?? []
  if (steps.length === 0) return '(the solver did not return a readable trace)'
  return steps.map((s) => s.rule).join(' -> ')
}

/**
 * The command that supplies what a not-checked run is missing.
 *
 * Built from the report rather than hardcoded, because the missing thing differs: a
 * document with no variables needs `state`, a document with variables but no constraints
 * needs `classify`. Naming the wrong one would send an agent to the wrong command with
 * full confidence — the failure mode v4's `<blocking-code>` placeholder had.
 */
const notCheckedRepair = (report: ReachabilityReport, docPath: string): Repair => {
  if (report.variables === 0) {
    return {
      ops: [{ op: 'state', name: '<variable>', type: 'bool' } satisfies DocumentOp],
      commands: [
        `symspec state <variable> --type bool --file ${docPath}`,
        `symspec check ${docPath}`,
      ],
    }
  }
  return {
    ops: [
      {
        op: 'classify',
        ref: '<requirement>',
        kind: 'constraint',
        expression: '<predicate over declared variables>',
      } satisfies DocumentOp,
    ],
    commands: [
      `symspec list ${docPath}`,
      `symspec classify <requirement> --kind constraint --expression "<predicate>" --file ${docPath}`,
      `symspec check ${docPath}`,
    ],
  }
}

/**
 * Why the tier did not fully cover this document, as prose — or `undefined` when it did.
 *
 * ONE function with an ordered set of causes rather than a finding per cause, because
 * they are not independent: a document with no state model also has no constraints and
 * no transitions, and emitting three disclosures for one omission is noise that trains a
 * reader to skip them. The FIRST applicable cause is the actionable one.
 */
const notCheckedReason = (report: ReachabilityReport): string | undefined => {
  if (report.variables === 0) {
    return (
      'no state model is committed, so no unbounded reachability question was asked. `check` ' +
      'cannot tell whether a requirement can be violated over all reachable states until the ' +
      'state variables are declared and the responses that touch them are classified'
    )
  }
  if (report.results.length === 0) {
    return (
      `${report.variables} state variable(s) are declared but NO requirement carries a ` +
      'constraint, so there is no property to prove. The state model describes a state space ' +
      'nothing asserts anything about'
    )
  }
  if (report.emptyTransitionRelation) {
    return (
      'the state model admits NO transitions — no requirement is classified as an `effect` — so ' +
      'the only reachable state is the initial one. An invariant that holds there holds almost ' +
      'vacuously, and is not evidence about a running system'
    )
  }
  if (report.skipped.length > 0) {
    return `${report.skipped.length} classified requirement(s) could not be read: ${report.skipped
      .map((s) => `${s.label} — ${s.reason}`)
      .join('; ')}`
  }
  return undefined
}

/**
 * Project a finished run onto findings and demotions.
 *
 * `docPath` is threaded in only so every command is copy-pasteable as-is — the same
 * reason `RepairContext` carries it. Nothing here reads the filesystem.
 */
export const projectReachability = (
  report: ReachabilityReport,
  docPath: string,
): ReachabilityProjection => {
  const findings: ReachabilityFinding[] = []
  const demotions: ReachabilityDemotion[] = []

  // --- SANITY GATE #1, PROJECTED --------------------------------------------
  //
  // FIRST, and it REPLACES the per-constraint projection rather than joining it. On a
  // vacuous model the tier issued no query and every result is `UNKNOWN`, so running the
  // normal loop would emit N info-severity "the solver did not decide" findings whose
  // stated remedies (raise the budget / bound the domains) are both WRONG — the solver was
  // never asked, and the model admits no states. One error-severity finding naming the
  // actual contradiction, plus one demotion per constraint, is the honest projection.
  if (report.vacuousInitialState) {
    const ids = report.results.map((r) => r.requirementId)
    const quoted =
      report.initialPredicates.length > 0
        ? report.initialPredicates.join('; ')
        : '(the declared variable ranges alone are contradictory)'
    findings.push({
      code: 'FND_REACHABILITY_VACUOUS_INITIAL',
      // ERROR, and the one non-`VIOLATED` error in the family. It earns that because it
      // does not merely fail to prove — it MASKS proven violations: measured, adding a
      // contradictory initial predicate to a document with a real reachable violation
      // turned the error-severity finding into "PROVED with nothing assumed" and flipped
      // the exit code from 1 to 0. Reporting that at info severity would leave the exit
      // code lying in exactly the case that matters most.
      severity: 'error',
      requirementIds: ids,
      message:
        'The INITIAL STATE of this state model is UNSATISFIABLE, so the model has no initial ' +
        'state at all, NO state is reachable, and every constraint holds VACUOUSLY. Nothing is ' +
        `proven about anything. The predicates that cannot all hold at once: ${quoted}` +
        (report.initialPredicates.length > 0
          ? ' — conjoined with the declared variable ranges.'
          : '') +
        ' This is reported at ERROR severity rather than as a disclosure because a vacuous ' +
        'model MASKS proven defects: with a satisfiable initial predicate this same document ' +
        'may carry reachable violations, and the vacuous run reports them as proofs. Note the ' +
        'independent certificate check cannot catch this — an unsatisfiable initial state makes ' +
        'the inferred invariant `false`, which discharges all three obligations validly.',
      evidence: {
        vacuousInitialState: true,
        initialPredicates: [...report.initialPredicates],
        constraintsAffected: report.results.length,
      },
      repair: {
        // NO ops. Which predicate to change, and to what, is a statement about the
        // system's intended starting state — content this must not invent. The reads that
        // show the author the contradiction are offered instead, together with the two
        // commands that edit either half.
        ops: [],
        commands: [
          `symspec list ${docPath}`,
          `symspec state-initial "<satisfiable predicate>" ${docPath}`,
          `symspec state-initial --clear ${docPath}`,
        ],
      },
    })
    // ONE DEMOTION PER CONSTRAINT, not one for the run. `verified` is false either way,
    // but a demotion carries `requirementIds`, and an agent reading the work list needs to
    // see that EVERY constraint is affected rather than inferring it from a run-scoped
    // note. On a model with no constraints at all this yields none, which is right: the
    // coverage disclosure below then carries the run-scoped statement.
    for (const result of report.results) {
      demotions.push({
        reason: 'reachability-vacuous-initial-state' satisfies ReachabilityDemotionReason,
        requirementIds: [result.requirementId],
        action:
          `${result.label} was NOT checked: the model's initial state is unsatisfiable ` +
          `(${quoted}), so no state is reachable and any answer would be vacuous. Fix the ` +
          'contradiction, then re-run — the constraint may well be violable once the model ' +
          'admits states. Raising a budget or bounding the domains will NOT help; the bounds ' +
          'may themselves be the contradiction.',
        repair: {
          ops: [],
          commands: [`symspec list ${docPath}`, `symspec check ${docPath}`],
        },
      })
    }
  }

  for (const result of report.vacuousInitialState ? [] : report.results) {
    const ids = [result.requirementId]
    // A PROOF THE EXPLICIT SEARCH REFUTED (AC-1-5). Checked BEFORE the verdict switch: the
    // tier has already withdrawn the proof (verdict UNKNOWN), and reporting that as an
    // ordinary "the solver did not decide" would hide that a checker is wrong.
    if (result.crossCheck?.status === 'disagrees') {
      const witness = result.crossCheck
      findings.push({
        code: 'FND_CERTIFICATE_DISAGREES',
        severity: 'error',
        requirementIds: ids,
        message:
          `${result.label}: the unbounded solver PROVED this constraint, but an independent ` +
          'explicit-state search of the same model reaches a state that VIOLATES it' +
          (witness.trace.length > 0
            ? `, by firing: ${witness.trace.join(' -> ')}`
            : ' — the initial state itself') +
          '. The proof is WITHDRAWN. The two checkers share nothing beyond the parsed ' +
          'expression, so one of them is wrong about this model; this is a tool defect, not a ' +
          'document defect.',
        evidence: {
          frame: witness.frame,
          trace: [...witness.trace],
          path: [...witness.path],
          strictRun: result.strict,
        },
        repair: {
          ops: [],
          commands: [`symspec show ${result.label} ${docPath}`, `symspec list ${docPath}`],
        },
      })
      demotions.push({
        reason: 'reachability-certificate-disagrees' satisfies ReachabilityDemotionReason,
        requirementIds: ids,
        action:
          `The proof for ${result.label} was refuted by the explicit-state cross-check and ` +
          'withdrawn. Nothing about this constraint is claimed. Read the witness path against ' +
          'the state model; report the document if the solver was the one that was wrong.',
        repair: { ops: [], commands: [`symspec check ${docPath}`] },
      })
      continue
    }
    // A PROOF THE EXPLICIT SEARCH COULD NOT EXAMINE (AC-1-5). It stopped without showing the
    // model is beyond its cap, so the model may be one the cross-check must cover. The
    // tier has withheld the proof (verdict UNKNOWN), and this says why.
    if (result.crossCheck?.status === 'not-applicable' && !result.crossCheck.beyondCap) {
      const why = result.crossCheck.reason
      findings.push({
        code: 'FND_REACHABILITY_UNKNOWN',
        severity: 'info',
        requirementIds: ids,
        message:
          `${result.label}: the unbounded solver proved this constraint, but the independent ` +
          `explicit-state search that must re-decide every proof over a model of at most ` +
          `${REACHABILITY_BFS_STATE_CAP} reachable states stopped (${why}) without showing that ` +
          'this model is larger. The proof is WITHHELD, and nothing is claimed either way.',
        evidence: {
          unknownReason: 'cross-check-incomplete',
          crossCheckReason: why,
          strictRun: result.strict,
        },
      })
      demotions.push({
        reason: 'reachability-cross-check-incomplete' satisfies ReachabilityDemotionReason,
        requirementIds: ids,
        action:
          `The proof for ${result.label} was not re-decided by the explicit-state cross-check ` +
          `(${why}), so it is not reported. Make the model enumerable: state each variable's ` +
          'initial value as `name = <value or expression>` rather than through a combined ' +
          'predicate, or narrow the declared ranges. Raising the solver budget will NOT help.',
        repair: {
          ops: [],
          commands: [`symspec list ${docPath}`, `symspec check ${docPath}`],
        },
      })
      continue
    }
    switch (result.verdict) {
      case 'VIOLATED': {
        findings.push({
          code: 'FND_REACHABILITY_VIOLATED',
          // THE one error-severity outcome, and it earned that: reachable in BOTH
          // configurations, so it is not an artifact of assuming nothing.
          severity: 'error',
          requirementIds: ids,
          message:
            `${result.label}: a reachable state VIOLATES this constraint. The solver reached it ` +
            `by firing: ${renderTrace(result)}. Proven over all reachable states with no bound. ` +
            'Every step of that trace is a change some requirement makes — the run that produced ' +
            'it pins every variable no effect writes — so this is a genuine defect in the ' +
            'described system rather than an artifact of assuming nothing.',
          evidence: {
            trace: (result.trace?.steps ?? []).map((s) => s.rule),
            // The state sequence the trace walks (AC-1-3), so a reader can CHECK each step
            // against its guard and effect rather than trust the rule names.
            states: result.trace?.states ?? [],
            strictRun: result.strict,
            ...(result.framed !== undefined ? { framedRun: result.framed } : {}),
          },
          // NO ops. The fix is a judgment about what the document should SAY — weaken the
          // constraint or change the effect that reaches the bad state — and synthesizing
          // either would be inventing requirements content. The reads that inform the
          // judgment are offered instead.
          repair: {
            ops: [],
            commands: [`symspec show ${result.label} ${docPath}`, `symspec list ${docPath}`],
          },
        })
        break
      }

      case 'PROVED': {
        const verified = result.invariant?.certificateVerified === true
        if (!verified) {
          // THE ANSWER DID NOT RE-VERIFY. Reported as UNKNOWN, not as a weaker proof:
          // an answer this tool could not independently check is an answer it has no
          // basis to state. See `reachability-codes.ts` for why there is no
          // "proved-but-unchecked" code.
          findings.push({
            code: 'FND_REACHABILITY_UNKNOWN',
            severity: 'info',
            requirementIds: ids,
            message:
              `${result.label}: the solver reported this constraint unreachable, but the answer ` +
              'did NOT independently re-verify ' +
              `(${result.invariant?.failedObligation ?? 'the certificate check did not complete'}). ` +
              'No proof is claimed. This is a tool-level failure rather than a document defect — ' +
              'the contract is never to report proven unless the proof re-checks.',
            evidence: {
              failedObligation: result.invariant?.failedObligation ?? 'unknown',
              certificateVerified: false,
            },
          })
          demotions.push({
            reason: 'reachability-undecidable' satisfies ReachabilityDemotionReason,
            requirementIds: ids,
            action:
              `The reachability answer for ${result.label} did not re-verify, so it is not treated ` +
              'as a proof. Re-run to confirm it reproduces; if it does, the encoding or the ' +
              'solver is at fault and the model should be simplified until the certificate checks.',
            repair: { ops: [], commands: [`symspec check ${docPath}`] },
          })
          break
        }
        findings.push({
          code: 'FND_REACHABILITY_PROVED',
          severity: 'info',
          requirementIds: ids,
          message:
            `${result.label}: PROVED — no reachable state violates this constraint, over all ` +
            'reachable states with no bound and with nothing assumed beyond what the document ' +
            'states (frame-closed). The inferred invariant re-verified against three independent ' +
            'plain-SMT obligations.',
          evidence: {
            invariant: result.invariant?.invariant ?? '',
            certificateVerified: true,
            frameClosed: true,
          },
        })
        // NO DEMOTION. The absence is the mechanism by which `verified` may stay true.
        break
      }

      case 'PROVED_UNDER_HYPOTHESES': {
        const hypotheses = result.hypotheses ?? []
        // The required wording shape from the AC-2-5 decision doc: state the proof, then
        // state what it does NOT entail, in the same breath (Kind2's rhetorical move,
        // shipped by SPARK/GNATprove in its assumptions report). Never "P is
        // unreachable" — the claim is about the requirement-sanctioned transition
        // relation, and the sentence has to carry that.
        const relied = reliedOn(hypotheses)
        findings.push({
          code: 'FND_REACHABILITY_UNDER_HYPOTHESES',
          severity: 'info',
          requirementIds: ids,
          message:
            `${result.label}: PROVED_UNDER_HYPOTHESES — no reachable state violates this ` +
            'constraint, ASSUMING these variables, which the document declares `frame: stable`, ' +
            `change only when a requirement changes them: ${relied}. That is a HYPOTHESIS: no ` +
            'requirement establishes it, and with the frame released the constraint IS violable, ' +
            'so this is a proof about the declared model and not about the system as specified ' +
            '— `verified` is demoted accordingly. A variable written by NO requirement is the ' +
            'sharpest case: nothing in the document keeps it from changing.',
          evidence: {
            invariant: result.invariant?.invariant ?? '',
            certificateVerified: result.invariant?.certificateVerified === true,
            hypotheses: hypotheses.map((h) => ({ variable: h.variable, writers: h.writers })),
            strictRun: result.strict,
            declaredRun: result.declared ?? 'unreachable',
          },
        })
        demotions.push({
          reason: 'reachability-frame-relied-upon' satisfies ReachabilityDemotionReason,
          requirementIds: ids,
          action:
            `The proof for ${result.label} depends on the declared frame: ${relied}. Discharge it ` +
            'either by adding the requirements that make those variables genuinely written only ' +
            'where intended, or by releasing the frame (the ops below re-declare each variable ' +
            '`volatile` with its own type, range, and initial) and accepting the weaker, honest ' +
            'verdict: the proof then needs a hypothesis the document does not state.',
          repair: {
            // A concrete, applicable op per hypothesis: RELEASE the frame, re-declaring the
            // variable EXACTLY as declared otherwise — `state` is a full redeclaration, so an
            // op that dropped the type, range, or initial would change the model (or be
            // refused) rather than release a frame (spec 007 AC-1-6).
            ops: hypotheses.map((h) => redeclare(h.declaration, 'volatile')),
            commands: [`symspec show ${result.label} ${docPath}`, `symspec check ${docPath}`],
          },
        })
        break
      }

      case 'UNKNOWN': {
        if (result.unknownReason === 'frame-undeclared') {
          const hypotheses = result.hypotheses ?? []
          const needed = reliedOn(hypotheses)
          findings.push({
            code: 'FND_REACHABILITY_UNKNOWN',
            severity: 'info',
            requirementIds: ids,
            message:
              `${result.label}: NOT PROVED, and not violated by any requirement — it holds only ` +
              `if these variables keep their value whenever no requirement writes them: ${needed}. ` +
              'THE DOCUMENT DOES NOT STATE THAT: they are declared `volatile` (the default), and ' +
              'with them free the constraint IS violable through a change no requirement makes. ' +
              'Nothing is claimed either way. State the hypothesis by declaring them ' +
              '`frame: stable` (the verdict becomes PROVED_UNDER_HYPOTHESES, still demoted), or ' +
              'author the requirements that make it true.',
            evidence: {
              unknownReason: 'frame-undeclared',
              hypotheses: hypotheses.map((h) => ({ variable: h.variable, writers: h.writers })),
              strictRun: result.strict,
              ...(result.declared !== undefined ? { declaredRun: result.declared } : {}),
              framedRun: result.framed ?? 'unreachable',
            },
          })
          demotions.push({
            reason: 'reachability-frame-undeclared' satisfies ReachabilityDemotionReason,
            requirementIds: ids,
            action:
              `${result.label} holds only under a frame the document does not declare: ${needed}. ` +
              'Either author the requirements that keep those variables fixed, or state the ' +
              'hypothesis — the ops below re-declare each variable `frame: stable` with its own ' +
              'type, range, and initial — and accept PROVED_UNDER_HYPOTHESES, which still demotes.',
            repair: {
              ops: hypotheses.map((h) => redeclare(h.declaration, 'stable')),
              commands: [`symspec show ${result.label} ${docPath}`, `symspec check ${docPath}`],
            },
          })
          break
        }
        const budget = result.unknownReason === 'budget-exhausted'
        findings.push({
          code: 'FND_REACHABILITY_UNKNOWN',
          severity: 'info',
          requirementIds: ids,
          message:
            `${result.label}: the solver did not decide whether this constraint can be violated ` +
            `(${
              budget
                ? `the ${report.timeoutMs}ms budget was exhausted after ${result.elapsedMs}ms`
                : `it gave up after ${result.elapsedMs}ms, well inside the ${report.timeoutMs}ms budget`
            }). Nothing is claimed either way. ` +
            (budget
              ? 'Raising the budget may resolve it.'
              : 'Raising the budget will NOT help — the model needs bounding instead.'),
          evidence: {
            // The DERIVED reason, never the solver's own string: a timed-out Spacer query
            // reports `reason_unknown === "ok"`, which would read as success.
            unknownReason: result.unknownReason ?? 'undecidable',
            elapsedMs: result.elapsedMs,
            timeoutMs: report.timeoutMs,
          },
        })
        demotions.push({
          reason: (budget
            ? 'reachability-budget-exhausted'
            : 'reachability-undecidable') satisfies ReachabilityDemotionReason,
          requirementIds: ids,
          action: budget
            ? `The reachability query for ${result.label} hit the ${report.timeoutMs}ms per-query ` +
              `budget. Raise it: \`symspec check ${docPath} --reachability-timeout-ms ${report.timeoutMs * 4}\`. ` +
              'That flag bounds THIS tier only, so the seven per-pair solvers keep their own ' +
              '`--timeout-ms`.'
            : `The reachability query for ${result.label} was undecidable within its budget, and ` +
              'more time will not help. Bound the integer domains in the state model ' +
              '(`symspec state <name> --type int --min <n> --max <n>`) so the state space is finite.',
          repair: budget
            ? {
                ops: [],
                // NAMES THE TIER'S OWN FLAG, not the shared `--timeout-ms` (G5). A
                // reachability query is one whole-model fixedpoint search; raising the shared
                // knob 4x to decide it would also hand every propositional solver 4x the rope,
                // which is a different and unasked-for change to the run.
                //
                // The doubling-and-then-some the budget-hint module uses: a bound that
                // failed at N rarely succeeds at N+ε, and each retry pays the full
                // truncated cost.
                commands: [
                  `symspec check ${docPath} --reachability-timeout-ms ${report.timeoutMs * 4}`,
                ],
              }
            : {
                ops: [],
                commands: [`symspec show ${result.label} ${docPath}`],
              },
        })
        break
      }
    }
  }

  // --- THE DECLARED-RANGE OBLIGATIONS (spec 007 AC-1-2) --------------------------
  for (const check of report.rangeChecks) {
    const bounds = [
      check.range.min !== undefined ? `min ${check.range.min}` : undefined,
      check.range.max !== undefined ? `max ${check.range.max}` : undefined,
    ]
      .filter((b) => b !== undefined)
      .join(', ')
    if (check.verdict === 'reachable') {
      const states = check.trace?.states ?? []
      const preState = states.length >= 2 ? states[states.length - 2] : undefined
      const value = states.length >= 1 ? states[states.length - 1]?.[check.variable] : undefined
      const steps = (check.trace?.steps ?? []).map((s) => s.rule)
      findings.push({
        code: 'FND_RANGE_VIOLATION',
        // ERROR: the declared range is false of the system as specified, and every step of
        // the witness is a change some requirement makes (full frame).
        severity: 'error',
        requirementIds: [check.requirementId],
        message:
          `${check.label}: writes ${check.variable} OUTSIDE its declared range (${bounds}) from a ` +
          'reachable state' +
          (preState !== undefined && value !== undefined
            ? ` — from ${renderState(preState)} it sets ${check.variable} := ${value}`
            : '') +
          `. Reached by firing: ${steps.length > 0 ? steps.join(' -> ') : '(the trace was not recovered)'}. ` +
          'The step is not disabled by the range: it is a transition the document describes, and ' +
          'any constraint it breaks is reported against it.',
        evidence: {
          variable: check.variable,
          range: { ...check.range },
          ...(value !== undefined ? { value } : {}),
          ...(preState !== undefined ? { preState } : {}),
          trace: steps,
          states,
        },
        // NO ops: guarding the effect, clamping the value, or widening the range are three
        // different statements about the system, and choosing one is the author's call.
        repair: {
          ops: [],
          commands: [`symspec show ${check.label} ${docPath}`, `symspec list ${docPath}`],
        },
      })
    } else if (check.verdict === 'unknown') {
      const budget = check.unknownReason === 'budget-exhausted'
      findings.push({
        code: 'FND_REACHABILITY_UNKNOWN',
        severity: 'info',
        requirementIds: [check.requirementId],
        message:
          `${check.label}: the solver did not decide whether this effect can write ` +
          `${check.variable} outside its declared range (${bounds}). Nothing is claimed either way.`,
        evidence: {
          variable: check.variable,
          unknownReason: check.unknownReason ?? 'undecidable',
          elapsedMs: check.elapsedMs,
          timeoutMs: report.timeoutMs,
        },
      })
      demotions.push({
        reason: (budget
          ? 'reachability-budget-exhausted'
          : 'reachability-undecidable') satisfies ReachabilityDemotionReason,
        requirementIds: [check.requirementId],
        action: budget
          ? `Whether ${check.label} keeps ${check.variable} in range was not decided within the ${report.timeoutMs}ms budget. Raise it: \`symspec check ${docPath} --reachability-timeout-ms ${report.timeoutMs * 4}\`.`
          : `Whether ${check.label} keeps ${check.variable} in range was undecidable within its budget; more time will not help. Bound the integer domains in the state model.`,
        repair: budget
          ? {
              ops: [],
              commands: [
                `symspec check ${docPath} --reachability-timeout-ms ${report.timeoutMs * 4}`,
              ],
            }
          : { ops: [], commands: [`symspec show ${check.label} ${docPath}`] },
      })
    }
  }

  // --- THE COVERAGE DISCLOSURE ------------------------------------------------
  // Emitted LAST so it reads as a statement about the run as a whole rather than about
  // any one requirement, and emitted at all because a question never asked looks exactly
  // like a question answered cleanly.
  const gap = notCheckedReason(report)
  if (gap !== undefined) {
    const ids = report.results.map((r) => r.requirementId)
    findings.push({
      code: 'FND_REACHABILITY_NOT_CHECKED',
      severity: 'info',
      requirementIds: ids,
      message:
        `The unbounded reachability tier did not fully cover this document: ${gap}. ` +
        'This is a COVERAGE DISCLOSURE, not a defect — but `verified` cannot account for a ' +
        'question that was never asked.',
      evidence: {
        variables: report.variables,
        effects: report.effects,
        constraintsChecked: report.results.length,
        skipped: report.skipped.map((s) => ({ label: s.label, reason: s.reason })),
        emptyTransitionRelation: report.emptyTransitionRelation,
      },
      repair: notCheckedRepair(report, docPath),
    })
    demotions.push({
      reason: 'reachability-not-checked' satisfies ReachabilityDemotionReason,
      requirementIds: ids,
      action: `Reachability was not fully checked: ${gap}. ${
        report.variables === 0
          ? `Declare the state variables (\`symspec state <name> --type bool|int|enum --file ${docPath}\`), then classify the responses that touch them (\`symspec classify <ref> --kind constraint --expression "<predicate>" --file ${docPath}\`).`
          : `Classify the responses that touch the declared variables: \`symspec classify <ref> --kind constraint --expression "<predicate>" --file ${docPath}\`.`
      }`,
      repair: notCheckedRepair(report, docPath),
    })
  }

  // --- THE FRAME-DRIFT DISCLOSURE -------------------------------------------
  // A variable declared `stable` and written by NO requirement is the exact V16 shape.
  // Prove-twice already prevents the false PROVED, so this is a DISCLOSURE rather than an
  // error (Quint would hard-error; a variable nothing writes is legitimately a monitored
  // input, and refusing it would reject a valid model). It rides on the not-checked code
  // rather than getting its own, because the remedy is the same shape: correct the
  // declaration.
  if (report.frameDrift.length > 0) {
    findings.push({
      code: 'FND_REACHABILITY_NOT_CHECKED',
      severity: 'info',
      requirementIds: [],
      message:
        `${report.frameDrift.length} variable(s) are declared \`frame: stable\` but are written by ` +
        `NO requirement: ${report.frameDrift.join(', ')}. Under the framed run they are pinned to ` +
        'their initial value forever, so any property about them holds only because of that ' +
        'declaration — which is the shape that turns a reachable state into an apparent proof. ' +
        'Prove-twice already prevents that from being reported as PROVED; this names the ' +
        'declaration so it can be corrected.',
      evidence: { frameDrift: [...report.frameDrift] },
      repair: {
        ops: report.frameDrift.map(
          (name) => ({ op: 'state', name, type: 'bool', frame: 'volatile' }) satisfies DocumentOp,
        ),
        commands: [`symspec check ${docPath}`],
      },
    })
  }

  return { findings, demotions }
}

/**
 * THE MUTATION FOLD — the only code that turns a {@link DocumentOp} into a changed
 * document.
 *
 * ## One fold, not one-per-command
 *
 * v4 had two mutation paths and the split cost it real behavior. `applyChange`
 * (singular) applied one change; `applyChanges` (plural) was a left-fold with NO
 * try/catch, so the FIRST throw aborted a whole batch with no per-op result and no
 * continue-on-error. Its own lesson
 * (`batch-apply-atomic-fold-per-op-results.md`) concluded that a batch caller must
 * fold the singular form itself — which v4's `apply.ts` then did, in a third
 * place, with its own ref-resolution and its own error mapping.
 *
 * Here there is one {@link applyOp} and one {@link foldOps}, and every surface is a
 * caller: the single-op operations (`add`, `update`, `delete`, the edge ops, the
 * side-table ops) each fold a ONE-ELEMENT stream, and `apply` folds an N-element
 * one. So a behavior is impossible to have in one surface and not the other — the
 * `--dry-run` preview, the key-minted-earlier-in-the-batch resolution, the
 * pattern-aware clear guard, and the atomic-abort semantics are all properties of
 * the fold, not of a command.
 *
 * ## THE THREE INVARIANTS
 *
 * 1. **Resolution is against the RUNNING document, never the original.** This is
 *    v4 lesson that removed the label→UUID sidecar file: an `add` op minting
 *    key `G1` at index 0 must be reference-able by `{"op":"derive","from":"G1"}` at
 *    index 5. Folding against the original would resolve `G1` to nothing.
 * 2. **The document is never mutated in place.** Each step returns a NEW document
 *    (structural copy of the touched parts only). A caller holding the pre-fold
 *    document still has it, which is what makes an atomic abort a no-op rather than
 *    a rollback.
 * 3. **Failure is a VALUE, not a throw.** {@link applyOp} returns
 *    `Ok | OpFailure`. v4 threw `ChangeError` and every caller had a
 *    try/catch that re-derived the code from `'code' in e`; a returned union makes
 *    the failure set visible in the type and exhaustive at the call site.
 *
 * ## The clock is INJECTED
 *
 * `createdAt`/`updatedAt` come from a `timestamp` argument, never `new Date()`.
 * That is not testing hygiene — it is what makes a fold REPRODUCIBLE: replaying the
 * same op stream with the same timestamp produces a byte-identical document, which
 * is the property the whole determinism claim rests on and the reason `import`
 * already worked this way.
 */

import { requirementsContentHash } from './content-hash.ts'
import {
  type AntonymPair,
  type GlossaryEntry,
  NULLABLE_ATTRS,
  type Relation,
  type Requirement,
  type RequirementsDocument,
  STATE_VAR_NAME_PATTERN,
  type StateModel,
  type StateVariable,
  type TermEntry,
  type UpdatableAttr,
  type Waiver,
} from './document.ts'
import { type DocumentOp, EDGE_OP_RELATION } from './ops.ts'
import { renderSentence } from './render.ts'
import { resolveId, resolveRef } from './resolve.ts'
import {
  cheapInitialContradiction,
  isExprError,
  referencedNames,
  validateEffect,
  validateExpression,
} from './state-expr.ts'

// ---------------------------------------------------------------------------
// The result shapes
// ---------------------------------------------------------------------------

/**
 * One op's failure: a stable ERR_* code plus the message.
 *
 * The code is a plain string rather than the `ErrCode` union because the fold lives
 * in `core/` and the catalog lives in `kernel/` — and the dependency runs the other
 * way (the kernel knows nothing about documents). The mapping from these codes to
 * catalog classes happens at the operation boundary, where it can be exhaustive;
 * {@link FOLD_ERROR_CODES} enumerates the closed set so that mapping cannot miss
 * one.
 */
export interface OpFailure {
  readonly code: string
  readonly error: string
  /** Actionable next steps, so a per-op failure inside a batch is as useful as a
   * top-level error envelope. */
  readonly suggestions: readonly string[]
}

/**
 * The closed set of codes {@link applyOp} can produce. Enumerated so the operation
 * boundary's code→class mapping is exhaustive by test rather than by inspection.
 */
export const FOLD_ERROR_CODES = [
  'ERR_USAGE',
  'ERR_NOT_FOUND',
  'ERR_DUPLICATE_ID',
  'ERR_DUPLICATE_KEY',
  'ERR_NULL_REQUIRED',
  'ERR_WAIVER_REFUSED',
] as const

/** One op's success: the new document plus what the op touched. */
export interface OpSuccess {
  readonly document: RequirementsDocument
  /** The requirement UUID the op created or targeted, when it had one. Absent for
   * the side-table ops, which touch no requirement. */
  readonly id?: string
  /** True when the op was a no-op (an idempotent re-apply). Reported rather than
   * hidden so a repair round-trip can tell "already done" from "just done". */
  readonly noop: boolean
}

/**
 * Narrow ANY `T | OpFailure` to its failure branch.
 *
 * Generic in `T` because the fold's internal helpers return their own success
 * shapes alongside the shared failure — {@link requireTarget} yields a
 * `Requirement`, {@link applyOp} yields an {@link OpSuccess} — and one guard for all
 * of them keeps the failure branch a single spelling.
 *
 * `'code' in result` is the discriminant, and it is safe for a reason worth stating
 * rather than assuming: no success shape reachable here carries a `code` field.
 * `Requirement` has none, `OpSuccess` has none. `mutate.test.ts` pins that, so a
 * future field named `code` on either shape is a test failure rather than a silent
 * reclassification of every success as an error.
 */
export const isOpFailure = <T extends object>(result: T | OpFailure): result is OpFailure =>
  'code' in result

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

const fail = (code: string, error: string, suggestions: readonly string[]): OpFailure => ({
  code,
  error,
  suggestions,
})

/**
 * `ERR_USAGE` shorthand, for the many state-model failures that are all one code.
 *
 * Every G4 authoring refusal is a USAGE error — the op as given cannot be applied —
 * and none of them is a distinct catalog code. Spelling `fail('ERR_USAGE', …)` at
 * seventeen sites invites a typo'd code string that `toCatalogError` would then
 * silently default to `ERR_USAGE` anyway, so the code is named once here instead. The
 * codes that ARE distinct (`ERR_NOT_FOUND`, `ERR_DUPLICATE_KEY`, …) still go through
 * {@link fail} explicitly, so the choice of a non-usage code stays visible at its
 * call site.
 */
const usage = (error: string, suggestions: readonly string[]): OpFailure =>
  fail('ERR_USAGE', error, suggestions)

/** A UUID for a new requirement. `crypto.randomUUID` rather than a derived hash:
 * `add` is authoring NEW content, so there is nothing to derive an id from, and a
 * random id is correct precisely because two identical `add` ops SHOULD produce two
 * requirements. (`import` derives ids instead, because a replay must be
 * reproducible — a different question, answered differently, in that module.) */
const newId = (): string => globalThis.crypto.randomUUID()

/**
 * Whether clearing `attr` would strip a slot the requirement's OWN pattern needs.
 * Returns the reason when the clear must be refused.
 *
 * v4's MN6 guard, carried verbatim in substance. `NULLABLE_ATTRS` answers
 * "may this field be absent in the schema"; this answers "may it be absent on THIS
 * requirement" — and the second is stricter. Without it, clearing `trigger` on an
 * event-driven requirement re-renders `"When , the auth service shall …"`, which is
 * a malformed sentence the lint tier then reports as the author's fault.
 */
const patternRequiresSlot = (
  pattern: Requirement['patternType'],
  attr: UpdatableAttr,
): string | undefined => {
  if (attr === 'trigger' && (pattern === 'event-driven' || pattern === 'unwanted-behavior')) {
    return `an ${pattern} requirement's trigger`
  }
  if (attr === 'preCondition' && (pattern === 'state-driven' || pattern === 'optional-feature')) {
    return `a ${pattern} requirement's pre-condition`
  }
  return undefined
}

/**
 * Resolve a ref through the single chokepoint, as an op result.
 *
 * Returns the REQUIREMENT, not just its id, and both halves of that matter. The id
 * is what a write must persist (a key would fail the document schema's UUID check);
 * the requirement is what the caller then reads — its `patternType` for the clear
 * guard, its edge arrays for an idempotence check. Returning only the id would make
 * every caller re-index the map and then guard the `undefined` that
 * `noUncheckedIndexedAccess` correctly insists on, for a lookup that provably
 * succeeded one line earlier.
 */
const requireTarget = (
  document: RequirementsDocument,
  ref: string | undefined,
  field: string,
  verb: string,
): Requirement | OpFailure => {
  if (ref === undefined) {
    return fail('ERR_USAGE', `The \`${verb}\` op requires "${field}".`, [
      `Add a "${field}" field naming a requirement by its stable key or its UUID.`,
    ])
  }
  const found = resolveRef(document, ref)
  if (found === undefined) {
    return fail(
      'ERR_NOT_FOUND',
      `No requirement matches "${ref}" (tried it as a UUID, then as a stable key).`,
      ['Run `symspec list` to see every requirement with its key and UUID.'],
    )
  }
  return found
}

// ---------------------------------------------------------------------------
// add
// ---------------------------------------------------------------------------

const applyAdd = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'add' }>,
  timestamp: string,
): OpSuccess | OpFailure => {
  const id = op.id ?? newId()

  if (document.requirements[id] !== undefined) {
    return fail('ERR_DUPLICATE_ID', `Requirement ${id} already exists.`, [
      'Use an `update` op to modify the existing requirement.',
      'Or omit "id" so a fresh UUID is minted.',
    ])
  }
  // A key must resolve to exactly ONE requirement, or key-addressing stops being as
  // safe as UUID-addressing — so a reused key is refused BEFORE anything is written.
  if (op.key !== undefined && resolveRef(document, op.key) !== undefined) {
    return fail('ERR_DUPLICATE_KEY', `Key "${op.key}" is already used by another requirement.`, [
      'Choose a different key.',
      'Or omit "key" to create the requirement without a stable key.',
    ])
  }

  const negated = op.negated ?? false
  const requirement: Requirement = {
    id,
    ...(op.key !== undefined ? { key: op.key } : {}),
    patternType: op.patternType,
    ...(op.preCondition !== undefined ? { preCondition: op.preCondition } : {}),
    ...(op.trigger !== undefined ? { trigger: op.trigger } : {}),
    systemName: op.systemName,
    systemResponse: op.systemResponse,
    negated,
    ...(op.responseKind !== undefined ? { responseKind: op.responseKind } : {}),
    // RE-RENDERED, never carried on the op — see the note in `./ops.ts`.
    sentence: renderSentence({
      patternType: op.patternType,
      preCondition: op.preCondition,
      trigger: op.trigger,
      systemName: op.systemName,
      systemResponse: op.systemResponse,
      negated,
    }),
    priority: op.priority ?? 'medium',
    status: op.status ?? 'draft',
    ...(op.verificationMethod !== undefined ? { verificationMethod: op.verificationMethod } : {}),
    ...(op.verificationNote !== undefined ? { verificationNote: op.verificationNote } : {}),
    // Edges are NOT part of `add`, deliberately: they arrive as their own ops, so
    // the op set stays orthogonal and every edge is individually idempotent.
    derives: [],
    satisfies: [],
    verifies: [],
    refines: [],
    createdAt: timestamp,
    updatedAt: timestamp,
  }

  return {
    document: { ...document, requirements: { ...document.requirements, [id]: requirement } },
    id,
    noop: false,
  }
}

// ---------------------------------------------------------------------------
// update
// ---------------------------------------------------------------------------

/** The five EARS structural slots whose edit re-renders `sentence`. A pure metadata
 * edit (priority/status/verification*) must NOT re-render, which is v4's
 * "five-way re-render gate". */
const EARS_SLOTS: ReadonlySet<UpdatableAttr> = new Set([
  'patternType',
  'preCondition',
  'trigger',
  'systemName',
  'systemResponse',
])

const applyUpdate = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'update' }>,
  timestamp: string,
): OpSuccess | OpFailure => {
  const target = requireTarget(document, op.ref, 'ref', 'update')
  if (isOpFailure(target)) return target

  if (op.value === null) {
    if (!NULLABLE_ATTRS.has(op.attr)) {
      return fail(
        'ERR_NULL_REQUIRED',
        `Cannot clear the required attribute "${op.attr}" on ${target.id}.`,
        [
          'Provide a value instead of null.',
          `Clearable attributes: ${[...NULLABLE_ATTRS].sort().join(', ')}.`,
        ],
      )
    }
    // The pattern-aware half — stricter than schema nullability. See
    // `patternRequiresSlot`.
    const required = patternRequiresSlot(target.patternType, op.attr)
    if (required !== undefined) {
      return fail(
        'ERR_NULL_REQUIRED',
        `Cannot clear ${op.attr} on a ${target.patternType} requirement — the pattern requires it.`,
        [
          `Set a new ${op.attr} value instead of clearing it.`,
          `Or change patternType first, if ${required} no longer applies.`,
        ],
      )
    }
  }

  // THE SECOND DOOR onto the V14/V21 hazard, closed with the same check.
  //
  // `stateEffect`/`stateConstraint` are in `UPDATABLE_ATTRS` (a state model is
  // authored iteratively, so editing one expression without restating the label has
  // to work), which means `update` can write an expression WITHOUT going through
  // `classify`. If it did so unvalidated, `symspec update stateConstraint "typo_var =
  // 1"` would put an undeclared reference straight into the document — and the failure
  // that produces is a solver hang, not a message. So the same validator runs here.
  //
  // Validated against the requirement's OWN kind rather than the attr alone: writing
  // a `stateEffect` onto a requirement classified `constraint` would store an
  // expression the encoder never reads, so the mismatch is refused too.
  if (op.value !== null && (op.attr === 'stateEffect' || op.attr === 'stateConstraint')) {
    const wanted = op.attr === 'stateEffect' ? 'effect' : 'constraint'
    if (target.responseKind !== undefined && target.responseKind !== wanted) {
      return usage(
        `${target.key ?? target.id} is classified ${target.responseKind}, so setting \`${op.attr}\` would store an expression nothing reads.`,
        [
          `Reclassify and set the expression in one step: \`symspec classify ${target.key ?? target.id} --kind ${wanted} --expression "${op.value}"\`.`,
        ],
      )
    }
    const checked =
      wanted === 'effect'
        ? validateEffect(op.value, document.stateModel)
        : validateExpression(op.value, document.stateModel, 'constraint')
    if (isExprError(checked)) {
      return usage(
        `The ${wanted} "${op.value}" on ${target.key ?? target.id} is not valid: ${checked.error}`,
        [...checked.suggestions],
      )
    }
  }

  // Build the next requirement by KEY, so a clear is a genuinely absent key rather
  // than an `undefined` value — the exactOptionalPropertyTypes discipline reaching
  // the persisted file, which is what keeps a save byte-stable.
  const next: Record<string, unknown> = { ...target }
  if (op.value === null) delete next[op.attr]
  else next[op.attr] = op.value

  const updated = next as unknown as Requirement
  const rendered = EARS_SLOTS.has(op.attr)
    ? { ...updated, sentence: renderSentence(updated), updatedAt: timestamp }
    : { ...updated, updatedAt: timestamp }

  return {
    document: {
      ...document,
      requirements: { ...document.requirements, [target.id]: rendered },
    },
    id: target.id,
    noop: false,
  }
}

// ---------------------------------------------------------------------------
// delete
// ---------------------------------------------------------------------------

const applyDelete = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'delete' }>,
): OpSuccess | OpFailure => {
  // `ref` wins over `id`; both are key-or-UUID. Donor parity — a stream written
  // against v4's `apply` used either spelling.
  const target = requireTarget(document, op.ref ?? op.id, 'ref (or id)', 'delete')
  if (isOpFailure(target)) return target

  const requirements = { ...document.requirements }
  delete requirements[target.id]
  // Inbound edges from other requirements become DANGLING rather than being
  // cascaded away, matching v4: `check` surfaces a dangling reference as a
  // finding, and silently rewriting other requirements' edges would be a mutation
  // the caller did not ask for.
  return { document: { ...document, requirements }, id: target.id, noop: false }
}

// ---------------------------------------------------------------------------
// Edges
// ---------------------------------------------------------------------------

const applyEdge = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: keyof typeof EDGE_OP_RELATION }>,
  timestamp: string,
): OpSuccess | OpFailure => {
  const source = requireTarget(document, op.from, 'from', op.op)
  if (isOpFailure(source)) return source
  const to = requireTarget(document, op.to, 'to', op.op)
  if (isOpFailure(to)) return to

  const relation: Relation = EDGE_OP_RELATION[op.op]

  // IDEMPOTENT: an existing edge is a no-op success, so replaying a repair plan
  // never duplicates one.
  if (source[relation].includes(to.id)) {
    return { document, id: source.id, noop: true }
  }

  return {
    document: {
      ...document,
      requirements: {
        ...document.requirements,
        [source.id]: {
          ...source,
          [relation]: [...source[relation], to.id],
          updatedAt: timestamp,
        },
      },
    },
    id: source.id,
    noop: false,
  }
}

const applyRemoveEdge = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'remove-edge' }>,
  timestamp: string,
): OpSuccess | OpFailure => {
  const source = requireTarget(document, op.from, 'from', 'remove-edge')
  if (isOpFailure(source)) return source
  const to = requireTarget(document, op.to, 'to', 'remove-edge')
  if (isOpFailure(to)) return to

  // Removing an absent edge is a no-op success (v4 AC-1-7: "safe to call
  // defensively").
  if (!source[op.relation].includes(to.id)) {
    return { document, id: source.id, noop: true }
  }

  return {
    document: {
      ...document,
      requirements: {
        ...document.requirements,
        [source.id]: {
          ...source,
          [op.relation]: source[op.relation].filter((t) => t !== to.id),
          updatedAt: timestamp,
        },
      },
    },
    id: source.id,
    noop: false,
  }
}

// ---------------------------------------------------------------------------
// The side tables
// ---------------------------------------------------------------------------

/**
 * Commit one synonym alias — refusing the two shapes that resolve by table ORDER.
 *
 * `glossaryIndex` (the atomizer's reader) is a flat `normalize(alias) -> normalize(canonical)`
 * map built by iterating the groups, so a phrase appearing twice is silently last-write-wins,
 * and lookup is ONE HOP, so a canonical that is itself an alias never resolves. Neither shape
 * errors anywhere downstream; both just quietly do something other than what the author asked
 * for. So both are refused HERE, at write time, which is the same discipline
 * {@link MutateOptions.validateAntonyms} applies for the same reason — the check path stays
 * free of "this table was incoherent" branches.
 *
 * Matching is done in NORMALIZED space because that is the space the index keys. Exact-string
 * matching let `"Issue a token"` and `"issue a token"` become two groups that
 * `glossaryIndex` then collapses onto one key, which is the same defect arriving by a
 * different door. The stored spelling of an existing canonical is preserved rather than
 * rewritten: an author's capitalization is theirs, and rewriting it would make committing an
 * alias silently edit a row the author did not name.
 */
const applyGlossary = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'glossary' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const canonical = op.canonical.trim()
  const alias = op.alias.trim()
  if (canonical.length === 0 || alias.length === 0) {
    return fail('ERR_USAGE', 'A `glossary` op requires a non-empty canonical and alias.', [
      'Both fields name a RESPONSE phrasing, e.g. canonical "issue a session token", alias "issue a login credential".',
    ])
  }
  const canonicalKey = norm(canonical)
  const aliasKey = norm(alias)
  if (canonicalKey === aliasKey) {
    return fail('ERR_USAGE', `"${canonical}" cannot be an alias of itself.`, [
      'A glossary entry unifies two DIFFERENT phrasings; these normalize to the same key.',
    ])
  }

  const entry = document.glossary.find((e) => norm(e.canonical) === canonicalKey)
  // IDEMPOTENT: this alias already sits under this canonical.
  if (entry?.aliases.some((a) => norm(a) === aliasKey) === true) {
    return { document, noop: true }
  }

  // The alias already belongs to a DIFFERENT group. Accepting would put one key in two
  // groups, and the winner would be whichever group `glossaryIndex` visits last.
  const otherOwner = document.glossary.find(
    (e) => norm(e.canonical) !== canonicalKey && e.aliases.some((a) => norm(a) === aliasKey),
  )
  if (otherOwner !== undefined) {
    return fail(
      'ERR_USAGE',
      `"${alias}" is already an alias of "${otherOwner.canonical}", so it cannot also be an alias of "${canonical}".`,
      [
        `Free it first: \`symspec glossary "${otherOwner.canonical}" "${alias}" --remove\`.`,
        `Or point this entry at "${otherOwner.canonical}" instead, if that is the reading you meant.`,
      ],
    )
  }

  // The canonical is itself an alias. Alias resolution is ONE HOP, so the chain would never
  // resolve and the merge would silently not happen.
  const canonicalIsAlias = document.glossary.find(
    (e) => norm(e.canonical) !== canonicalKey && e.aliases.some((a) => norm(a) === canonicalKey),
  )
  if (canonicalIsAlias !== undefined) {
    return fail(
      'ERR_USAGE',
      `"${canonical}" is already an alias of "${canonicalIsAlias.canonical}", so it cannot also be a canonical.`,
      [
        'Alias resolution is one hop, so this chain would never resolve.',
        `Use "${canonicalIsAlias.canonical}" as the canonical: \`symspec glossary "${canonicalIsAlias.canonical}" "${alias}"\`.`,
      ],
    )
  }

  const glossary: GlossaryEntry[] =
    entry === undefined
      ? [...document.glossary, { canonical, aliases: [alias] }]
      : document.glossary.map((e) =>
          // The EXISTING canonical spelling is kept, not `canonical`.
          norm(e.canonical) === canonicalKey
            ? { canonical: e.canonical, aliases: [...e.aliases, alias] }
            : e,
        )
  const refused = options.validateGlossary?.({ ...document, glossary }, canonicalKey, aliasKey)
  if (refused !== undefined) {
    return fail('ERR_USAGE', `"${alias}" cannot be an alias of "${canonical}": ${refused}.`, [
      'A glossary entry says its phrases are ONE action; an antonym pair says two actions cannot both happen.',
      'If the two are opposites, keep them apart — the antonym table already relates them. If they are one action, rewrite one requirement in the other`s words.',
    ])
  }
  return { document: { ...document, glossary }, noop: false }
}

/**
 * Remove one alias. Matched in NORMALIZED space, symmetrically with {@link applyGlossary}.
 *
 * The symmetry is load-bearing rather than tidy: an entry committed as `"Issue a token"` must
 * be removable by naming `"issue a token"`, or the refusal `applyGlossary` now raises would
 * point at an `--remove` that no-ops, leaving an author stuck with a row they cannot free.
 */
const applyUnglossary = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'unglossary' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const canonicalKey = norm(op.canonical.trim())
  const aliasKey = norm(op.alias.trim())
  const entry = document.glossary.find((e) => norm(e.canonical) === canonicalKey)
  if (entry === undefined || !entry.aliases.some((a) => norm(a) === aliasKey)) {
    return { document, noop: true }
  }
  // An emptied group is DROPPED entirely — a canonical with no aliases unifies
  // nothing, so keeping it would be a row that looks like a decision and is not.
  const glossary = document.glossary
    .map((e) =>
      norm(e.canonical) === canonicalKey
        ? { canonical: e.canonical, aliases: e.aliases.filter((a) => norm(a) !== aliasKey) }
        : e,
    )
    .filter((e) => e.aliases.length > 0)
  return { document: { ...document, glossary }, noop: false }
}

/** Canonical, order-independent key for an antonym pair. */
const pairKey = (a: string, b: string): string => [a, b].sort().join(' ')

/**
 * The antonym-consistency validator, injected.
 *
 * `core/` must not import the transplanted formal tier — the dependency runs the
 * other way (`../formal/compat.ts` reads `core/`, never the reverse), and a cycle
 * would put the atomizer in the load graph of every document read. So the caller
 * supplies the check, and `../operations/mutation.ts` wires the real
 * `buildAntonymIndexWithDoc`.
 *
 * The check is not optional bookkeeping: an antonym pair is the ONE committed
 * record whose wrong value MANUFACTURES a false contradiction. An odd polarity
 * cycle (asserting a↔b when a and b already resolve to the same polarity through
 * the seed table) makes the index builder throw — and it must throw HERE, at write
 * time with a usage error, so the check path stays throw-free.
 */
export interface MutateOptions {
  /**
   * Validate a candidate antonym table. Return an error MESSAGE to refuse the
   * write, or `undefined` to accept. Omitted ⇒ no validation, which is correct for
   * a caller with no formal tier available (and unsound for the CLI, which is why
   * the operation layer always supplies it).
   */
  readonly validateAntonyms?: (pairs: readonly AntonymPair[]) => string | undefined
  /**
   * Normalize a phrase to the atomizer's key — a verb head for `antonym`, a whole response
   * phrasing for `glossary`. It is the same `normalize` in both cases, because
   * `glossaryIndex` and the antonym index key the same way.
   *
   * Omitted ⇒ a trim, which stores the text as written and makes the glossary's
   * collision checks case-sensitive. The operation layer supplies the real `normalize`, so a
   * committed record matches what the atomizer looks up.
   */
  readonly normalizeHead?: (text: string) => string
  /**
   * Validate a candidate TERM. Return an error MESSAGE to refuse the write, or `undefined` to
   * accept. Both arguments arrive already normalized.
   *
   * Injected for the same reason as {@link validateAntonyms}: the check needs the engine's
   * antonym index and the guard-implication tier's establish-verb lexicon, and
   * `domain/requirements` must not import the engine. Omitted ⇒ no validation, which is correct
   * for a caller with no engine available and unsound for the CLI — so the operation layer
   * always supplies it.
   *
   * What it refuses, and why it must: a term containing a verb that either lexicon reads moves
   * the polarity `atomize` computes for a state-establishing response while leaving the
   * raw-text parse that RECOGNISES the bridge unchanged. The two disagreeing lets a committed
   * term prove a contradiction the document does not contain — an error-severity fabrication,
   * which is the one outcome the propose/decide split exists to prevent.
   */
  readonly validateTerms?: (canonical: string, alias: string) => string | undefined
  /**
   * Validate a candidate GLOSSARY entry: `document` is the fold's result with the alias added,
   * and `canonical` / `alias` are the entry's two keys, normalized. Return an error MESSAGE to
   * refuse the write, or `undefined` to accept.
   *
   * Injected for the same reason as {@link validateAntonyms}. What it refuses: an alias that is
   * a CONTRARY of another phrase its entry names under the antonym table ("close the door" as an
   * alias of "open the door"). The entry says the two are one action and the table says they
   * cannot both happen, so together they say neither ever does. Defense in depth — an antonym
   * or term committed afterwards can form the same entry with no glossary write to refuse, so
   * the soundness guarantee is the atomizer keeping each contrary on its own atom linked to the
   * entry's action, and `check` demoting over what that leaves undecided.
   */
  readonly validateGlossary?: (
    document: RequirementsDocument,
    canonical: string,
    alias: string,
  ) => string | undefined
  /**
   * The WAIVABILITY policy (spec 007 AC-5-6): the class of a finding code and whether a waiver
   * may suppress it, or `undefined` for a code no catalog publishes.
   *
   * Injected for the same reason as {@link validateAntonyms}: the class table is the published
   * catalog's, which this module does not load. Supplied, it makes `waive` refuse with
   * `ERR_WAIVER_REFUSED` a `never`-class code in every scope, a code with no class, and a
   * waiver that names no requirement; and it stores every accepted waiver in the one scoped
   * form, `requirementIds` plus the content hash of their current text (a `ref` becomes
   * `refs: [ref]`). Omitted ⇒ the fold stores what the op says, which is correct for a caller
   * with no catalog and unsound for the CLI — so the operation layer always supplies it.
   */
  readonly waiverPolicy?: (code: string) => WaiverPolicyRow | undefined
}

/** One code's row under {@link MutateOptions.waiverPolicy}. */
export interface WaiverPolicyRow {
  /** The finding class the code belongs to (`verdict`, `wording`, …), named in a refusal. */
  readonly class: string
  /** `scoped`: waivable over named requirements and their current text. `never`: not at all. */
  readonly waivable: 'scoped' | 'never'
}

const applyAntonym = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'antonym' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const a = norm(op.a)
  const b = norm(op.b)
  if (a.length === 0 || b.length === 0) {
    return fail('ERR_USAGE', 'An `antonym` op requires two non-empty response verb-heads.', [
      'Each is the LEADING VERB of a response, e.g. a "open", b "shut".',
    ])
  }
  if (a === b) {
    return fail('ERR_USAGE', `"${a}" cannot be its own antonym.`, [
      'Supply two DIFFERENT verb-heads; a verb is not its own opposite.',
    ])
  }

  const key = pairKey(a, b)
  if (document.antonyms.some((p) => pairKey(norm(p.a), norm(p.b)) === key)) {
    return { document, noop: true }
  }

  const candidate: AntonymPair[] = [...document.antonyms, { a, b }]
  const inconsistent = options.validateAntonyms?.(candidate)
  if (inconsistent !== undefined) {
    return fail(
      'ERR_USAGE',
      `The antonym pair "${a}"/"${b}" is inconsistent with the committed antonyms: ${inconsistent}`,
      [
        'The signed antonym classes must stay consistent — this pair would create an odd polarity cycle.',
        'Inspect the committed pairs and the seed table before re-asserting this one.',
      ],
    )
  }

  return { document: { ...document, antonyms: candidate }, noop: false }
}

const applyUnantonym = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'unantonym' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const key = pairKey(norm(op.a), norm(op.b))
  const antonyms = document.antonyms.filter((p) => pairKey(norm(p.a), norm(p.b)) !== key)
  if (antonyms.length === document.antonyms.length) return { document, noop: true }
  return { document: { ...document, antonyms }, noop: false }
}

/**
 * Commit one noun-phrase term — with the refusal that keeps the feature sound.
 *
 * Mirrors {@link applyGlossary}'s four checks, for the same reasons, in the same normalized
 * space. Two things are different, and both come from the substitution being applied INSIDE a
 * body rather than replacing one.
 *
 * **One-hop in TOKEN space (the `canonical contains an alias` refusal).** `atomize` substitutes
 * in a single pass and continues after the tokens it wrote, so a canonical containing a
 * committed alias is NOT rewritten a second time. Accepting such an entry would therefore mean
 * the table's effect depends on whether the reader expects a second pass. Refusing it is the
 * token-space analogue of `applyGlossary`'s one-hop rule, and it keeps the decide key
 * unambiguous.
 *
 * **The verb refusal, delegated to {@link MutateOptions.validateTerms}.** A term that rewrites
 * a response VERB desyncs two pipelines that must agree: `guard-implication` decides whether a
 * response establishes a state by parsing the RAW text, while the bridge's polarity comes from
 * the full `atomize` — which sees the substitution. Rewrite a head into an antonym class and
 * the bridge is still recognised while its polarity flips, so it asserts the negation of what
 * the document says and can prove a contradiction that is not there. Error severity, tool's own
 * doing. So terms are for NOUNS, and that is enforced here rather than documented; the check
 * lives behind the same injection seam as `validateAntonyms` because `domain/requirements` must
 * not import the engine tier.
 */
const applyTerm = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'term' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const canonical = op.canonical.trim()
  const alias = op.alias.trim()
  if (canonical.length === 0 || alias.length === 0) {
    return fail('ERR_USAGE', 'A `term` op requires a non-empty canonical and alias.', [
      'Both fields name a NOUN PHRASE, e.g. canonical "session token", alias "login credential".',
    ])
  }
  const canonicalKey = norm(canonical)
  const aliasKey = norm(alias)
  if (canonicalKey === aliasKey) {
    return fail('ERR_USAGE', `"${canonical}" cannot be a term alias of itself.`, [
      'A term entry unifies two DIFFERENT noun phrases; these normalize to the same key.',
    ])
  }

  const rejected = options.validateTerms?.(canonicalKey, aliasKey)
  if (rejected !== undefined) {
    return fail(
      'ERR_USAGE',
      `The term "${canonical}" / "${alias}" is not committable: ${rejected}`,
      [
        'A term is substituted inside EVERY slot body, so a verb in one moves the polarity the',
        'solver computes while leaving the raw-text bridge parse unchanged — which can prove a',
        'conflict the document does not contain.',
        'Use `symspec glossary "<canonical phrasing>" "<alias phrasing>"` to align a whole phrasing that contains a verb.',
      ],
    )
  }

  const entry = document.terms.find((e) => norm(e.canonical) === canonicalKey)
  // IDEMPOTENT: this alias already sits under this canonical.
  if (entry?.aliases.some((a) => norm(a) === aliasKey) === true) {
    return { document, noop: true }
  }

  const otherOwner = document.terms.find(
    (e) => norm(e.canonical) !== canonicalKey && e.aliases.some((a) => norm(a) === aliasKey),
  )
  if (otherOwner !== undefined) {
    return fail(
      'ERR_USAGE',
      `"${alias}" is already a term alias of "${otherOwner.canonical}", so it cannot also be an alias of "${canonical}".`,
      [
        `Free it first: \`symspec term "${otherOwner.canonical}" "${alias}" --remove\`.`,
        `Or point this entry at "${otherOwner.canonical}" instead, if that is the reading you meant.`,
      ],
    )
  }

  const canonicalIsAlias = document.terms.find(
    (e) => norm(e.canonical) !== canonicalKey && e.aliases.some((a) => norm(a) === canonicalKey),
  )
  if (canonicalIsAlias !== undefined) {
    return fail(
      'ERR_USAGE',
      `"${canonical}" is already a term alias of "${canonicalIsAlias.canonical}", so it cannot also be a canonical.`,
      [
        'Term substitution is one pass, so this chain would never resolve.',
        `Use "${canonicalIsAlias.canonical}" as the canonical: \`symspec term "${canonicalIsAlias.canonical}" "${alias}"\`.`,
      ],
    )
  }

  // One-hop in TOKEN space. The substitution scans left to right, takes the LONGEST alias at each
  // position, writes its canonical and continues after it (`substituteTerms` in the atomizer).
  // That is a congruence, so two phrases the table calls one noun come out as one atom in every
  // body, exactly when NO alias overlaps another phrase of the table: not inside it, not equal
  // to it, not around it, and not straddling one of its edges. An alias that overlaps a
  // canonical rewrites the canonical's own occurrences while the canonical's aliases still
  // rewrite TO it; an alias that overlaps another alias wins or loses the longest-first race
  // depending on the words around it. Either way two phrases the table merged come out
  // different, and a conflict resting on them is gone. Two canonicals may overlap freely,
  // because a canonical is never matched.
  // Split on EITHER separator. `normalizeHead` is the atomizer's `normalize` in production
  // (underscore-joined), and a bare trim in a caller that has no engine — so a check that split
  // only on `_` would be silently inert for the second, which is the shape a test would then
  // fail to reach.
  const tokensOf = (key: string) => key.split(/[\s_]+/).filter((t) => t.length > 0)
  const contains = (haystack: readonly string[], needle: readonly string[]): boolean => {
    if (needle.length === 0 || needle.length > haystack.length) return false
    for (let i = 0; i + needle.length <= haystack.length; i++) {
      if (needle.every((t, k) => haystack[i + k] === t)) return true
    }
    return false
  }
  // A proper suffix of `x` is a proper prefix of `y`: the two would straddle in a body.
  const straddles = (x: readonly string[], y: readonly string[]): boolean => {
    for (let k = 1; k < Math.min(x.length, y.length); k++) {
      if (y.slice(0, k).every((t, i) => x[x.length - k + i] === t)) return true
    }
    return false
  }
  // How `x` sits against `y`, worded for the refusal; `undefined` when they share no span.
  const overlap = (x: string, y: string): string | undefined => {
    const [xs, ys] = [tokensOf(x), tokensOf(y)]
    if (xs.length === ys.length && contains(xs, ys)) return 'is'
    if (contains(xs, ys)) return 'contains'
    if (contains(ys, xs)) return 'sits inside'
    if (straddles(xs, ys) || straddles(ys, xs)) return 'overlaps an edge of'
    return undefined
  }
  const ambiguity = [
    'Term substitution is a single pass that takes the longest alias at each position and',
    'continues after the tokens it wrote, so an alias overlapping another phrase of the table',
    "rewrites some of that phrase's occurrences and not others — two phrases the table calls one",
    'noun would reach the solver as two.',
  ]

  const committedAliases = [
    ...document.terms.flatMap((e) => e.aliases.map((a) => norm(a))),
    aliasKey,
  ]
  for (const a of committedAliases) {
    const relation = a === canonicalKey ? undefined : overlap(canonicalKey, a)
    if (relation === undefined) continue
    return fail(
      'ERR_USAGE',
      `The canonical "${canonical}" ${relation} the committed term alias "${a.replace(/_/g, ' ')}", so the table would be ambiguous.`,
      [...ambiguity, 'Reword the canonical so it does not overlap an alias.'],
    )
  }

  // The same rule from the alias's side: the new alias against every canonical (its own
  // included) and every other alias. Refusing only a canonical that swallows an alias left this
  // half open — `term invoice purchase` split "purchase order" from its committed alias.
  const phrases = [
    ...document.terms.map((e) => ['canonical', norm(e.canonical)] as const),
    ['canonical', canonicalKey] as const,
    ...document.terms.flatMap((e) =>
      e.aliases.map((a) => ['alias', norm(a)] as const).filter(([, a]) => a !== aliasKey),
    ),
  ]
  for (const [role, p] of phrases) {
    const relation = overlap(aliasKey, p)
    if (relation === undefined) continue
    const shown = p.replace(/_/g, ' ')
    return fail(
      'ERR_USAGE',
      `The alias "${alias}" ${relation} the committed term ${role} "${shown}", so the table would be ambiguous.`,
      [
        ...ambiguity,
        `Name the whole noun instead: an alias of "${shown}" itself, or a phrase that shares no word with it at an edge.`,
      ],
    )
  }

  const terms: TermEntry[] =
    entry === undefined
      ? [...document.terms, { canonical, aliases: [alias] }]
      : document.terms.map((e) =>
          // The EXISTING canonical spelling is kept, not `canonical`.
          norm(e.canonical) === canonicalKey
            ? { canonical: e.canonical, aliases: [...e.aliases, alias] }
            : e,
        )
  return { document: { ...document, terms }, noop: false }
}

/** Remove one term alias. Matched in NORMALIZED space, symmetrically with {@link applyTerm}. */
const applyUnterm = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'unterm' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const norm = options.normalizeHead ?? ((s: string) => s.trim())
  const canonicalKey = norm(op.canonical.trim())
  const aliasKey = norm(op.alias.trim())
  const entry = document.terms.find((e) => norm(e.canonical) === canonicalKey)
  if (entry === undefined || !entry.aliases.some((a) => norm(a) === aliasKey)) {
    return { document, noop: true }
  }
  // An emptied group is DROPPED entirely, as in `applyUnglossary`: a canonical with no aliases
  // substitutes nothing, so keeping it would be a row that looks like a decision and is not.
  const terms = document.terms
    .map((e) =>
      norm(e.canonical) === canonicalKey
        ? { canonical: e.canonical, aliases: e.aliases.filter((a) => norm(a) !== aliasKey) }
        : e,
    )
    .filter((e) => e.aliases.length > 0)
  return { document: { ...document, terms }, noop: false }
}

/** The exact-set scope as a comparable key: sorted, deduplicated, `undefined` when absent. */
const idSetKey = (ids: readonly string[] | undefined): string | undefined =>
  ids === undefined ? undefined : [...new Set(ids)].sort().join(',')

/**
 * Two waivers match iff they suppress the same code at the same scope. For an exact-set waiver
 * the scope includes the bound text: re-reviewing an EDITED pair is a new waiver, not a no-op
 * against the stale one.
 */
const sameWaiver = (a: Waiver, b: Waiver): boolean =>
  a.code === b.code &&
  a.requirementId === b.requirementId &&
  idSetKey(a.requirementIds) === idSetKey(b.requirementIds) &&
  a.contentHash === b.contentHash

/** Resolve every ref of a `refs` scope to its UUID, sorted and deduplicated. */
const resolveRefs = (
  document: RequirementsDocument,
  refs: readonly string[],
  verb: string,
): string[] | OpFailure => {
  if (refs.length === 0) {
    return fail('ERR_USAGE', `The \`${verb}\` op's "refs" must name at least one requirement.`, [
      'Omit "refs" for an unscoped waiver, or list the requirement ids of the finding you reviewed.',
    ])
  }
  const ids = new Set<string>()
  for (const ref of refs) {
    const scoped = requireTarget(document, ref, 'refs', verb)
    if (isOpFailure(scoped)) return scoped
    ids.add(scoped.id)
  }
  return [...ids].sort()
}

/**
 * The waivability refusal (spec 007 AC-5-6), or `undefined` when the policy lets `code` be
 * waived at all. A `never` class is refused whatever the scope, so it is decided before the
 * scope is read: no `refs` or hash would make a verdict, a disclosure or a triage candidate a
 * thing a reviewer can accept.
 */
const waiverClassRefusal = (
  code: string,
  row: WaiverPolicyRow | undefined,
): OpFailure | undefined => {
  if (row === undefined) {
    return fail(
      'ERR_WAIVER_REFUSED',
      `No catalog publishes the code \`${code}\`, so it has no waivability class and cannot be waived.`,
      [
        `Run \`symspec explain --code ${code}\` for the nearest published codes, and waive the exact code a \`symspec check\` finding carries.`,
      ],
    )
  }
  if (row.waivable === 'scoped') return undefined
  return fail(
    'ERR_WAIVER_REFUSED',
    `\`${code}\` is a ${row.class}-class finding, and a ${row.class} finding is never waivable, in any scope: only a change to what the document says discharges it.`,
    [
      `Read the finding's message and demotion action (\`symspec check\`), then rewrite the requirement it names (\`symspec update --ref <id> <attr> "<wording>"\`), or commit the \`symspec antonym <verbA> <verbB>\` or \`symspec glossary "<canonical>" "<alias>"\` entry it proposes where the two phrasings really are contraries or one action.`,
      `\`symspec explain --code ${code}\` states what the code means and how it is discharged.`,
    ],
  )
}

const applyWaive = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'waive' }>,
  options: MutateOptions,
): OpSuccess | OpFailure => {
  const code = op.code.trim()
  const reason = op.reason.trim()
  if (code.length === 0 || reason.length === 0) {
    return fail('ERR_USAGE', 'A `waive` op requires a non-empty code and reason.', [
      'The reason is the audit trail that distinguishes a reviewed waiver from neglect — write the actual justification.',
    ])
  }

  const policy = options.waiverPolicy
  if (policy !== undefined) {
    const refused = waiverClassRefusal(code, policy(code))
    if (refused !== undefined) return refused
  }

  if (op.ref !== undefined && op.refs !== undefined) {
    return fail('ERR_USAGE', 'A `waive` op takes "ref" or "refs", not both.', [
      '"ref" waives every finding of the code that names one requirement; "refs" waives only the finding over exactly those requirements, as they are written now.',
    ])
  }

  // Under the policy a waiver is ALWAYS scoped and bound to the text it was reviewed on: a
  // waiver by code alone reaches every finding of the code, including ones raised after the
  // review over requirements nobody read, so it is refused; a single `ref` is the exact set of
  // that one requirement, normalized here so it is stored, hashed, in the one scoped form.
  if (policy !== undefined) {
    if (op.ref === undefined && op.refs === undefined) {
      return fail(
        'ERR_WAIVER_REFUSED',
        `A \`waive\` of \`${code}\` must name the requirement ids of the finding it accepts ("refs"): a waiver by code alone would reach every finding of the code, including ones nobody reviewed.`,
        [
          `Copy the waive op from the finding's \`repair.ops\` (\`symspec check\`): it carries "refs" and the content hash of the text the finding was raised on.`,
          `Or pass the finding's requirement with \`symspec waive ${code} --ref <id> --reason "…"\`.`,
        ],
      )
    }
    if (op.ref !== undefined) {
      const { ref, ...rest } = op
      return applyWaive(document, { ...rest, refs: [ref] }, options)
    }
  }

  if (op.contentHash !== undefined && op.refs === undefined) {
    return fail('ERR_USAGE', 'A `waive` op\'s "contentHash" binds a "refs" scope; add "refs".', [
      "Copy the op from the finding's `repair.ops` as-is: it carries both.",
    ])
  }

  // An optional scope is resolved to the stable UUID before storing, so a waiver
  // keeps biting the right requirement regardless of any human-facing relabeling.
  let requirementId: string | undefined
  if (op.ref !== undefined) {
    const scoped = requireTarget(document, op.ref, 'ref', 'waive')
    if (isOpFailure(scoped)) return scoped
    requirementId = scoped.id
  }

  // An exact-set scope is bound to the text it names NOW. The op's own hash, when it carries
  // one, is the text `check` raised the finding on; a mismatch means the requirements were
  // edited since, so the reviewer read something other than what would be waived.
  let exact: Pick<Waiver, 'requirementIds' | 'contentHash'> = {}
  if (op.refs !== undefined) {
    const ids = resolveRefs(document, op.refs, 'waive')
    if (isOpFailure(ids)) return ids
    const contentHash = requirementsContentHash(document, ids)!
    if (op.contentHash !== undefined && op.contentHash !== contentHash) {
      return fail(
        'ERR_USAGE',
        `The requirements this \`waive\` names have changed since the finding was raised (content hash ${op.contentHash}, now ${contentHash}).`,
        [
          `Re-run \`symspec check\`, re-read ${ids.map((id) => `\`symspec show ${id}\``).join(' and ')}, and waive from the new finding's repair only if the new text is consistent too.`,
        ],
      )
    }
    exact = { requirementIds: ids, contentHash }
  }

  const waiver: Waiver = {
    code,
    ...(requirementId !== undefined ? { requirementId } : {}),
    ...exact,
    reason,
  }
  // IDEMPOTENT, and the STORED reason wins: the first review is authoritative, so
  // re-waiving with different prose does not quietly overwrite the original
  // justification.
  if (document.waivers.some((w) => sameWaiver(w, waiver))) {
    return { document, noop: true }
  }
  return { document: { ...document, waivers: [...document.waivers, waiver] }, noop: false }
}

const applyUnwaive = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'unwaive' }>,
): OpSuccess | OpFailure => {
  // The code is matched EXACTLY as stored (ruling R55): a hand-written ` FND_X` is its own row,
  // and trimming it here would also delete the canonical `FND_X` waiver beside it.
  const code = op.code
  // A ref that resolves to nothing is matched as written: a stored waiver can still name a
  // requirement the document has since deleted, and an unresolved ref must not widen into the
  // unscoped key and delete the code-only or another scoped waiver of the code (R55).
  const requirementId = op.ref !== undefined ? (resolveId(document, op.ref) ?? op.ref) : undefined
  // `refs` removes every exact-set waiver over that set, whatever text it was bound to — the
  // stale ones are exactly what an author clearing a pair wants gone.
  const ids = op.refs?.map((ref) => resolveId(document, ref) ?? ref)
  const matches = (w: Waiver): boolean =>
    w.code === code &&
    w.requirementId === requirementId &&
    idSetKey(w.requirementIds) === idSetKey(ids)
  const waivers = document.waivers.filter((w) => !matches(w))
  if (waivers.length === document.waivers.length) return { document, noop: true }
  return { document: { ...document, waivers }, noop: false }
}

// ---------------------------------------------------------------------------
// The state model (G4)
// ---------------------------------------------------------------------------

/**
 * Build one {@link StateVariable} from a `state` op.
 *
 * ## Why the per-type rules are re-stated here rather than left to the schema
 *
 * The document schema ALREADY states them structurally — `StateVariable` is a union
 * whose `bool` member has no `domain` key, whose `enum` member requires one, and whose
 * `int` member carries optional bounds — and that union is what the manifest
 * publishes. So a wrong shape would be caught on save regardless, and this function
 * could in principle just assemble and let the decode fail.
 *
 * It does not, because the two failures are not equally useful. A schema failure on
 * save reports a JSON PATH (`at ["stateModel"]["variables"][2]`) against a value the
 * caller never typed — they typed `--type enum` and forgot `--domain`. The rules are
 * therefore checked HERE, where the message can name the flag and the fix, and the
 * schema remains the backstop that makes a hand-edited file safe. That is the same
 * split `applyUpdate`'s clear guard already uses: `NULLABLE_ATTRS` answers "may the
 * schema omit this", the fold answers "may THIS caller omit it", and both are needed
 * because they answer different questions.
 *
 * The one rule that is genuinely only here is the EMPTY RANGE (`min > max`), which the
 * schema cannot express: both bounds are individually valid integers, and their
 * relationship is a cross-field constraint. It matters more than it looks — an empty
 * range is an empty state space, over which every invariant holds VACUOUSLY, so a
 * document carrying one would get a clean reachability proof that means nothing.
 */
const stateVariableOf = (op: Extract<DocumentOp, { op: 'state' }>): StateVariable | OpFailure => {
  // The frame defaults HERE, to the sound value. See `FRAME_KINDS` — a missing
  // declaration may only ever weaken a claim, so an absent `frame` is `volatile`.
  const frame = op.frame ?? 'volatile'
  const initial = op.initial?.trim()
  const common = {
    name: op.name,
    frame,
    ...(initial !== undefined && initial.length > 0 ? { initial } : {}),
  }

  if (op.type === 'bool') {
    if (op.domain !== undefined || op.min !== undefined || op.max !== undefined) {
      return usage(
        `A bool variable has no domain: ${JSON.stringify(op.name)} was declared bool with domain/bounds.`,
        [
          "A bool's domain is {true,false} by construction — declaring one would let the document claim a boolean with three values.",
          'Drop --domain/--min/--max, or declare the variable as `enum` (with --domain) or `int` (with --min/--max).',
        ],
      )
    }
    return { ...common, type: 'bool' }
  }

  if (op.type === 'int') {
    if (op.domain !== undefined) {
      return usage(
        `An int variable's range is --min/--max, not --domain: ${JSON.stringify(op.name)}.`,
        ['Use --min and/or --max for an int; --domain lists the members of an `enum`.'],
      )
    }
    if (op.min !== undefined && op.max !== undefined && op.min > op.max) {
      // An empty range is an EMPTY STATE SPACE, and every invariant over it holds
      // vacuously — the exact "a proof can be vacuously true and the tool would not
      // know" failure the sanity gates exist for. Cheaper to refuse the declaration.
      return usage(
        `The declared range of ${JSON.stringify(op.name)} is empty: min ${op.min} > max ${op.max}.`,
        [
          'An empty range gives the encoder no states at all, so every invariant over it would hold VACUOUSLY.',
          `Swap them: --min ${op.max} --max ${op.min}.`,
        ],
      )
    }
    const domain =
      op.min !== undefined || op.max !== undefined
        ? {
            domain: {
              ...(op.min !== undefined ? { min: op.min } : {}),
              ...(op.max !== undefined ? { max: op.max } : {}),
            },
          }
        : {}
    return { ...common, type: 'int', ...domain }
  }

  // enum
  const members = (op.domain ?? []).map((m) => m.trim()).filter((m) => m.length > 0)
  if (members.length === 0) {
    return usage(`An enum variable requires a non-empty --domain: ${JSON.stringify(op.name)}.`, [
      'List the members: --domain "PENDING,RUNNING,DONE,FAILED".',
      'An enum with an empty domain would give the encoder an empty state space, so every invariant over it would hold VACUOUSLY.',
    ])
  }
  const duplicate = members.find((m, i) => members.indexOf(m) !== i)
  if (duplicate !== undefined) {
    return usage(
      `The enum domain of ${JSON.stringify(op.name)} lists ${JSON.stringify(duplicate)} twice.`,
      ['Each member must appear once — a repeated member is a typo, not a wider domain.'],
    )
  }
  if (op.min !== undefined || op.max !== undefined) {
    return usage(`An enum variable has no numeric bounds: ${JSON.stringify(op.name)}.`, [
      'Drop --min/--max; an enum`s values are the --domain members.',
    ])
  }
  return { ...common, type: 'enum', domain: members }
}

/**
 * Every expression in a document that references state, as `(label, source, kind)`.
 *
 * Collected so ONE function can re-validate the whole document against a CHANGED
 * model — which is what `unstate` and a redeclaration need. Validating only the
 * expression being written would leave the other direction open: dropping a variable
 * five expressions still name, or narrowing an enum domain a constraint still
 * compares against, both produce a document whose next `check` carries an undeclared
 * reference into the encoder. That is the V14/V21 hang reached by a different route,
 * so both routes are closed.
 */
const stateExpressions = (
  document: RequirementsDocument,
): readonly {
  readonly label: string
  readonly source: string
  readonly kind: 'effect' | 'constraint'
}[] => {
  const found: { label: string; source: string; kind: 'effect' | 'constraint' }[] = []
  for (const id of Object.keys(document.requirements).sort()) {
    const requirement = document.requirements[id]
    if (requirement === undefined) continue
    const label = requirement.key ?? requirement.id
    if (requirement.stateEffect !== undefined) {
      found.push({ label, source: requirement.stateEffect, kind: 'effect' })
    }
    if (requirement.stateConstraint !== undefined) {
      found.push({ label, source: requirement.stateConstraint, kind: 'constraint' })
    }
  }
  return found
}

/**
 * Refuse a model change that would orphan an existing expression's reference.
 *
 * Reports the FIRST offender with the referencing requirement named, because that is
 * the fix site — an agent needs to know which requirement to edit, not merely that
 * something broke.
 */
const modelKeepsExpressionsValid = (
  document: RequirementsDocument,
  model: StateModel,
  what: string,
): OpFailure | undefined => {
  for (const { label, source, kind } of stateExpressions(document)) {
    const checked =
      kind === 'effect' ? validateEffect(source, model) : validateExpression(source, model, kind)
    if (isExprError(checked)) {
      return usage(`${what} would invalidate ${label}'s ${kind} "${source}": ${checked.error}`, [
        `Edit or clear ${label} first: \`symspec classify ${label} --retract\`, or \`symspec update state${kind === 'effect' ? 'Effect' : 'Constraint'} "<new expression>" --ref ${label}\`.`,
        ...checked.suggestions,
      ])
    }
  }
  return undefined
}

const applyState = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'state' }>,
): OpSuccess | OpFailure => {
  const name = op.name.trim()
  if (name.length === 0) {
    return usage('A `state` op requires a variable name.', [
      'Name the variable: `symspec state --name lock_held --type bool`.',
    ])
  }

  // THE NAME RULE, at the fold rather than only at the schema backstop on save, so the
  // refusal names the offending word (spec 007 AC-1-4). A variable or enum member spelled
  // like an expression keyword under case folding (`True`, `NOT`, `And`) lexes as that
  // keyword everywhere it is written, so it could be declared and never referenced.
  for (const candidate of [name, ...(op.type === 'enum' ? (op.domain ?? []) : [])]) {
    const trimmed = candidate.trim()
    if (trimmed.length > 0 && !STATE_VAR_NAME_PATTERN.test(trimmed)) {
      return usage(
        `${JSON.stringify(trimmed)} is not a usable state ${trimmed === name ? 'variable name' : `member of ${JSON.stringify(name)}`}.`,
        [
          'Names are identifier-shaped (letters, digits, `_`, `.`; not starting with a digit) and must not equal an expression keyword — `and`, `or`, `not`, `true`, `false`, `when` — in ANY letter case.',
          'The expression lexer folds case, so `True` reads as the literal `true` and `NOT` as the connective: a variable so named could be declared but never referenced.',
          `Rename it, e.g. ${JSON.stringify(`${trimmed}_state`)}.`,
        ],
      )
    }
  }

  const variable = stateVariableOf({ ...op, name })
  if (isOpFailure(variable)) return variable

  const existing = document.stateModel.variables.find((v) => v.name === name)
  // IDEMPOTENT on an identical redeclaration, so replaying a plan is free. Compared
  // by canonical VALUE rather than by identity, since the op path always builds a
  // fresh object.
  if (existing !== undefined && JSON.stringify(existing) === JSON.stringify(variable)) {
    return { document, noop: true }
  }

  const variables =
    existing === undefined
      ? [...document.stateModel.variables, variable]
      : document.stateModel.variables.map((v) => (v.name === name ? variable : v))
  const next: RequirementsDocument = {
    ...document,
    stateModel: { ...document.stateModel, variables },
  }

  // A REDECLARATION can narrow: bool→int, or an enum domain losing a member an
  // expression compares against. Both leave an existing expression referencing
  // something that no longer resolves, so the whole document is re-validated against
  // the new model before the write is accepted.
  if (existing !== undefined) {
    const broken = modelKeepsExpressionsValid(
      next,
      next.stateModel,
      `Redeclaring ${JSON.stringify(name)}`,
    )
    if (broken !== undefined) return broken
  }
  // The model-wide initial predicate is checked too, for the same reason.
  const initialBroken = modelInitialValid(next)
  if (initialBroken !== undefined) return initialBroken

  // SANITY GATE #1, authoring half. Reached from BOTH directions here: a new `--initial`
  // that contradicts the model-wide predicate, and a narrowed `--min`/`--max` that excludes
  // an initial value already committed. The second is the shape an author reaches by
  // bounding a variable after writing its initial, and it is exactly as vacuous as a
  // self-contradictory predicate.
  const vacuous = initialStateSatisfiable(next)
  if (vacuous !== undefined) return vacuous

  return { document: next, noop: false }
}

/**
 * Refuse a state model whose INITIAL STATE is provably unsatisfiable — the authoring-time
 * half of sanity gate #1.
 *
 * ## Why this is worth a write-time refusal when `check` already gates the run
 *
 * The solver-backed gate in `../formal/reachability.ts` is the complete answer and it fires
 * on every `check`. This closes the same hole one step earlier, where it is preventable
 * rather than merely detectable: the write is REFUSED, so the vacuous document never
 * reaches disk and the author sees the contradiction while they still remember what they
 * meant. It is the same authoring-vs-schema split `stateVariableOf` documents, and the
 * same one the existing empty-range and empty-domain refusals already use — an empty range
 * is exactly this defect reached through a different field, and it was already refused
 * here for exactly this reason.
 *
 * ## It is deliberately INCOMPLETE, and that direction is the sound one
 *
 * `cheapInitialContradiction` reports only contradictions it has PROVEN with a syntactic
 * check and gives up on everything else — see its header for the three cases and why a
 * false positive (refusing a valid document) would be strictly worse than a miss. What it
 * misses, `check` catches. So the two halves are not redundant; they are the same gate at
 * two different costs, and neither is load-bearing alone.
 *
 * Collects the SOURCE of each predicate so the message names which half to edit: the
 * per-variable `initial` and the model-wide one are set by different commands, and a
 * contradiction that exists only in their CONJUNCTION cannot be fixed without knowing
 * which one the author wants to keep.
 */
const initialStateSatisfiable = (document: RequirementsDocument): OpFailure | undefined => {
  const model = document.stateModel
  const collected: {
    expr: Parameters<typeof cheapInitialContradiction>[0][number]['expr']
    source: string
  }[] = []

  for (const variable of model.variables) {
    if (variable.initial === undefined) continue
    const parsed = validateExpression(variable.initial, model, 'initial')
    // An expression that does not VALIDATE is not this check's business — the caller has
    // already refused it, or (on a hand-edited document) `check` discloses it as skipped.
    // Silently ignoring it here is what keeps this check's failures about satisfiability
    // only.
    if (isExprError(parsed)) continue
    collected.push({ expr: parsed, source: `\`--initial\` on state ${variable.name}` })
  }
  if (model.initial !== undefined) {
    const parsed = validateExpression(model.initial, model, 'initial')
    if (!isExprError(parsed)) {
      collected.push({ expr: parsed, source: '`symspec state-initial`' })
    }
  }

  const contradiction = cheapInitialContradiction(collected, model)
  if (contradiction === undefined) return undefined
  return usage(`The state model's initial state would be UNSATISFIABLE: ${contradiction}.`, [
    'An unsatisfiable initial state means the model has NO initial state, so NO state is reachable and every constraint holds VACUOUSLY — `check` would report every constraint PROVED while proving nothing, and would MASK any real violation the document contains.',
    'Fix the contradiction: change one of the predicates, or clear the model-wide one with `symspec state-initial --clear`.',
    'Per-variable initials are CONJOINED with the model-wide one (adding either only narrows the initial states), so two individually-sensible predicates can contradict each other.',
  ])
}

/** Re-validate the model-wide initial predicate, when there is one. */
const modelInitialValid = (document: RequirementsDocument): OpFailure | undefined => {
  const initial = document.stateModel.initial
  if (initial === undefined) return undefined
  const checked = validateExpression(initial, document.stateModel, 'initial')
  if (isExprError(checked)) {
    return usage(
      `The model-wide initial predicate "${initial}" is no longer valid: ${checked.error}`,
      [
        'Update it with `symspec state-initial "<predicate>"`, or clear it with `symspec state-initial --clear`.',
        ...checked.suggestions,
      ],
    )
  }
  return undefined
}

const applyUnstate = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'unstate' }>,
): OpSuccess | OpFailure => {
  const name = op.name.trim()
  const existing = document.stateModel.variables.find((v) => v.name === name)
  // Removing an already-absent variable is a no-op success, symmetric with removing
  // an absent edge — so an `unstate` in a replayed plan does not fail the batch.
  if (existing === undefined) return { document, noop: true }

  // THE REFERENCE CHECK, from the other side. An expression naming a variable the
  // model no longer declares is exactly the state the authoring-time check exists to
  // prevent, and `unstate` is the only other way to reach it.
  //
  // An expression that ALREADY does not validate (`referencedNames` → `undefined`) is
  // deliberately NOT counted: removing a variable cannot make it worse, so blocking
  // the removal on it would strand the document. See that function's note.
  const referencing: string[] = []
  for (const { label, source, kind } of stateExpressions(document)) {
    const names = referencedNames(source, document.stateModel, kind)
    if (names?.has(name) === true) referencing.push(`${label} (${kind})`)
  }

  if (referencing.length > 0) {
    return usage(
      `Cannot undeclare ${JSON.stringify(name)} — ${referencing.length} expression(s) still reference it: ${referencing.join(', ')}.`,
      [
        'Clear or rewrite those expressions first, then undeclare the variable.',
        'Leaving them would put an UNDECLARED reference into the document, which the reachability encoder cannot encode — the failure it produces is a solver hang, not an error message (v4 findings V14/V21), so it is refused here instead.',
      ],
    )
  }

  const next: RequirementsDocument = {
    ...document,
    stateModel: {
      ...document.stateModel,
      variables: document.stateModel.variables.filter((v) => v.name !== name),
    },
  }
  const initialBroken = modelInitialValid(next)
  if (initialBroken !== undefined) return initialBroken
  return { document: next, noop: false }
}

const applyStateInitial = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'state-initial' }>,
): OpSuccess | OpFailure => {
  if (op.predicate === null) {
    if (document.stateModel.initial === undefined) return { document, noop: true }
    const model: StateModel = { variables: document.stateModel.variables }
    return { document: { ...document, stateModel: model }, noop: false }
  }

  const predicate = op.predicate.trim()
  if (predicate.length === 0) {
    return usage('An empty initial-state predicate constrains nothing.', [
      'Write a predicate, e.g. `symspec state-initial "run_state = PENDING and retry_count = 0"`.',
      'Or clear it entirely with `symspec state-initial --clear`.',
    ])
  }
  const checked = validateExpression(predicate, document.stateModel, 'initial')
  if (isExprError(checked)) {
    return usage(`The initial-state predicate "${predicate}" is not valid: ${checked.error}`, [
      ...checked.suggestions,
    ])
  }
  if (document.stateModel.initial === predicate) return { document, noop: true }
  const next: RequirementsDocument = {
    ...document,
    stateModel: { ...document.stateModel, initial: predicate },
  }
  // SANITY GATE #1, authoring half — the LOW-13 route. This is the command that most easily
  // reaches the contradiction, because the model-wide predicate is CONJOINED with every
  // per-variable one: `state-initial "held = 2"` over a variable already declared
  // `--initial "held = 0"` produces a model with no initial state, and neither half is
  // wrong on its own.
  const vacuous = initialStateSatisfiable(next)
  if (vacuous !== undefined) return vacuous
  return { document: next, noop: false }
}

const applyClassify = (
  document: RequirementsDocument,
  op: Extract<DocumentOp, { op: 'classify' }>,
  timestamp: string,
): OpSuccess | OpFailure => {
  const target = requireTarget(document, op.ref, 'ref', 'classify')
  if (isOpFailure(target)) return target

  // RETRACTION clears the label AND the expression. See `ClassifyOp` — leaving a
  // predicate behind with no label would be a decision recorded and not applied.
  if (op.kind === null) {
    if (
      target.responseKind === undefined &&
      target.stateEffect === undefined &&
      target.stateConstraint === undefined
    ) {
      return { document, id: target.id, noop: true }
    }
    const cleared: Record<string, unknown> = { ...target, updatedAt: timestamp }
    delete cleared.responseKind
    delete cleared.stateEffect
    delete cleared.stateConstraint
    return {
      document: {
        ...document,
        requirements: {
          ...document.requirements,
          [target.id]: cleared as unknown as Requirement,
        },
      },
      id: target.id,
      noop: false,
    }
  }

  const expression = op.expression?.trim()
  if (expression === undefined || expression.length === 0) {
    // A label with no expression contributes NOTHING to the encoding while looking
    // classified — the "reads as done and is not" case `ClassifyOp` documents.
    return usage(
      `Classifying ${target.key ?? target.id} as ${op.kind} requires the expression that says WHAT it ${op.kind === 'effect' ? 'changes' : 'asserts'}.`,
      [
        op.kind === 'effect'
          ? `Supply it: \`symspec classify ${target.key ?? target.id} --kind effect --expression "lock_held := true"\`.`
          : `Supply it: \`symspec classify ${target.key ?? target.id} --kind constraint --expression "not (lock_held and pending)"\`.`,
        'A responseKind with no expression contributes nothing to the reachability encoding, so it would read as classified while the solver saw no state model at all.',
        `Retract instead with \`symspec classify ${target.key ?? target.id} --retract\` if the response does not touch state.`,
      ],
    )
  }

  // THE V14/V21 FRONT DOOR. Every reference must resolve against the DECLARED model,
  // here, at write time, where the failure is an ERR_* an author can act on.
  const checked =
    op.kind === 'effect'
      ? validateEffect(expression, document.stateModel)
      : validateExpression(expression, document.stateModel, 'constraint')
  if (isExprError(checked)) {
    return usage(
      `The ${op.kind} "${expression}" on ${target.key ?? target.id} is not valid: ${checked.error}`,
      [...checked.suggestions],
    )
  }

  // Build by KEY so the unused half is genuinely ABSENT rather than `undefined` —
  // the exactOptionalPropertyTypes discipline reaching the file, which is what keeps
  // a save byte-stable and keeps a reclassification from leaving the old expression
  // behind.
  const next: Record<string, unknown> = { ...target, updatedAt: timestamp }
  next.responseKind = op.kind
  if (op.kind === 'effect') {
    next.stateEffect = expression
    delete next.stateConstraint
  } else {
    next.stateConstraint = expression
    delete next.stateEffect
  }
  const updated = next as unknown as Requirement

  if (
    target.responseKind === op.kind &&
    target.stateEffect === updated.stateEffect &&
    target.stateConstraint === updated.stateConstraint
  ) {
    return { document, id: target.id, noop: true }
  }

  return {
    document: {
      ...document,
      requirements: { ...document.requirements, [target.id]: updated },
    },
    id: target.id,
    noop: false,
  }
}

// ---------------------------------------------------------------------------
// The dispatcher
// ---------------------------------------------------------------------------

/**
 * Apply ONE op to a document, returning the new document or a typed failure.
 *
 * Exhaustive over {@link DocumentOp} by construction: every arm returns and the
 * return type admits no `undefined`, so adding a verb to the union without handling
 * it here is a compile error rather than a silently ignored op.
 */
export const applyOp = (
  document: RequirementsDocument,
  op: DocumentOp,
  timestamp: string,
  options: MutateOptions = {},
): OpSuccess | OpFailure => {
  switch (op.op) {
    case 'add':
      return applyAdd(document, op, timestamp)
    case 'update':
      return applyUpdate(document, op, timestamp)
    case 'delete':
      return applyDelete(document, op)
    case 'derive':
    case 'satisfy':
    case 'verify':
    case 'refine':
      return applyEdge(document, op, timestamp)
    case 'remove-edge':
      return applyRemoveEdge(document, op, timestamp)
    case 'glossary':
      return applyGlossary(document, op, options)
    case 'unglossary':
      return applyUnglossary(document, op, options)
    case 'antonym':
      return applyAntonym(document, op, options)
    case 'unantonym':
      return applyUnantonym(document, op, options)
    case 'waive':
      return applyWaive(document, op, options)
    case 'unwaive':
      return applyUnwaive(document, op)
    case 'state':
      return applyState(document, op)
    case 'unstate':
      return applyUnstate(document, op)
    case 'state-initial':
      return applyStateInitial(document, op)
    case 'classify':
      return applyClassify(document, op, timestamp)
    case 'term':
      return applyTerm(document, op, options)
    case 'unterm':
      return applyUnterm(document, op, options)
  }
}

// ---------------------------------------------------------------------------
// The batch fold
// ---------------------------------------------------------------------------

/** One op's entry in a fold's result array. */
export interface FoldEntry {
  /** 0-based index among the ops the fold was given. */
  readonly index: number
  readonly op: string
  readonly ok: boolean
  /** The requirement UUID the op created or targeted, when it had one. */
  readonly id?: string
  /** True when the op was an idempotent no-op. */
  readonly noop?: boolean
  readonly code?: string
  readonly error?: string
  readonly suggestions?: readonly string[]
}

/** What a fold produced. `document` is the folded result; in ATOMIC mode with any
 * failure it is the UNCHANGED input, which is what makes an abort a no-op. */
export interface FoldResult {
  readonly document: RequirementsDocument
  readonly results: readonly FoldEntry[]
  readonly summary: {
    readonly total: number
    readonly ok: number
    readonly failed: number
    readonly noop: number
  }
  /** True when the caller should PERSIST `document`. False on an atomic abort and
   * on a run where nothing actually changed. */
  readonly write: boolean
  /** The 0-based index of the op that aborted an atomic fold. Absent otherwise. */
  readonly abortedAt?: number
}

/**
 * Fold a stream of ops over a document.
 *
 * ATOMIC by default (`continueOnError: false`): every op is applied in memory, and
 * the result is only marked writable when ALL of them succeeded. Any failure
 * returns the ORIGINAL document with `write: false` and `abortedAt` set — so a
 * crashed batch leaves the file untouched and the resume story is "fix that line
 * and re-run", not "work out how far it got".
 *
 * `continueOnError: true` applies what succeeds and still marks the result
 * writable, with a per-op results array. That is the mode a repair plan wants: an
 * op that is already applied (a no-op) or that names a requirement someone deleted
 * should not block the eight repairs that do apply.
 *
 * `write` is false when nothing CHANGED even if everything succeeded — an
 * all-no-op fold has nothing to persist, and skipping the save keeps a
 * re-run from touching the file's mtime.
 */
export const foldOps = (
  document: RequirementsDocument,
  ops: readonly DocumentOp[],
  timestamp: string,
  options: MutateOptions & { readonly continueOnError?: boolean } = {},
): FoldResult => {
  const continueOnError = options.continueOnError === true
  const results: FoldEntry[] = []
  let current = document
  let changed = false
  let failed = 0
  let noops = 0

  for (let index = 0; index < ops.length; index += 1) {
    const op = ops[index]
    if (op === undefined) continue
    // Applied against `current`, NEVER against `document` — invariant 1.
    const result = applyOp(current, op, timestamp, options)

    if (isOpFailure(result)) {
      failed += 1
      results.push({
        index,
        op: op.op,
        ok: false,
        code: result.code,
        error: result.error,
        suggestions: result.suggestions,
      })
      if (!continueOnError) {
        return {
          // The ORIGINAL — an atomic abort writes nothing.
          document,
          results,
          summary: { total: ops.length, ok: index, failed: 1, noop: noops },
          write: false,
          abortedAt: index,
        }
      }
      continue
    }

    current = result.document
    if (result.noop) noops += 1
    else changed = true
    results.push({
      index,
      op: op.op,
      ok: true,
      ...(result.id !== undefined ? { id: result.id } : {}),
      ...(result.noop ? { noop: true } : {}),
    })
  }

  return {
    document: current,
    results,
    summary: {
      total: ops.length,
      ok: results.filter((r) => r.ok).length,
      failed,
      noop: noops,
    },
    write: changed,
  }
}

/**
 * WAIVABILITY, as data the domain can read: every finding code's class, and which classes a
 * waiver may suppress (spec 007 AC-5-6, S3).
 *
 * The table lives in the domain ring because the two places that ENFORCE it are domain code:
 * the boundary projection `compat.ts` (`toEngineDoc` forwards no stored waiver the policy
 * refuses) and the write-time classifier `app/operations/mutate-options.ts` hands the fold. The
 * ring rule (`package-boundary.test.ts`) lets `app/` read `domain/` and never the reverse, so a
 * table under `app/runtime/` would leave the check-time half unable to see it.
 * `app/runtime/signal-classes.ts` re-exports every name here, beside the demotion classes and
 * the published enforcement flag, so the manifest, `explain` and AGENTS.md read one table.
 */

import type { FND_CODES } from './engine/formal/codes.ts'
import { GTWR_CODES } from './engine/lint/codes.ts'
import type { REACHABILITY_FND_CODES } from './reachability/reachability-codes.ts'
