 const args=[binary,'check',file];const r=spawnSync(process.execPath,args,{encoding:'utf8',env:process.env});const payload=JSON.parse(r.stdout)
 const d=payload.data;product.push({label,exitCode:r.status,type:payload.type,reachabilityVariables:d?.reachability?.variables,findings:d?.findings?.filter((f:any)=>f.code.startsWith('FND_REACHABILITY')).map((f:any)=>({code:f.code,message:f.message.replaceAll(file,'<doc>'),repair:f.repair?JSON.parse(JSON.stringify(f.repair).replaceAll(file,'<doc>')):null})),demotions:d?.coverage?.demotions?.filter((f:any)=>f.reason.startsWith('reachability')).map((f:any)=>JSON.parse(JSON.stringify(f).replaceAll(file,'<doc>')))})
}
