console.log(JSON.stringify({sourceSha256:hash(readFileSync('./src/domain/reachability/reachability-report.ts','utf8')),bundleSha256:hash(readFileSync(binary,'utf8')),producerCases:20000,producerHash:producer.digest('hex'),broadCases:20000,broadHash:broad.digest('hex'),projection,product}))

