import {createHash} from 'node:crypto'
import {toEngineDoc} from './src/domain/compat.ts'
import {decodeDocument} from './src/domain/requirements/document.ts'
import {buildGlossaryPlan} from './src/domain/glossary/glossary-plan.ts'
const base=JSON.parse(readFileSync('./src/testing/__fixtures__/s3-waivability/base.json','utf8'))
const template=Object.values(base.requirements)[0] as Record<string,unknown>
const requirements=Object.fromEntries(['reconcile the ledger','settle the accounts'].map((response,i)=>{
 const id=`10000000-0000-4000-8000-${String(i+1).padStart(12,'0')}`
 return [id,{...template,id,key:`PLAN-R${i+1}`,patternType:'event-driven',trigger:'the day closes',systemName:'ledger service',systemResponse:response,sentence:`When the day closes, the ledger service shall ${response}.`}]
}))
const raw={...base,requirements,antonyms:[],terms:[],waivers:[],stateModel:{variables:[]},glossary:[{canonical:'reconcile the ledger',aliases:['reconcile the books']},{canonical:'settle the accounts',aliases:['settle the balances']}]}
const doc=Effect.runSync(decodeDocument(raw)).document
const plan=await buildGlossaryPlan(toEngineDoc(doc),async texts=>texts.map(()=>Float32Array.from([1,0])))
const held=plan.unresolved.find(u=>u.reason==='existing-canonical-conflict')
if (!held)throw Error('expected existing-canonical-conflict: '+JSON.stringify(plan))
const match=/`(symspec glossary[^`]+)`/.exec(held.message)
if(!match)throw Error('no command '+held.message)
const out=resolve(process.argv[2]!);mkdirSync(out,{recursive:true})
const file=resolve(out,'requirements.json');writeFileSync(file,JSON.stringify(raw)+'\n')
const suggested=match[1]!
if(out.includes('mutant')&&!suggested.includes('glossary add'))throw Error('mutant not active: '+suggested)
const args=['glossary',...(suggested.includes('glossary add')?['add']:[]),'--remove','reconcile the ledger','reconcile the books','--file',file]
const binary=resolve('dist/cli.mjs');const result=spawnSync(process.execPath,[binary,...args],{encoding:'utf8',env:process.env})
let response:unknown=result.stdout;try{response=JSON.parse(result.stdout)}catch{}
console.log(JSON.stringify({input:raw,held,suggested,sourceSha256:createHash('sha256').update(readFileSync('./src/domain/glossary/glossary-plan.ts')).digest('hex'),bundleSha256:createHash('sha256').update(readFileSync(binary)).digest('hex'),command:[process.execPath,binary,...args],exitCode:result.status,stdout:response,stderr:result.stderr}))

