const schema=Schema.toJsonSchemaDocument(RequirementsDocument)
const descriptions:{path:string,text:string}[]=[]
function visit(value:unknown,path='$') {
 if (typeof value!=='object'||value===null)return
 for (const [key,v] of Object.entries(value)) {
  if (key==='description'&&typeof v==='string'&&v.includes('this one checks'))descriptions.push({path:path+'.description',text:v})
  else visit(v,path+'.'+key)
 }
}
visit(schema)
