import pathlib,json,hashlib,subprocess,re
ROOT=pathlib.Path(__file__).resolve().parent
HEAD='2d3e5fe3368d8a2166f50a32156c26734df253e8'
sources={};problems=[];rows=[];checked_logs=set()
def sha(s):return hashlib.sha256(s).hexdigest()
def source(file):
 if file not in sources:sources[file]=subprocess.check_output(['git','-C',str(ROOT/'attack-copy'),'show',HEAD+':'+file]).decode()
 return sources[file]
def immutable_logs(obj,context):
 if isinstance(obj,list):
  for v in obj:immutable_logs(v,context)
 elif isinstance(obj,dict):
  for key in ('log','report'):
   path=obj.get(key);want=obj.get(key+'Sha256')
   if isinstance(path,str) and isinstance(want,str) and path.startswith('/'):
    pair=(path,want)
    if pair not in checked_logs:
     checked_logs.add(pair);p=pathlib.Path(path)
     if not p.exists() or sha(p.read_bytes())!=want:problems.append(f'{context}: stale/missing {key} {path}')
  for v in obj.values():immutable_logs(v,context)
def audit(m,campaign):
 if m.get('status') is None:return
 label=campaign+':'+m['id'];file=m['file'];s=source(file)
 if sha(s.encode())!=m['sourceSha256']:problems.append(label+': source hash does not match tested HEAD')
 match=re.fullmatch(r'(.+):(\d+):(\d+)-(\d+):(\d+)',m['span'])
 if not match:problems.append(label+': malformed span');return
 _,a,b,c,d=match.groups();lines=s.splitlines(keepends=True)
 start=sum(map(len,lines[:int(a)-1]))+int(b)-1;end=sum(map(len,lines[:int(c)-1]))+int(d)-1
 if s[start:end]!=m['original']:problems.append(label+': span differs from original')
 mutated=s[:start]+m['replacement']+s[end:]
 if sha(mutated.encode())!=m['mutantSha256']:problems.append(label+': reconstructed mutant hash mismatch')
 if m['status'] in ('killed','survived'):
  runs=m['runs']
  if len(runs)!=2 or any(r.get('status')!=m['status'] for r in runs):problems.append(label+': not two identical statuses')
  if m.get('stable') is not True:problems.append(label+': missing stability assertion')
  if m['status']=='killed' and not m.get('killedBy'):problems.append(label+': kill without killing test')
 immutable_logs(m,label)
 rows.append({'campaign':campaign,'id':m['id'],'file':file,'status':m['status'],'control':m.get('control',False)})
paths=[('new-parent',ROOT/'results.json'),('new-extra',ROOT/'extras/results.json')]
paths += [(str(job),ROOT.parent/f'job-{job}'/'result.json') for job in (1118,1119,1120)]
for label,p in paths:
 if not p.exists():continue
 j=json.loads(p.read_text());mutants=j if isinstance(j,list) else j.get('mutants',[])
 for m in mutants:audit(m,label)
 if isinstance(j,dict):
  for m in j.get('controls',[]):audit(m,label+'-control')
report={'head':HEAD,'finishedMutants':len(rows),'sourceFilesChecked':len(sources),'immutableLogHashesChecked':len(checked_logs),'mutants':rows,'problems':problems,'pass':not problems}
(ROOT/'mutation-audit-progress.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:v for k,v in report.items() if k!='mutants'},indent=2))
raise SystemExit(bool(problems))

import pathlib,json,hashlib
ROOT=pathlib.Path(__file__).resolve().parent
checked=set();problems=[];reconciled=[]
def walk(v):
 if isinstance(v,list):
  for x in v:walk(x)
 if isinstance(v,dict):
  if isinstance(v.get('path'),str) and isinstance(v.get('sha256'),str):
   p=pathlib.Path(v['path']);pair=(str(p),v['sha256'])
   if pair not in checked:
    checked.add(pair)
    if not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest()!=v['sha256']:
     snapshot=ROOT/'C20-reviewed-mutants.json'
     if p==ROOT/'mutants.json' and snapshot.exists() and hashlib.sha256(snapshot.read_bytes()).hexdigest()==v['sha256']:
      reconciled.append({'originalPath':str(p),'sha256':v['sha256'],'snapshotPath':str(snapshot),'reason':'Queue changed at recorded tail rebalance by appending C23. Exact reviewed bytes reconstructed by omitting that appended item; SHA256 matches reviewer evidence.'})
     else:problems.append(pair)
  for x in v.values():walk(x)
complete=[]
for j in (1148,1152):
 p=ROOT.parent/f'job-{j}/result.json'
 if not p.exists():continue
 walk(json.loads(p.read_text()));complete.append(j)
out={'jobs':complete,'hashesChecked':len(checked),'reconciledMutableQueues':reconciled,'problems':problems,'passed':not problems}
(ROOT/'judgment-audit.json').write_text(json.dumps(out,indent=2)+'\n')
